import type { MvBook } from '../molytvoslov';
const D: MvBook[] = [{"u":"Канон преподобному Іову, ігумену Почаївському","e":"Canon to St Job, Abbot of Pochaiv","secs":[{"h":"Глас 8. Пісня 1","ps":["Ірмос: Посіче́нний несіко́маго пресіче́, і ви́ді со́лнце зе́млю, ю́же не ви́ді; лю́таго врага́ вода́ потопи́, і непроходи́моє про́йде Ізра́їль; піснь же воспіва́шеся: Го́сподеві пої́м, сла́вно бо просла́вися.","Приспів: Преподо́бне о́тче наш І́ове, моли́ Бо́га о нас.","А́нгела земна́го і Небе́снаго челові́ка, І́ова преподо́бнаго, Воли́нськую похвалу́, досто́йно воспі́ти помози́ мі, Сло́ве Бо́жий, презира́я моя́ прегріше́нія і подава́я сло́во усто́м мої́м.","Приспів: Преподо́бне о́тче наш І́ове, моли́ Бо́га о нас.","Бил єси́, Преподо́бне, воі́стину ми́ру світи́льник пресві́тел, всім путь спасе́нія показу́яй; ті́мже і мні бу́ди помо́щник, во є́же просла́вити житіє́ твоє́ і умиле́ніє стяжа́ти.","Приспів: Преподо́бне о́тче наш І́ове, моли́ Бо́га о нас.","В дому́ роди́телей твої́х пе́рвіє позна́л єси́ Го́спода, І́ове сла́вне, і, о́трок сий, ра́зум соверше́н показа́л єси́, єгда́ мона́шеськоє житіє́ ізво́лил єси́, вся же жите́йськая прови́дів, Єди́наго Бо́га возлюби́л єси́.","Приспів: Преподо́бне о́тче наш І́ове, моли́ Бо́га о нас.","Го́ре о́чі твої́ і ду́шу вознося́, во оби́телі Уго́рництій бра́тію в Богоуго́днім житії́ ско́ро превозше́л єси́, ху́ждша всіх себі́ помишля́я і тім лу́чшій Ісу́су явля́яся, ста́рцем же і ю́ним о́браз бив прелюбезні́йший.","Слава: До́брі тя на дия́воли во́їнствовавша помишля́я, Преподо́бне, своєя́ стижду́ся лі́ності і мно́жества гріхо́в мої́х ужаса́юся: но твої́ми, свя́те, моли́твами да́руй мі жела́ніє благо́є, во є́же про́чеє вре́м'я житія́ моєго́ в покая́нії сконча́ти.","І нині: Я́ко Бо́жия Ма́ти дерзнове́ніє іму́щи к ро́ждшемуся із Тебе́ Єдиноро́дному Сло́ву, і Отцю́ Собезнача́льному, і Соєсте́ственному Ду́ху моля́щи не преста́й от бід спасти́, Всенепоро́чная, Тя, Богоро́дицю, сла́в'ящия."]},{"h":"Пісня 3","ps":["Ірмос: Утверди́ся се́рдце моє́ во Го́споді, вознесе́ся рог мой в Бо́зі моє́м, разшири́шася на враги́ моя́ уста́ моя́, возвесели́хся о спасе́нії Твоє́м.","Приспів: Преподо́бне о́тче наш І́ове, моли́ Бо́га о нас.","Єсть во мні, о́тче Преподо́бне, до́браго ісправле́нія жела́ніє, но іскуше́нія лі́ності побіжда́ти не навико́х, уви́ мні. Оба́че на по́мощ твою́ наді́яся, уни́нія по́мисли отгоня́ю, на твоя́ же взира́ю сла́вния по́двиги.","Приспів: Преподо́бне о́тче наш І́ове, моли́ Бо́га о нас.","Желі́зо нарече́ся род твой, І́ове Преподо́бне, крі́пость душі́ твоєя́ предуказу́я; в пеще́рі же ка́менні заключи́вся, я́ко зла́то сокрове́но, освяти́л єси́ мі́сто по́двиг твої́х і го́ру Поча́євськую, я́ко сті́ну мі́дяну, проти́ву враго́в Правосла́вія яви́л єси́.","Приспів: Преподо́бне о́тче наш І́ове, моли́ Бо́га о нас.","Зіло́ углуби́шася помишле́нія твоя́ я́же о Небе́снім Ца́рствії, єгда́, єще́ о́трок сий, А́нгельський о́браз восприя́л єси́; ті́мже і свяще́нник бив Бо́гу ві́рен, да́же ни́ні моле́нія о лю́діх возно́сиши, І́ове Преподо́бне.","Приспів: Преподо́бне о́тче наш І́ове, моли́ Бо́га о нас.","Земля́ Га́лицькая ю́ностію твоє́ю сла́виться, і Ду́бенськая оби́тель му́жеськия по́двиги твоя́ благовіству́єть, оби́тель же Поча́євськая ста́ростію твоє́ю хва́литься і блаже́нною кончи́ною весели́ться, вся же вселе́нная о чудесі́х твої́х ра́дується і ликовству́єть.","Слава: І́же подає́ши блага́я всім, моля́щимся тебі́, і мене́ припа́дающа не отри́ни свя́тче, но, покая́ніє моє́ зря, даждь мі житія́ ісправле́ніє, ре́вность же вдохни́, є́же подража́ти твої́м Боголюби́вим дія́нієм.","І нині: Умерщвле́нний мой ум Живо́тним ді́йством із Тебе́, Я́вльшимся ми́ру, воздви́гни, Чи́стая, і к жи́зні наста́ви, Я́же сме́рті две́рі разо́ршая Єди́на Рождество́м Твої́м."]},{"h":"Сідален, глас 8","ps":["Днесь ісполня́ється ра́дости оби́тель Поча́євськая, твоє́ Боголюби́воє житіє́ прославля́ющи; днесь христоимени́тії лю́діє ре́вностію спасе́нія просвіща́ються, зря́ще нетлі́нієм просла́вленния мо́щі твоя́, преподо́бне; днесь гріхо́вния отгоня́ються стра́сті, і по́мисли покая́нія душі́ на́ша об'є́млють, в ни́хже утверди́ всіх, пресла́вне, ві́рно почита́ющих па́м'ять твою́.","Слава, і нині:","Я́ко Всенепоро́чная Неві́ста Творця́, я́ко Неіскусому́жная Ма́ти Ізба́вителя, прия́телище я́ко су́щи Уті́шителя, Всепі́тая, беззако́нія м'я су́ща скве́рноє оби́телище і де́монов ігра́лище в ра́зумі би́вша, потщи́ся от тіх злоді́йства м'я ізба́вити і сві́тлоє жили́ще доброді́телей соверши́, Світоно́сная Нетлі́нная, отжени́ о́блак страсте́й, і Ви́шняго прича́стія сподо́би, і Сві́та Невече́рняго моли́твами Твої́ми."]},{"h":"Пісня 4","ps":["Ірмос: Проро́к Авваку́м у́мнима очи́ма прови́ді, Го́споди, Прише́ствіє Твоє́, тім і вопія́ше: от ю́га при́йдеть Бог. Сла́ва си́лі Твоє́й, сла́ва снизхожде́нію Твоєму́.","Приспів: Преподо́бне о́тче наш І́ове, моли́ Бо́га о нас.","І́ове Преподо́бне, о всіх моли́твенник бу́ди те́плий, твоєму́ заступле́нію ві́рующих, своє́ же окаява́ющих житіє́ і на Бо́жиє милосе́рдіє упова́ющих, а́ще і прельще́ньми житія́ сего́ вла́ющихся.","Приспів: Преподо́бне о́тче наш І́ове, моли́ Бо́га о нас.","Кто от челові́к не подиви́ться долготерпіли́вому житію́ твоєму́, о́тче, кто ли не просла́вить твоєя́ о Правосла́вії ре́вности, ти бо, я́ко адама́нт крі́пок, єретико́м противоста́л єси́, і і́стинния ві́ри пропові́даніє словеси́ же і писа́ньми всім препо́дал єси́.","Приспів: Преподо́бне о́тче наш І́ове, моли́ Бо́га о нас.","Льва рика́юща і і́щуща поглоти́ти ду́ші спаса́ємих моли́твою твоє́ю побіди́л єси́, о́тче, но і тому́ служа́щия лю́ди в покая́ніє приводи́л єси́, та́ти милосе́рдієм твої́м постижда́я і вразумля́я, граби́телі же обличе́ньми устраша́я і вся науча́я спаси́тельному покая́нію.","Слава: Мрак душі́ моєя́, о́тче, предста́тельством твої́м разсі́й і сві́том за́повідей Госпо́дніх просвіти́ моє́ окая́нноє се́рдце, да і аз, твої́м ученико́м послі́дуя, тіх ча́сти лише́н не пребу́ду, твою́ восхваля́я святу́ю па́м'ять.","І нині: Бо́га, із Тебе́ воплоще́ннаго, моли́ непрело́жно, Є́же бі преби́вша і єсте́ственно Ра́вна Отцю́, і Ду́ху Сопресто́льна, проще́ніє прегріше́ній і душ спасе́ніє пою́щим Тя ві́рою дарова́ти."]},{"h":"Пісня 5","ps":["Ірмос: Мрак душі́ моєя́ разжени́, Світода́вче Христе́ Бо́же, началоро́дную тьму ізгна́в бе́здни, і да́руй мі світ повелі́ній Твої́х, Сло́ве, да, у́тренюя, сла́влю Тя.","Приспів: Преподо́бне о́тче наш І́ове, моли́ Бо́га о нас.","Наш єси́ воі́стину предста́тель і чудотво́рець пресві́тлий, взива́ше Діони́сій, обріти́й мо́щі твоя́, тлі́нію неприча́стни. Ми же, сія́ лобиза́юще, вопіє́м: на́ших скверн не возгнуша́йся, уго́дниче Бо́жий, но твої́ми моли́твами сія́ очи́сти.","Приспів: Преподо́бне о́тче наш І́ове, моли́ Бо́га о нас.","Оправда́нієм Бо́жиїм от ю́ности, о́тче, науча́єм, суєти́ жите́йськія уклони́тися крі́пко возжела́л єси́, безмо́лвіє же возлюби́л єси́: оба́че велі́нію Христо́ву не противля́яся, притека́ющия к тебі́ Пра́вому іспові́данію і Єва́нгельському житію́ науча́л єси́.","Приспів: Преподо́бне о́тче наш І́ове, моли́ Бо́га о нас.","Предста́тель яви́лся єси́ і по преставле́нії твоє́м стра́ждущим і скорб'я́щим челові́ком: та́ко бо тя ви́діша лю́діє, із гро́ба твоєго́ ісходя́ща і со А́нгели посреді́ це́ркве моля́щася. О, чу́до пресла́вноє воі́стину! О, ра́дость ві́рним і утвержде́ніє!","Приспів: Преподо́бне о́тче наш І́ове, моли́ Бо́га о нас.","Рачи́тель бив Небе́снаго Ца́рствія, о своє́м та́мо вхожде́нії ізвіству́єшися і кромі́ болі́зні і стра́ха пресе́льник явля́єшися лу́чшія жи́зні, бра́тії же твоєя́ учи́тель і упова́ніє.","Слава: Сопу́тник житію́ моєму́ бу́ди, о́тче І́ове, моли́твою твоє́ю огражда́й многом'яте́жную мою́ ду́шу і введи́ ю в Небе́сноє Ца́рство, твої́ми умиле́нную по́двиги, Христу́ же покая́нния принося́щую сле́зи.","І нині: Тя сті́ну іму́ще і предста́тельством Твої́м соблюда́єми, Твоє́ю Боже́ственною сла́вою хва́лящеся, Тя блажи́м: Ти бо, Всечи́стая, душа́м на́шим істоча́єши весе́ліє і ра́дованіє."]},{"h":"Пісня 6","ps":["Ірмос: Іо́ну в ки́ті, Го́споди, єди́наго всели́л єси́, мене́ же свя́зана мре́жами вра́жіїми, я́ко от тлі о́наго спаси́.","Приспів: Преподо́бне о́тче наш І́ове, моли́ Бо́га о нас.","Тве́рдоє упова́ніє на предста́тельство твоє́ возлага́ю, преподо́бне, і ві́рою молю́ся: даждь мі страсте́й лю́тих одолі́ніє, сме́рті же непреста́нную па́м'ять і блаже́нства жела́ніє гряду́щаго ві́ка.","Приспів: Преподо́бне о́тче наш І́ове, моли́ Бо́га о нас.","Утвержда́ється тобо́ю, Преподо́бне, Свята́я Це́рков, є́ресь же вся́кая посрамля́ється, обличе́ніє іму́щи твоя́ многоціле́бния мо́щі, і житія́ твоєго́ столі́тняго труди́, і болі́зні, і сле́зи, і пост, і пло́ті от косте́й отпаде́ніє.","Приспів: Преподо́бне о́тче наш І́ове, моли́ Бо́га о нас.","Фарао́на ми́сленнаго побіжда́ше І́ов преподо́бний, послуша́нію всегда́ приліжа́ і обурева́ємим на по́мощ приходи́ти не отриця́яся: і та́ко три оби́телі уче́нієм свої́м просвіти́в і по́двиги мно́гими просла́вив, веселя́ше Спа́са всіх, Человіколю́бця.","Приспів: Преподо́бне о́тче наш І́ове, моли́ Бо́га о нас.","Христо́ву смире́нію подража́ше І́ов, єгда́ нача́льство я́ко служе́ніє всім прия́т і, ігу́мен сий, в тя́жких слу́жбах подвиза́шеся, бра́тії же бя́ше о́браз кро́тости, і трудолю́бія пра́вило, і о моли́тві при́сноє напомина́ніє.","Слава: От скве́рних ізба́ви м'я страсте́й твої́ми моли́твами, тіх одолі́ніє мні подава́я Боже́ственния по́мощі при́сним призива́нієм, і на себі́ ненаді́янієм, і бра́та моєго́ неосужде́нієм.","І нині: Вознесла́ єси́ всеї́стинно па́дшеє челові́чеськоє существо́ во зра́ці Боже́ственном, і Отця́ в ра́венстві ви́димаго Си́на неізмі́ннаго, Богома́ти, без Сі́мене во чре́ві поноси́вши."]},{"h":"Кондак, глас 4","ps":["Яви́лся єси́ і́стинния ві́ри столп, Єва́нгельських же за́повідей ревни́тель, горди́ні обличе́ніє, смире́нним же предста́тель і науче́ніє: ті́мже і ублажа́ющим тя гріхо́в отпуще́ніє іспроси́ і оби́тель твою́ невріди́му сохрани́, І́ове о́тче наш, Многострада́льному подо́бний."]},{"h":"Ікос","ps":["Отве́рзи уста́ твоя́, пеще́ро ка́менная, і рци нам, колькра́ти то́ки слез І́овлих омочи́лася єси́, ка́ко того́ воздиха́нія твої́х стін не расторго́ша, ка́ко Світ Боже́ственний тебі́ не сожже́, ка́ко А́нгели бді́нним по́двигом І́овлим диви́шася, ті́ми бо освяти́ся земля́ Га́лицькая і Воли́нськая; ми же, сія́ вся помишля́юще, слеза́ми умиле́нія о́чі на́ші ісполня́єм: єсть бо преподо́бний І́ов уго́дник ди́вний, Многострада́льному подо́бний."]},{"h":"Пісня 7","ps":["Ірмос: На по́лі Деї́рі іногда́ мучи́тель пещ поста́ви на муче́ніє Богоно́сних, в не́йже три о́троки пісносло́в'яху Єди́наго Бо́га, тро́їчно воспіва́ху, глаго́люще: отце́в Бо́же, благослове́н єси́.","Приспів: Преподо́бне о́тче наш І́ове, моли́ Бо́га о нас.","Лю́ди правосла́вния, тя блажа́щия, преподо́бне І́ове, укріпи́ на враги́ і о Це́ркві ми́рная глаго́ли в се́рдці їх, всім єдиноми́сліє іспроси́ у Бо́га, і друг ко дру́гу любо́в, і о Правосла́вії ре́вность.","Приспів: Преподо́бне о́тче наш І́ове, моли́ Бо́га о нас.","Ча́шу житія́ Твоєго́ пи́ти, Го́споди, не могу́ аз, окая́нний, боя́знію скорбе́й обурева́єм і страсте́й сплета́єм те́рнієм, оба́че молю́ся: І́ова, Твоєго́ уго́дника, моли́твами поми́луй м'я і помози́ мі гріхо́вную отрясти́ лі́ность.","Приспів: Преподо́бне о́тче наш І́ове, моли́ Бо́га о нас.","Широ́кий путь, поги́бель душі́ преднося́щий, возненави́дів, І́ове Преподо́бне, в ті́сній пеще́рі заключи́лся єси́ і ті́снаго путі́ жи́зні в нача́льстві твоє́м не уклони́лся єси́, день і нощ в моли́тві і труді́х пребива́я і науче́ніє здра́воє всім приходя́щим к тебі́ подава́я.","Слава: Щедр бил єси́ ни́щим, ка́ющимся же ми́лостив і науче́нія тре́бующим учи́тель кро́ток, Боже́ственния же му́дрости люби́тель і Єва́нгельських за́повідей пропові́дник, книг же Боже́ственних ізда́тель і є́ресі безбоя́зненний обличи́тель.","І нині: Марі́ю Пречи́стую і Всесвяту́ю восхва́лим: То́ю бо благода́ть нам істоча́ється па́че ума́ даро́в, я́ко от пото́ка Боже́ственния бла́гости, Ю́же благочести́вим по́мислом ни́ні ублажа́єм."]},{"h":"Пісня 8","ps":["Ірмос: Покрива́яй вода́ми преви́спренная Своя́, полага́яй мо́рю преді́л песо́к і содержа́й вся, Тя поє́ть со́лнце, Тя сла́вить луна́, Тебі́ прино́сить піснь твар, я́ко Соді́телю всіх во ві́ки.","Приспів: Преподо́бне о́тче наш І́ове, моли́ Бо́га о нас.","Є́дущим і іду́щим во оби́тель твою́ безчи́сленним лю́дем, ко твої́м же моще́м припа́дающим, бу́ди дарова́ній духо́вних пода́тель, тіле́сних же болі́зней ціли́тель і пред Спа́сом те́плий о всіх предста́тель, І́ове, землі́ Воли́нськия сла́во і украше́ніє.","Приспів: Преподо́бне о́тче наш І́ове, моли́ Бо́га о нас.","Ю́ноша ті́лом, но ста́рець умо́м в нача́лі мона́шеськаго житія́ твоєго́ бил єси́, о́тче: соста́рівся же пло́тію, ю́ношеськую бо́дрость в труді́х явля́л єси́, землі́ копа́нієм і древе́с насажде́нієм о́браз всім смиренному́дрія подава́я.","Приспів: Преподо́бне о́тче наш І́ове, моли́ Бо́га о нас.","Явле́ніє твоє́ со А́нгели вку́пі смире́нную ді́ву ужаса́ше, здра́віє же ученику́ твоєму́ подава́ше і вся лю́ди на славосло́віє Бо́гові воздвиза́ше, І́стинную же утвержда́ше в них ві́ру і єрети́чеськая отріва́ше нападе́нія.","Слава: Фимія́мом моли́тв твої́х і мене́ облагоуха́й, І́ове пресла́вне, мої́х гріхо́в злосмра́діє тім отгоня́я і упова́ніє на Го́спода вселя́я в мою́ смра́дную ду́шу, да благода́тію Бо́жиєю очища́єм, воспою́ твоє́, преблаже́нне, крі́пкоє заступле́ніє.","І нині: Богороди́тельнице Всечи́стая, душі́ моєя́ я́зви і гріхо́вния стру́пи очи́сти, істо́чником омива́ющи су́щим із ребр Си́на Твоєго́, і поте́кшими із тіх, очища́ющи, струя́ми: к Тебі́ прибіга́ю і Тя призива́ю, Богоблагода́тную."]},{"h":"Пісня 9","ps":["Ірмос: Благослове́н Госпо́дь, Бог Ізра́їлев, воздви́гнувий рог спасе́нія нам в дому́ Дави́дові, о́трока Своєго́ в ни́хже посіти́ нас Восто́к с висоти́ і напра́вил ни єсть на путь ми́ра.","Приспів: Преподо́бне о́тче наш І́ове, моли́ Бо́га о нас.","Іссо́пом благода́ті Бо́жия окропи́ сердця́ на́ша, І́ове Преподо́бне, твої́м святи́м моще́м покланя́ющихся, да твоєя́ ре́вности о ві́рі причасти́вшеся, к ісполне́нію за́повідей Христо́вих до́брі потщі́мся.","Приспів: Преподо́бне о́тче наш І́ове, моли́ Бо́га о нас.","Псало́мськи взива́ти к Бо́гу на землі́ не престава́л єси́, і ді́вства твоєго́ сосу́д соблю́л єси́: ті́мже на Небесі́ ра́йськия воспіва́єши ни́ні пі́сні со А́нгели і всі́ми святи́ми, лю́ди же, на землі́ трудя́щияся, от Ви́шніх назира́єши.","Приспів: Преподо́бне о́тче наш І́ове, моли́ Бо́га о нас.","О, коли́ка житія́ твоєго́ нетлі́нная красота́, о, коли́ка по сме́рті твоє́й чудеса́ і ісціле́нія! Се бо земна́я оста́вив, воі́стину стори́цею Небе́сная бла́га єще́ в житії́, па́че же во гряду́щем, по глаго́лу Христо́ву стяжа́л єси́.","Слава: О, коли́ко гріхо́в на́ших мно́жество! Но сія́ превосхо́дить твої́х моли́тв крі́пость, ї́хже не лиши́ нас, о́тче Преподо́бне І́ове, дру́же Христо́в і святи́х всіх соприча́стниче, церко́вний сто́лпе і о душа́х челові́чеських предста́телю теплі́йший.","І нині: Зачала́ єси́, Ді́во, без сі́мене, вся́чеськая созда́вшаго Сло́во Бо́жиє, кромі́ хоті́ній плотськи́х, і без істлі́нія родила́ єси́, без болі́зней ма́терніх. Тім Тя, Богоро́дицю, і язи́ком, і се́рдцем іспові́дающе, велича́єм."]}],"notes":[]},{"u":"Канон преподобномучениці Євгенії Римській","e":"Canon to the Venerable Martyr Eugenia of Rome","secs":[{"h":"Глас 2. Пісня 1","ps":["Ірмос: Во глубині́ постла́ іногда́ фараони́тськоє всево́їнство преоруже́нная си́ла, вопло́щшеєся же Сло́во всезло́бний гріх потреби́ло єсть, препросла́вленний Госпо́дь, сла́вно бо просла́вися.","Приспів: Свята́я преподобному́ченице Євге́ніє, моли́ Бо́га о нас.","Євге́ніє, му́ченице Христо́ва, ни́ні ликовству́ющи ра́достно со а́нгельськими во́їнстви, я́ко ді́ва непоро́чна і я́ко му́чениця, вінцено́сиця всебога́тая, благода́ть дарова́ти моли́ся любо́вію воспіва́ющим тя.","Приспів: Свята́я преподобному́ченице Євге́ніє, моли́ Бо́га о нас.","Піснопі́нія, неві́сто Христо́ва, боже́ственнаго послу́шавши, к висо́кому впери́лася єси́ благоро́дію: я́ко бо світ возсія́ в се́рдці твоє́, пі́сней Ду́ха богосло́віє, вся́ко безбо́жіє отгоня́.","Приспів: Свята́я преподобному́ченице Євге́ніє, моли́ Бо́га о нас.","Же́нськоє єстество́ твой ум заби́в, к му́жеським дія́нієм востече́, вмужи́вся благода́тію, і Бо́гу проми́сленні управля́яся, му́ченице Євге́ніє, боже́ственнаго благоро́дія тезоімени́тная.","Осія́вшися сві́том у́мним, мно́жайшия осія́нія сопричасти́тися соді́лала єси́, богому́драя; єго́же ни́ні пою́щия тя ізбавля́ющи гріха́, сподо́би твої́ми мольба́ми, му́ченице Євге́ніє всеблаже́нная.","Богородичен: Умерщвле́ни би́вше зна́нія са́дом, дре́вом жи́зні, Чи́стая, к жи́зні, ві́рнії, воззва́хомся, із Тебе́ прозя́бшим па́че сми́сла, Богоро́дице, Христо́м Бо́гом; Єму́же со дерзнове́нієм моли́ся спасти́ся душа́м на́шим."]},{"h":"Пісня 3","ps":["Ірмос: На ка́мені м'я ві́ри утверди́в, разшири́л єси́ уста́ моя́ на враги́ моя́, возвесели́бося дух мой, внегда́ пі́ти: ність свят, я́коже Бог наш, і ність пра́веден, па́че Тебі́, Го́споди.","Приспів: Свята́я преподобному́ченице Євге́ніє, моли́ Бо́га о нас.","Я́коже же́ртва непоро́чна Влади́ці принесла́ся єси́ ми́слію соверше́ннійшею і бога́тство тлі́ємоє отри́нула єси́, вопію́щи, всему́драя: Ти єси́ Бог наш, і ність свят, па́че Тебі́, Го́споди.","Приспів: Свята́я преподобному́ченице Євге́ніє, моли́ Бо́га о нас.","Всечи́стая, позна́ся твоя́ чистота́, просія́ страда́ній Твої́х крі́пость, дія́ніє бо восхожде́ніє виді́нія соді́лала єси́, вопію́щи: Ти єси́ Бог наш, і ність свят, па́че Тебі́, Го́споди.","Цілому́дрія жела́нієм одержа́ся, соблюла́ єси́ хвалу́ чистоти́, била́ єси́ прия́тна прему́дрости, Христу́ вопію́щи: Ти єси́ Бог наш, і ність свят, па́че Тебі́, Го́споди.","Богородичен: Марі́ю, Пречи́стую Богоро́дицю, воспої́м, я́ко Хода́таїцю спасе́нія я́вльшуюся, богому́дрії, і вопіє́м: ність чи́сти, я́коже Ти, Пречи́стая, і ність непоро́чни, па́че Тебе́, Влади́чице."]},{"h":"Сідален, глас 8","ps":["Воздержа́вшися в труді́х страда́льчеських, просла́вилася єси́ по́двиги му́ченичеськими, мно́гі приве́дши спаса́ємия Зижди́телю твоєму́: боже́ственною бо любо́вію оста́вивши привре́менная, му́жеськия по́двиги соверши́ла єси́, сла́вная. Ті́мже по кончи́ні безконе́чную обріла́ єси́ жизнь, пребива́ющи с Женихо́м твої́м всегда́, Євге́ніє равноа́нгельная. Моли́ Христа́ Бо́га прегріше́ній оставле́ніє дарова́ти чту́щим любо́вію всечестну́ю па́м'ять твою́.","Слава, і нині: Не́бо мні показа́ся днесь земля́, на ней бо ражда́ється Творе́ць і в я́сліх восклоня́ється во Вифлеє́мі Іуде́йстім. Со а́нгели пою́ть па́стиріє непреста́нно: во ви́шніх сла́ва, мир в ми́рі; ви́діша бо звізду́, путеше́ствующу с волхви́, ско́ро же теку́ще принести́ да́ри, зла́то, сми́рну і лива́н, я́ко всіх су́щему Бо́гу, і Царю́ ві́чному, і Зижди́телю вся́чеських, во верте́пі за милосе́рдіє ро́ждшемуся."]},{"h":"Пісня 4","ps":["Ірмос: Прише́л єси́ от Ді́ви не хода́тай, ні а́нгел, но Сам Го́споди вопло́щся, і спасл єси́ всего́ м'я челові́ка; тім зову́ ті: сла́ва си́лі Твоє́й, Го́споди.","Приспів: Свята́я преподобному́ченице Євге́ніє, моли́ Бо́га о нас.","Прише́л єси́, воплоти́вся от Ді́ви, Ви́шній, Себі́ обручи́в дів соста́ви, Тебе́ Єди́наго возлю́бльшія, ді́вственнаго Жениха́ зна́ємаго.","Приспів: Свята́я преподобному́ченице Євге́ніє, моли́ Бо́га о нас.","Рождества́ плотська́го совлекла́ єси́ покрива́ло: пакирожде́нія же нетлі́нную оде́жду, му́ченице всесла́вная, світови́дно облекла́ єси́ креще́нієм.","Приспів: Свята́я преподобному́ченице Євге́ніє, моли́ Бо́га о нас.","Возсія́ світоно́сная заря́ се́рдцю твоєму́, ле́сти отгоня́щи ізлія́нний мрак блиста́нієм благода́ті, му́ченице Христо́ва Євге́ніє, до́брая ді́во.","Удобре́нно твоє́ і красно́ житіє́ просвіти́ла єси́, воздержа́нієм пе́рвіє плотські́я стра́сті ув'яди́вши, посліди́ же страда́нієм пресві́тло, Євге́ніє, сія́ющи.","Богородичен: Преви́шшая а́нгел била́ єси́, Всепі́тая, О́тча ро́ждши сові́та вели́каго А́нгела, Челові́ка би́вша за мно́гоє благоутро́біє, Человіколю́бця."]},{"h":"Пісня 5","ps":["Ірмос: Просвіще́ніє во тьмі лежа́щих, спасе́ніє отча́янних, Христе́ Спа́се мой, к Тебі́ у́тренюю, Царю́ ми́ра, просвіти́ м'я сія́нієм Твої́м, іно́го бо ра́зві Тебе́ Бо́га не зна́ю.","Приспів: Свята́я преподобному́ченице Євге́ніє, моли́ Бо́га о нас.","Тече́ніє твоє́ направля́ємо ви́дя ко спасе́нію, змій душепа́губний, страстоно́сице, воздвиза́єть іскуше́нія тебі́ разли́чная, твою́ крі́пость разсла́бити покуша́яся; сего́ же, богому́драя чи́стая, попра́ла єси́.","Приспів: Свята́я преподобному́ченице Євге́ніє, моли́ Бо́га о нас.","Вся добра́ до́брих Да́телю, і Благоді́телю, і Жениху́ душ, Христу́, яви́лася єси́, укра́шена в по́стниціх воздержа́нієм і му́ченичеським страда́нієм сія́ющи, му́ченице Євге́ніє, Христо́ва до́брая ді́во.","Віне́ць твоєму́ верху́ наложи́ся дарова́ній: Боже́ственную бо почти́ла єси́ му́дрость, бога́тство і сла́ву оте́чеськую презрі́вши, і с крі́постію послі́довала єси́ возлю́бленному Жениху́ твоєму́, всечестна́я.","Богородичен: Із Тебе́ Жизнь, возсія́вши ми́ру, Богороди́тельнице, пре́жде сме́ртію удержа́нния воззива́єть к жи́зні присносу́щній причаще́нієм, ві́рою вопію́щия: іно́го, ра́зві Тебе́, Бо́га не зна́єм."]},{"h":"Пісня 6","ps":["Ірмос: В бе́здні гріхо́вній валя́яся, неізслі́дную милосе́рдія Твоєго́ призива́ю бе́здну: от тлі, Бо́же м'я возведи́.","Приспів: Свята́я преподобному́ченице Євге́ніє, моли́ Бо́га о нас.","Дрема́нія твої́м ві́ждом не дала́ єси́, до́ндеже сладостра́стіє все угаси́ла єси́ і чи́стую Зижди́телю твоєму́ тебі́ саму́ю соверши́ла єси́ оби́тель.","Приспів: Свята́я преподобному́ченице Євге́ніє, моли́ Бо́га о нас.","Єги́птянині, нра́вом поревнова́вши, очерні́вшая ді́лом і і́менем, клевета́ти остри́ться честно́є житіє́ твоє́, всечестна́я.","Тве́рдую показа́вши сві́тлость і врачева́ній благода́тію обогати́вшися бога́тством ві́ри, чернори́зиць составле́нію бисть учи́тельниця.","Богородичен: Та́їнственно уча́хуся несказа́нному всі проро́ци Твоєму́, Всечи́стая, Рождеству́, духо́вно образу́юще і предглаго́люще всім бу́дущая."]},{"h":"Пісня 7","ps":["Ірмос: Богопроти́вноє велі́ніє беззако́ннующаго мучи́теля висо́к пла́мень вознесло́ єсть: Христо́с же простре́ Богочести́вим отроко́м ро́су духо́вную, Сий Благослове́н і Препросла́влен.","Приспів: Свята́я преподобному́ченице Євге́ніє, моли́ Бо́га о нас.","Із'ясни́ла єси́ всім богодухнове́нних писа́ній і́стину, же́нськоє єстество́ ому́жествивши, і вся удиви́ла єси́ пресла́вно, честна́я, я́же привела́ єси́ сві́тли ве́ровавшия Христу́, всебога́тая.","Приспів: Свята́я преподобному́ченице Євге́ніє, моли́ Бо́га о нас.","Я́вственно обличи́ла єси́ і́дольськоє неі́стовство, всехва́льная, боже́ственними твої́ми уче́ньми, і дів неізче́тноє мно́жество обручи́вши всі́ми ца́рствующему Христу́ сві́тлоє му́ченичеською кро́вію.","Ви́дівши житіє́ твоє́ світоно́сноє, Васи́лла сла́вная, боже́ственне поревнова́вши і Христу́ обручи́ся, оста́вльши плотсько́є все сладостра́стіє, і ни́ні му́ченичеськия ра́дости сподо́бися.","Богородичен: Па́жить ісціли́ла єси́ сме́ртную, безсі́менно ро́ждши Жизнь Іпоста́сную, Ді́во Всенепоро́чная, Богороди́тельнице Чи́стая. Тім же Тя, ра́дующеся, істо́чник безсме́ртія імену́єм."]},{"h":"Пісня 8","ps":["Ірмос: В пещ о́гненную ко отроко́м євре́йським снизше́дшаго і пла́мень в ро́су прело́жшаго Бо́га, по́йте діла́ я́ко Го́спода, і превозносі́те во вся ві́ки.","Приспів: Свята́я преподобному́ченице Євге́ніє, моли́ Бо́га о нас.","В ріці́ ю́ношеськи, во огні́ же терпіли́вно іскуси́лася єси́: проти́вная бо єстества́ крі́пко прешла́ єси́, — Христа́ по́йте, діла́, — зову́щи, — і превозносі́те во вся ві́ки.","Приспів: Свята́я преподобному́ченице Євге́ніє, моли́ Бо́га о нас.","Страннолі́пно явле́йся Христо́с тебі́, в темни́ці держи́мій, препитава́єть бога́тно і Рождество́м Свої́м совокупля́єть го́рнім во́їнством тя, славосло́в'ящую Єго́ во ві́ки.","Приспів: Свята́я преподобному́ченице Євге́ніє, моли́ Бо́га о нас.","Твой Жени́х благолі́пно вінці́ тя сугу́бими украша́єть, Євге́ніє богому́драя, і тебі́ черто́г сві́тел пра́ведно, я́ко пра́ведний, дає́ть. Єго́же превозно́сим во вся ві́ки.","Благода́ть Бо́жия, світови́дно облиста́вши тя, ни́ні озаря́єть во оби́теліх небе́сних, Єя́же напо́лнитися твої́ми моли́твами непреста́нно моли́ соверша́ющим твою́ па́м'ять, богому́драя.","Богородичен: Безсме́ртния зари́ істо́чник ві́ми Тя, Богоро́дице, я́ко ро́ждшую Сло́во Безсме́ртнаго Отця́, вся сме́рти ізбавля́ющаго превозноша́ющия Єго́ во ві́ки."]},{"h":"Пісня 9","ps":["Ірмос: Безнача́льна Роди́теля Син, Бог і Госпо́дь, вопло́щся от Ді́ви, нам яви́ся, омраче́нная просвіти́ти, собра́ти расточе́нная, тім Всепі́тую Богоро́дицю, велича́єм.","Приспів: Свята́я преподобному́ченице Євге́ніє, моли́ Бо́га о нас.","Во оби́телі все́льшися небе́сния, сла́вная, ни́ні сла́дости ра́йськия сподо́билася єси́ я́вственно с ді́вами, я́ко му́чениця всеї́стинна і с му́ченицями ді́ва всенепоро́чная, Євге́ніє всеблаже́нная.","Приспів: Свята́я преподобному́ченице Євге́ніє, моли́ Бо́га о нас.","Жела́ніє получи́ла єси́ па́че ума́ і сми́сла, жела́ній кра́йнійшему предстоя́щи сві́тло і світоза́рними луча́ми Нача́льния Тро́йці, богому́драя, я́вственно сія́ющи, Євге́ніє, до́брая ді́во.","Приспів: Свята́я преподобному́ченице Євге́ніє, моли́ Бо́га о нас.","Свіщу́ держа́щи ді́вства неуга́сну, му́ченичеським вінце́м украси́лася єси́, і ни́ні моля́щи не преста́й благоче́стно тя любо́вію почита́ющим спасти́ся моли́твами твої́ми, Євге́ніє всесла́вная.","К Боже́ственному ни́ні ізшла́ єси́ прохлажде́нію, вседо́бляя, ран проше́дши огнь нестерпи́мий і непостоя́нную во́ду іскуше́ній, му́ченице Євге́ніє. Христа́ у́бо моли́ спасти́ ду́ші на́ша.","Богородичен: Я́ко руно́, Всенепоро́чная, дождь небе́сний во чре́ві заче́нши, нам родила́ єси́ безсме́ртіє даю́щаго, благоче́стно Того́ воспіва́ющим і Тя, Всенепоро́чную Богоро́дицю, велича́ющим."]}],"notes":[]},{"u":"Канон молебний преподобному Никифору Прокаженному","e":"Supplicatory canon to St Nikephoros the Leper","secs":[{"ps":["Твір монахині Ісидори"]},{"h":"Після благословення священника починаємо псалом 142","ps":["Го́споди, усли́ши моли́тву мою́, внуши́ моле́ніє моє́ во і́стині Твоє́й, усли́ши м'я в пра́вді Твоє́й. І не вни́ди в суд с рабо́м Твої́м, я́ко не оправди́ться пред Тобо́ю всяк живи́й. Я́ко погна́ враг ду́шу мою́, смири́л єсть в зе́млю живо́т мой; посади́л м'я єсть в те́мних, я́ко ме́ртвия ві́ка. І уни́ во мні дух мой, во мні см'яте́ся се́рдце моє́. Пом'яну́х дні дре́внія; поучи́хся во всіх ді́ліх Твої́х, в творе́ніїх руку́ Твоє́ю поуча́хся. Возді́х к Тебі́ ру́ці мої́, душа́ моя́ я́ко земля́ безво́дная Тебі́. Ско́ро усли́ши м'я, Го́споди, ісчезе́ дух мой; не отврати́ лиця́ Твоєго́ от мене́, і уподо́блюся низходя́щим в ров. Сли́шану сотвори́ мні зау́тра ми́лость Твою́, я́ко на Тя упова́х; скажи́ мні, Го́споди, путь, во́ньже пойду́, я́ко к Тебі́ взях ду́шу мою́. Ізми́ м'я от враг мої́х, Го́споди, к Тебі́ прибіго́х. Научи́ м'я твори́ти во́лю Твою́, я́ко Ти єси́ Бог мой; Дух Твой Благи́й наста́вить м'я на зе́млю пра́ву. І́мене Твоєго́ ра́ди, Го́споди, живи́ши м'я; пра́вдою Твоє́ю ізведе́ши от печа́лі ду́шу мою́. І ми́лостію Твоє́ю потреби́ши враги́ моя́, і погуби́ши вся стужа́ющия душі́ моє́й: я́ко аз раб Твой єсьм.","Потім: Бог Господь і явися нам:"]},{"h":"Тропар, глас 4","ps":["Подібен: Вознесийся на Хрест:","Пло́ті твоєя́ прокаже́ніє / мужему́дренно, я́ко І́ов, / претерпі́л єси́ Ники́форе, / ри́зу же душі́ твоєя́ / сві́тлі очи́стил єси́, / соверше́нне же на лі́ствицю доброді́телей восше́д, / по́двиги твої́ми / жи́тельства А́нгельськаго дости́же, / непреста́нно Бо́гу поя́: / Тебі́ сла́ва подоба́єть,\\ Тро́йце Єдиносу́щная.","Сла́ва Отцю́ і Си́ну і Свято́му Ду́ху: той самий.","І ни́ні і при́сно і во ві́ки віко́в. Амі́нь:","Не умолчи́м нікогда́, Богоро́дице, / си́ли Твоя́ глаго́лати, недосто́йнії: / а́ще бо Ти не би предстоя́ла моля́щи, / кто би нас ізба́вил от толи́ких бід, / кто же би сохрани́л до ни́ні свобо́дні? / Не отсту́пим, Влади́чице, от Тебе́:\\ Твоя́ бо раби́ спаса́єши при́сно от вся́ких лю́тих.","§Псалом 50: Помилуй мя, Боже. І починаємо канон, глас 1, акровірш якого: «Радуйся, Никифоре, прокаженних нова́я слава»."]},{"h":"Пісня 1","ps":["Ірмос: Во́ду проше́д, я́ко су́шу, / і єги́петськаго зла ізбіжа́в, / ізраїльтя́нин вопія́ше: / Ізба́вителю і Бо́гу на́шему пої́м.","Приспів: Преподо́бне о́тче Ники́форе, моли́ Бо́га о нас!","Благода́ті чи́стий сосу́д, / па́че сні́га убеле́нна душе́ю, / прокаже́ннаго Ники́фора / прийді́те всі чисті́йшими пі́сньми да возвели́чим.","Приспів: Преподо́бне о́тче Ники́форе, моли́ Бо́га о нас!","Любве́ напечатле́ніє свяще́ннійшеє, / ві́ри путь сконча́вшаго му́жеськи, / наде́ждею ви́шняго Ца́рствія, / ни́ні Ники́фора прокаже́ннаго да ублажи́м.","Сла́ва Отцю́ і Си́ну і Свято́му Ду́ху.","По́ти преподо́бнаго твоєго́ боре́нія / ду́шу боже́ственну, Ники́форе, і́стинно сотвори́в, / зла́та світлі́йшу, / к Бо́гу ру́ці воздева́л єси́.","І ни́ні і при́сно і во ві́ки віко́в. Амі́нь.","Глаго́ли неізрече́нния Гавриї́лови сли́шавши, / Отрокови́це Пресвята́я, / благопослу́шно ми́рові Бо́га родила́ єси́, / кля́тву же Є́вину упраздни́ла єси́."]},{"h":"Пісня 3","ps":["Ірмос: Небе́снаго кру́га Верхотво́рче, Го́споди, / і Це́ркве Зижди́телю, / Ти мене́ утверди́ в любві́ Твоє́й, / жела́ній Кра́ю, ві́рних Утвержде́ніє, / Єди́не Человіколю́бче.","Приспів: Преподо́бне о́тче Ники́форе, моли́ Бо́га о нас!","От Кри́та возше́л єси́, / я́коже новосія́нноє со́лнце, / всю же зе́млю заря́ми жи́тельства твоєго́ / благолі́пно обнови́л єси́, / си́не сві́та, Ники́форе, / і помраче́нія стра́стнаго вся́каго разріша́єши.","Приспів: Преподо́бне о́тче Ники́форе, моли́ Бо́га о нас!","Сми́сленно мона́шеськую стезю́ у́зькую соверши́л єси́, / во вся́чеськом воздержа́нії жи́тельствуя, всеблаже́нне, / і беспло́тних лико́в / во пло́ті дости́г, Ники́форе, / воі́стину возвели́чил єси́ / схи́му, о́браз равноа́нгельний.","Сла́ва Отцю́ і Си́ну і Свято́му Ду́ху.","Ісціле́ній Імі́яй безмі́рную бе́здну, / і в неду́зі Наказу́яй ї́хже я́ко непоро́чная ча́да приє́млеть, / Христо́с пло́ті твоєя́ прокаже́ніє, Ники́форе, / дарова́ любве́ во утвержде́ніє.","І ни́ні і при́сно і во ві́ки віко́в. Амі́нь.","Господоімени́тая Отрокови́це, / ми́ра всего́ Влади́чице, / ду́шу мою́ прегріше́ньми порабоще́нную / ма́терніми Твої́ми мольба́ми / покажи́ страсте́й преви́шшу, / к пе́рвой сла́ві моє́й па́ки возве́дши.","Уврачу́й на́ша стра́сті моли́твами твої́ми, Ники́форе, / поне́сший му́жеськи / пло́ті прокаже́ніє, / к соверше́нному іспита́нію терпі́нія.","При́зри благосе́рдієм, Всепі́тая Богоро́дице, / на моє́ лю́тоє тілесе́ озлобле́ніє / і ісціли́ душі́ моєя́ болі́знь."]},{"h":"Сідален, глас 2","ps":["Подібен: Моління теплеє:","Му́ку ве́лію прокаже́нія претерпі́л єси́ / великоду́шно і си́льною во́лею, / Бо́га прославля́я, Ники́форе, / пе́сне ра́дованная, / і велича́я устна́ми непоро́чними,\\ боже́ственную непреста́нно чистоту́."]},{"h":"Пісня 4","ps":["Ірмос: Усли́шах,Го́споди, / смотре́нія Твоєго́ та́їнство, / разумі́х діла́ Твоя́ / і просла́вих Твоє́ Божество́.","Приспів: Преподо́бне о́тче Ники́форе, моли́ Бо́га о нас!","Наслажде́нія пло́ті, / во вся́чеськом воздержа́нії жи́тельствуя, умертви́л єси́, / дух же Боже́ственно оживи́л єси́.","Приспів: Преподо́бне о́тче Ники́форе, моли́ Бо́га о нас!","Тезоіме́н зва́нію небе́сному, блаже́нне, / соді́лався, Ники́форе, / одолі́л єси́ полці́ всі чужда́го.","Сла́ва Отцю́ і Си́ну і Свято́му Ду́ху.","Оче́с осліпле́ніє терп'я́, о́тче Ники́форе, / внутр себі́ зря́ше / блиста́нія Бо́жия Ду́ха, / і сія́ющих луче́й світ непристу́пний.","І ни́ні і при́сно і во ві́ки віко́в. Амі́нь.","Рече́нія ісполня́ються проро́чеськая / на Тебі́, Всепі́тая, / неіскусому́жно бо во чре́ві понесла́ єси́ / Єго́же дре́вле сі́ї предвозвісти́ша."]},{"h":"Пісня 5","ps":["Ірмос: Просвіти́ нас повелі́нії Твої́ми, Го́споди, / і ми́шцею Твоє́ю висо́кою / Твой мир пода́ждь нам, Человіколю́бче.","Приспів: Преподо́бне о́тче Ники́форе, моли́ Бо́га о нас!","Утверди́л єси́ ум / на ка́мені Го́спода твоєго́, Ники́форе, / тім преби́л єси́ тверд, я́коже адама́нт, / болі́зні не ужаса́яся.","Приспів: Преподо́бне о́тче Ники́форе, моли́ Бо́га о нас!","Прокаже́ніє пло́ті я́ко І́ов / прене́сл єси́ терпіли́вно, / тім сія́єши, Ники́форе, душе́ю / па́че зла́та і сребра́ многоці́ннаго.","Сла́ва Отцю́ і Си́ну і Свято́му Ду́ху.","Возложи́л єси́, Ники́форе, / на Бо́га наде́жду свою́, / сиро́т і вдов Засту́пника / оте́чеськаго ра́ди ми́лованія, / от Него́же обрета́ше вспоможе́ніє.","І ни́ні і при́сно і во ві́ки віко́в. Амі́нь.","Столп непристу́пен на враги́ єси́, Влади́чице, / устремля́ющися на того́ ухищре́нія, / я́ко Ро́ждшая Іму́щаго си́лу неісче́тную."]},{"h":"Пісня 6","ps":["Ірмос: Моли́тву пролію́ ко Го́споду / і Тому́ возвіщу́ печа́лі моя́, / я́ко зол душа́ моя́ іспо́лнися / і живо́т мой а́ду прибли́жися, / і молю́ся, я́ко Іо́на: / от тлі, Бо́же, возведи́ м'я.","Приспів: Преподо́бне о́тче Ники́форе, моли́ Бо́га о нас!","Укріпи́вся Бо́жиєю благода́тію / на стра́сті до́льнія, Ники́форе, / не́мощ пло́ті твоєя́ прия́л єси́, / я́ко дарова́ніє ми́лости от Го́спода, / І́же челові́ком жа́ждеть спасе́нія / ра́ди щедро́т неізче́тних.","Приспів: Преподо́бне о́тче Ники́форе, моли́ Бо́га о нас!","Я́ко світи́льника тя Тро́йці позна́хом, Ники́форе, / на горі́ утвержде́нна, / і всім ра́достно разлива́юща, / сія́ніє і блеща́ніє Ду́ха, / мглу страсте́й расточа́ющеє, / і веселя́щеє землі́ всі конці́.","Сла́ва Отцю́ і Си́ну і Свято́му Ду́ху.","Побіди́л єси́ вра́жія возноше́нія, Ники́форе, / смире́нієм твої́м Боже́ственним, / я́ко душе́ю благоразу́міє прял єси́, / ті́лом же му́ки і я́зви, / і соді́лался єси́ всеї́стинно / сні́га безмі́рно беле́є.","І ни́ні і при́сно і во ві́ки віко́в. Амі́нь.","Утро́ба твоя́ свята́я / соді́лася, Марі́є, небе́с ши́рши, / я́ко Бог в ню всели́ся, / Єго́же небе́сная не вмісти́ша преді́ли, / Сего́ ма́терськи моли́ / стра́стния м'я разріши́ти печа́лі.","Уврачу́й на́ша стра́сті моли́твами твої́ми, Ники́форе, / поне́сший му́жеськи / пло́ті прокаже́ніє, / к соверше́нному іспита́нію терпі́нія.","При́зри благосе́рдієм, Всепі́тая Богоро́дице, / на моє́ лю́тоє тілесе́ озлобле́ніє / і ісціли́ душі́ моєя́ болі́знь.","І священник поминає."]},{"h":"Кондак, глас 2","ps":["Подібен: Предстательство християн:","Неду́га у́зький путь проше́л єси́, Ники́форе, / і вся́чеськи послі́довал єси́ Влади́ці, / я́ко послушли́вий і досто́йний син, / і́го же Того́ благо́є і бре́м'я ле́гкоє / на ра́міх поне́сл єси́, / ті́мже лику́я возше́л єси́ / к сла́ви ві́чния поко́ю кра́сному,\\ ра́достно веселя́ся.","Прокімен, глас 4: Честна́ пред Го́сподем смерть преподо́бних Єго́.","Стих: Терп'я́ потерпі́х Господ і внят мі:"]},{"h":"Від Матфея святого Євангелія читання.","ps":["Рече́ Госпо́дь Свої́м ученико́м: вся Мні предана́ суть Отце́м Мої́м: і нікто́же зна́єть Син, то́кмо Оте́ць: ні Отця́ кто зна́єть, то́кмо Син, і єму́же а́ще во́лить Син откри́ти. Прийді́те ко Мні, всі тружда́ющіїся і обремене́ннії, і Аз упоко́ю ви: возьмі́те і́го моє́ на себі́ і научі́теся от Мене́, я́ко кро́ток єсьм і смире́н се́рдцем, і обря́щете поко́й душа́м ва́шим, і́го бо Моє́ бла́го і бре́м'я Моє́ легко́ єсть.","Сла́ва Отцю́ і Си́ну і Свято́му Ду́ху.","Моли́твами преподо́бнаго Твоєго́ Ники́фора, / Ми́лостиве, очи́сти / мно́жество согріше́ній на́ших.","І ни́ні і при́сно і во ві́ки віко́в. Амі́нь.","Моли́твами Богоро́диці, / Ми́лостиве, очи́сти / мно́жество согріше́ній на́ших.","Поми́луй м'я, Бо́же, / по вели́цій ми́лості Твоє́й і по мно́жеству щедро́т Твої́х / очи́сти беззако́ніє моє́."]},{"h":"Стихира, глас 6","ps":["На лі́ствицю небе́сную доброді́телей, Ники́форе, / по́мислом богому́дрим / і душе́вною тве́рдостію возше́л єси́, / я́ко І́ов бо ноша́ше / пло́ті прокаже́ніє і оче́с сліпоту́, / я́зви і стру́пи, і вся́каго у́да озлобле́ніє, / к Ви́шнім же вознесе́н, / вся Небе́сних узрі́л єси́, / добро́ту і сла́ву, / ю́же Госпо́дь уго́това Бог / сотворя́ющим ви́ну Єго́ запові́данія.","Потім священник: Спаси́, Бо́же, лю́ди Твоя́:","Хор: Го́споди, поми́луй: 12 раз."]},{"h":"Пісня 7","ps":["Ірмос: От Іуде́ї доше́дше, о́троци / во Вавило́ні іногда́ / ві́рою Тро́йчеською пла́мень пе́щний попра́ша, пою́ще: / отце́в Бо́же, благослове́н єси́.","Приспів: Преподо́бне о́тче Ники́форе, моли́ Бо́га о нас!","Непреста́нную стяжа́л єси́ моли́тву, / я́ко ді́ланіє в житії́ превосхо́днейшеє, / є́юже с Бо́гом бесі́дуєши, / а́нгельському жи́тельству подража́я, / отце́в Бо́же, вопія́, благослове́н єси́.","Приспів: Преподо́бне о́тче Ники́форе, моли́ Бо́га о нас!","Упра́влен, блаже́нне, от свята́го Анфи́ма, / прекра́сно на Хіо́сі соверши́л єси́ подви́жничеський путь, / і того́ побі́ди ве́лія, Ники́форе, описа́л єси́, / тім вінці́ от живоно́сния десни́ці восприя́л єси́.","Сла́ва Отцю́ і Си́ну і Свято́му Ду́ху.","Возсила́я Боже́ственния / моли́тви твоя́, Ники́форе, ко Го́споду, / полу́нощі на возду́х возше́л єси́, / ізумле́нія ученика́ іспо́лнив, / тя узре́вшаго Євме́нія, / с ни́мже пі́ніє Бо́гу прино́сиши во ві́ки.","І ни́ні і при́сно і во ві́ки віко́в. Амі́нь.","Ма́нни тя ста́мна воі́стину пред'явля́ше, / Ді́во Ма́ти Чи́стая, / во чре́ві бо Твоє́м сохрани́ла єси́ Хліб жи́зні Небе́сний, Христа́, / душі́ ві́рних препита́ющий неізрече́нно."]},{"h":"Пісня 8","ps":["Ірмос: Царя́ Небе́снаго, / Єго́же пою́ть во́ї А́нгельстії, / хвалі́те і превозносі́те во вся ві́ки.","Приспів: Преподо́бне о́тче Ники́форе, моли́ Бо́га о нас!","Словеси́ твої́ми Боже́ственними / і поуче́нії му́дрими / душа́м скорб'я́щих сла́дкоє утіше́ніє / предлага́єши, Ники́форе.","Приспів: Преподо́бне о́тче Ники́форе, моли́ Бо́га о нас!","Нестяжа́нія тя сокро́вище, Ники́форе, / ві́рноє і ве́ліє стяжа́хом, / я́ко се́рдцем нищ соді́лался єси́, блаже́нне.","Сла́ва Отцю́ і Си́ну і Свято́му Ду́ху.","Дале́че су́щая / а́ки бли́жняя зря́ше, / душе́внима очи́ма, Ники́форе, / я́ко Боже́ственним прозрі́нієм украси́лся єси́.","І ни́ні і при́сно і во ві́ки віко́в. Амі́нь.","Преіспещре́на Боже́ственню сла́вою, Ді́во, / Царю́ Небе́сному одесну́ю предста́ла єси́ / я́ко Влади́чиця ми́ра."]},{"h":"Пісня 9","ps":["Ірмос: Воі́стину Богоро́дицю, / Тя іспові́дуєм, / спасе́ннії Тобо́ю, Ді́во Чи́стая, / с Безпло́тними ли́ки Тя велича́юще.","Приспів: Преподо́бне о́тче Ники́форе, моли́ Бо́га о нас!","Ле́гці і́го прокаже́нія тягча́йшаго / о Ники́форе, поне́с, / во град Бо́жий і́же свобо́дь єсть, преше́л єси́, / ле́гці воскриля́єм.","Приспів: Преподо́бне о́тче Ники́форе, моли́ Бо́га о нас!","Сі́м'я, Ники́форе, єва́нгельськоє, / в до́браго і блага́го се́рдця твоєго́ земле́ возде́ланноє, / многопло́ден клас сотвори́.","Приспів: Преподо́бне о́тче Ники́форе, моли́ Бо́га о нас!","Світи́льнику душі́ твоєя́ іспо́лнену, Ники́форе, / терпі́нія єле́єм, / Жени́х Христо́с, тя ли́ку му́дрих дів сопричте́.","Сла́ва Отцю́ і Си́ну і Свято́му Ду́ху.","Ра́ка моще́й твої́х то́чить, Ники́форе, / Уті́шителя благода́ть і благоуха́ніє жи́зні / благогові́йно приходя́щим к ней всегда́.","І ни́ні і при́сно і во ві́ки віко́в. Амі́нь.","Я́ко луна́, Богоро́дице, ярча́йшая / прозяба́єши ми́рові свяще́нний світ, / я́ко ро́ждшая сла́ви вели́коє Со́лнце.","Потім: Достойно є:"]},{"h":"Величання","ps":["Я́ко да тя блаже́нства на Небесі́х / прича́стника тя сотвори́ть, / Влади́ка ра́ни і печа́лі прокаже́нія / в земні́й юдо́лі ті даде́, Ники́форе, / я́ко Оте́ць благоутро́бний.","Пра́вило тя лу́чшеє смиренному́дрія позна́ли єсьми́, / терпі́нія зерца́ло, / бді́нія столп, терпі́нія ді́лателя, / моли́тви же, Ники́форе, вели́каго учи́теля.","Укріпи́вся пе́рвіє, я́ко І́ов, / в терпі́нії, Ники́форе, болі́зней, / сего́ ра́ди ни́ні с ним весели́шися ві́чно / неізрече́нним богозрі́нієм, величаємий.","Всю́ду христолю́бцев боже́ственноє мно́жество, / Христо́ва люби́мця Ники́фора ни́ні прокаже́ннаго, / пі́сньми хвале́бними да украси́м досто́йно, / я́ко небе́снаго терпі́нія борця́ превосхо́днейшаго.","Я́ко спелая виногра́дная гроздь, / в точи́лі прокаже́нія, Ники́форе, / ісцежа́єши вино́ доброді́телей боже́ственноє, / веселя́щеє сердца́ восхваля́ющих тя.","Жезл си́ли Бо́жия, Ники́форе, імі́я, я́ко по́сох крі́пок, / мимоходя́ше тве́рдо тісноту́ жите́йськую / гряди́й к Боже́ственних Черто́гов широті́ простра́нній.","Я́ко на́ковальня пребива́я терпі́нія, / непрекло́нен показа́лся єси́, Ники́форе, во озлобле́ніїх, / і в ку́зниці іспи́тан болі́зней, / зла́та блиста́єши вся́чеськи світлі́є.","Днесь си́ли А́нгельстії / ра́дуються зрі́ти / Ники́фора Боже́ственную ду́шу, / Престо́лу Влади́чню с ни́ми предстоя́щую / і сла́вою осія́нную чистоти́.","Ублажа́єм тя, / преподо́бне о́тче Ники́форе прокаже́нний, / і чтим святу́ю па́м'ять твою́, / наста́вниче мона́хов / і собесі́дниче А́нгелов.","Потім: величання святому храму. Трисвяте: по «Отче наш»:"]},{"h":"Тропар, глас 1","ps":["Подібен: Пустинний житель:","Ники́фора преподо́бнаго прокаже́наго боре́нієм / і є́же в по́двизіх му́жеству / удиви́шася А́нгели, / я́ко други́й бо І́ов / боле́знная претерпі́, сла́в'я Бо́га, / ни́ні же сла́вою увінчава́ється от Него́, / чуде́с раздая́нієм. / Ра́дуйся, мона́хов наста́вниче, / ра́дуйся, челові́ком укріпле́ніє, / ра́дуйся, благоуха́нія обра́дованіє\\ ізлива́яй от моще́й твої́х.","Потім це:"]},{"h":"Стихира, глас 2","ps":["Подібен: Єгда от древа:","Ра́дуйся, терпі́нія страстоте́рпче, / утіше́нія світи́льниче, / наде́жди боже́ственний о́бразе, / ві́ри напечатле́ніє, / любве́ ісполне́ніє, / моли́тви учи́телю, / пра́вило воздержа́нія, / бога́тство многолюбе́зноє чистоти́. / Прокаже́нія пе́щію іспи́тан, / сія́єши, Ники́форе, ми́рові\\ зла́та преди́вно світлі́є.","Влади́чице, прими́ моли́тви раб Твої́х / і ізба́ви нас\\ от вся́кия ну́жди і печа́лі.","Все упова́ніє моє́ на Тя возлага́ю, / Ма́ти Бо́жия, / сохрани́ м'я под кро́вом Твої́м.","Моли́твами, Го́споди, всіх святи́х Твої́х і Богоро́диці / Твой мир даждь нам / і поми́луй нас,\\ я́ко Єди́н милосе́рд.","От вся́ких бід раби́ Твоя́ сохрани́, / благослове́нная Богоро́дице, / я́ко да Тя славосло́вим,\\ Наде́жду душ на́ших."]},{"h":"Молитва","ps":["О святи́й уго́дниче Бо́жий, преподо́бне о́тче наш Ники́форе прокаже́нний! По́двигом добри́ подвиза́вся на землі́, восприя́л єси́ на Небесі́х віне́ць пра́вди, єго́же угото́вал єсть Госпо́дь всім лю́б'ящим Єго́. Ті́мже, взира́юще на твой святи́й о́браз, ра́дуємся о пресла́внім сконча́нії жи́тельства твоєго́ і чтем святу́ю па́м'ять твою́. Ти же, предстоя́ Престо́лу Бо́жию, прийми́ моле́нія на́ша і ко Всемилостивому́ Бо́гу принеси́, о є́же прости́ти нам вся́коє прегріше́ніє і помощі́ нам ста́ти проти́ву ко́знем дия́вольским, да ізба́вльшеся от скорбе́й, болі́зней, бід і напа́стей і вся́каго зла, благоче́стно і пра́ведно поживе́м в ни́нішнем ві́ці і сподо́бимся предста́тельством твої́м, а́ще і недосто́йни єсьми́, ви́діти блага́я на землі́ живи́х, сла́в'яще Єди́наго во святи́х Свої́х сла́вимаго Бо́га, Отця́, і Си́на, і Свята́го Ду́ха, ни́ні і во ві́ки віко́в. Амі́нь."]},{"h":"Інша молитва","ps":["О свяще́нная главо́, преподо́бне о́тче, преблаже́нне Ники́форе прокаже́нний! Не забу́ди убо́гих твої́х до конця́, но помина́й нас всегда́ во святи́х твої́х і благоприя́тних моли́твах к Бо́гу. Моли́ за ни, долготерпіли́вий о́тче, я́ко імі́яй дерзнове́ніє к Небе́сному Царю́: не премолчи́ за ни ко Го́споду, і не пре́зри нас, ві́рою і любо́вію чту́щих тя. Помина́й нас, недосто́йних, у Престо́ла Вседержи́телева, і не преста́й моля́ся о нас ко Христу́ Бо́гу, і́бо дана́ тебі́ бисть благода́ть за ни моли́тися. Не мним бо тя су́ща ме́ртва: а́ще бо ті́лом і преста́вился єси́ от нас, но і по сме́рті жив сий пребива́єши. Не отступа́й от нас ду́хом, сохраня́я нас от стріл вра́жиїх і вся́кия пре́лести бісо́вськия і ко́зней дия́вольських, о́тче наш до́брий. А́ще бо і моще́й твої́х ра́ка пред очи́ма на́шима ви́дима єсть всегда́, но свята́я твоя́ душа́ со А́нгельськими во́їнстви, со безпло́тними ли́ки, с Небе́сними си́лами, у Престо́ла Вседержи́телева предстоя́щи, досто́йно весели́ться. Ві́дуще у́бо тя воі́стину і по сме́рті жи́ва су́ща, тебі́ припа́даєм і тебі́ мо́лимся: моли́ся о нас Всеси́льному Бо́гу, о по́льзі душ на́ших, і іспроси́ нам вре́м'я на покая́ніє, да невозбра́нно пре́йдем от землі́ на Не́бо, от мита́рств же го́рких, бісо́во возду́шних князе́й і от ві́чния муки́ да ізба́вимся, і Небе́снаго Ца́рствія наслі́дници да бу́дем со всі́ми пра́ведними, от ві́ка угоди́вшими Го́споду на́шему Ісу́су Христу́: Єму́же подоба́єть вся́кая сла́ва, честь і поклоне́ніє, со безнача́льним Єго́ Отце́м, і с Пресвяти́м і благи́м і животворя́щим Єго́ Ду́хом, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Канон преподобному Миколі Святоші, князю Чернігівському","e":"Canon to St Nicholas Sviatosha, Prince of Chernihiv","secs":[{"h":"Глас 4. Пісня 1","ps":["Ірмос: Отве́рзу уста́ моя́ і напо́лняться Ду́ха, і сло́во отри́гну Цари́це Ма́тері, і явлю́ся, сві́тло торжеству́я, і воспою́, ра́дуяся, Тоя́ чудеса́.","Приспів: Преподо́бне о́тче Нико́ло, моли́ Бо́га о нас.","Отве́рзи мні устні́, Христе́ мой, посли́ Паракли́та, да Твоєго́ уго́дника пі́ти возмогу́ стихосло́вії висоту́ доброді́телей, на ню́же в чистоті́ се́рдця смире́нієм взи́де.","Приспів: Преподо́бне о́тче Нико́ло, моли́ Бо́га о нас.","В пра́вду наре́клся єси́ Свято́ша: іспо́лнь бо сий святи́ні, вся́каго непреподо́бнаго ді́йства удали́лся єси́, і к Богови́дінію ум свой впери́в, отту́ду позна́л єси́ вся, я́же в ми́рі су́єтная би́ти.","Приспів: Преподо́бне о́тче Нико́ло, моли́ Бо́га о нас.","Пре́жде тебі́ би́вших пом'яну́л єси́, от коли́кия сла́ви напра́сно отпадо́ша, і с безче́стієм пожа́ть серп сме́рти; сего́ ти да ізба́вишися, престо́л на землі́ кня́жій оста́вил єси́, і прия́л єси́ на Небесі́ престо́л, і́же пребива́єть ви́ну со святи́ми.","Блаже́нному Іоаса́фу Інді́йському поревнова́л єси́: я́коже бо той оста́ви ца́рство земно́є і взиська́ Небе́сноє, та́ко і ти, блаже́нне, вре́менноє княже́ніє оста́вль, прия́л єси́ ві́чноє.","Богородичен: Ви́шняго Ца́рствія не лиши́ м'я, Небе́сними і земни́ми Влади́чествующая Госпоже́, сего́ бо іща́, удаля́юся, облада́єм вою́ющими всегда́ на м'я страстьми́, оба́че к Тебі́ несумні́нною наде́ждою прибіга́ю."]},{"h":"Пісня 3","ps":["Ірмос: Твоя́ пісносло́вці, Богоро́дице, живи́й і незави́стний істо́чниче, лик себі́ совоку́пльшія, духо́вно утверди́, в Боже́ственній Твоє́й сла́ві, вінце́в сла́ви сподо́би.","Приспів: Преподо́бне о́тче Нико́ло, моли́ Бо́га о нас.","Раб Єди́ному Бо́гу да бу́деши, не восхоті́л єси́ рабо́тати ми́ру, от него́же ізше́д, а́ки втори́й Авраа́м, дом і зе́млю свою́ оста́вил єси́ і прише́д, а́ки в Харра́нь, в пречестну́ю Бо́жия Ма́тере Пече́рськую оби́тель, ви́діл єси́ лі́ствицею дія́нія і ві́дінія блаже́нних оте́ць к Небесі́ восходя́щих.","Приспів: Преподо́бне о́тче Нико́ло, моли́ Бо́га о нас.","Господи́н сий іногда́ княже́нію своєму́, за любо́в Го́спода своєго́ сотвори́лся єси́ раб, служа́ рабо́м Христо́вим в пова́рни, да би́вшему нас ра́ди Послушли́ву до сме́рти послі́дуєши.","Приспів: Преподо́бне о́тче Нико́ло, моли́ Бо́га о нас.","Порфи́рою оді́ян і в руці́ імі́яй ски́петр, не устиді́лся єси́ на ра́менах дрова́ носи́ти і сіщи́ рука́ма свої́ма; да вся у́ди в порабоще́ніє преда́си Ви́шнему Влади́ці, от Него́же возме́здіє прия́л єси́ живо́т ві́чний.","Мирсті́ї мирська́я му́дрствующе, бра́тія твоя́, блаже́нне, мня́ху дія́ніє твоє́ в пова́рні безче́стно би́ти, тім і развраща́ху тя, да оста́виши сіє́. Но ти, люб'я́ послуша́ніє сіє́, єще́ єди́но лі́то іспроси́л єси́ себе́ в том пребива́ти.","Богородичен: За́повідем Го́спода моєго́ не повину́ющася, ні храня́щаго послуша́нія уста́ви, убіди́ м'я, Влади́чице моя́, к ді́ланію тіх і укріпи́ в про́чеє вре́м'я в обої́х соверше́нно іспра́витися, да не в лі́ності сконча́вся, с непотре́бними раби́ казнь прийму́ по діло́м."]},{"h":"Сідален, глас 8","ps":["Я́ко і́стиннаго послу́шателя Єва́нгельськаго сло́ва, і і́ноков люби́теля, і ревни́теля преподо́бним, прийді́те, бра́тіє, пі́сненними хвала́ми воспоє́м блаже́ннаго Нико́лу: той бо ті́ло своє́ порабо́ти Бо́гу, да ду́шу свободи́ть от страсте́й, і а́ки со́лнце, возсія́в луча́ми доброді́телей свої́х, всіх нас озаря́єть, пою́щих: сла́ва Бо́гу, призива́ющему раби́ Своя́ во ві́чноє спасе́ніє.","Богородичен: Ви́шняго м'я граждани́на покажи́, Чи́стая Ді́во, прибіга́ющаго к Твоєму́ покро́ву і прося́щаго от Тебе́ те́плаго заступле́нія, я́ко, да Тобо́ю обрі́т благода́ть, воспою́: сла́ва Бо́гу, спаса́ющему род челові́чеський."]},{"h":"Пісня 4","ps":["Ірмос: Сідя́й в сла́ві на Престо́лі Божества́, во о́блаці ле́гці при́йде Ісу́с Пребоже́ственний нетлі́нною дла́нію і спасе́ зову́щия: сла́ва, Христе́, си́лі Твоє́й.","Приспів: Преподо́бне о́тче Нико́ло, моли́ Бо́га о нас.","Сідя́й во сла́ві пре́жде на престо́лі і вельмо́жам предстоя́щим ті, не устиді́лся єси́, блаже́нне, сіді́ти при враті́х монасти́рських три лі́та, я́ко ві́рно храня́й сих вход от безді́льно влазя́щих.","Приспів: Преподо́бне о́тче Нико́ло, моли́ Бо́га о нас.","Председя́щу ті пе́рвіє на трапе́зі любопи́щней і мно́гим рабо́м служа́щим я́ко влади́ці, не возгнуша́лся єси́ посліди́, свя́те, раб би́ти рабо́м Христо́вим, тім служа́ і представля́я бра́шна от Бо́жіяго дарова́нія.","Приспів: Преподо́бне о́тче Нико́ло, моли́ Бо́га о нас.","Я́коже степе́ньми на висоту́ мирськи́я сла́ви возше́дши, і́муть упокоє́ніє по труді́х, та́ко і ти, преподо́бне, сові́том ігу́мена і бра́тії вся послуша́нія чи́ни проше́д, принужде́н с ми́ром в ке́ллії безмо́лвствовати і внима́ти спасе́нію своєму́.","Я́ко трудолюби́вий раб, умножа́я Влади́ці своєму́ тала́нт, не дал єси́ упокоє́нія многотру́дному твоєму́ ті́лу, но рука́ма свої́ма насади́л єси́ вертогра́д; і ви́діша бра́тія трудо́в твої́х плоди́.","Богородичен: Ліня́щася м'я, на доброді́телі пону́ди, Богоро́дице, і даждь мі вертогра́д душе́вний ми́сленними древеси́ насади́ти, слеза́ми умиле́нія напая́ти, і принести́ Влади́ці моєму́ стори́чний плод, да і аз с ві́рними раби́ Єго́ прийму́ от руку́ Єго́ мзду трудо́в мої́х."]},{"h":"Пісня 5","ps":["Ірмос: Ужасо́шася вся́чеськая о Боже́ственній сла́ві Твоє́й, Ти бо, Неіскусобра́чная Ді́во, імі́ла єси́ во утро́бі над всі́ми Бо́га і родила́ єси́ Безлі́тнаго Си́на, всім воспіва́ющим Тя мир подава́ющая.","Приспів: Преподо́бне о́тче Нико́ло, моли́ Бо́га о нас.","Дивля́хуся всі трудолю́бію твоєму́, блаже́нне, я́ко нікогда́же ви́дін бил єси́ пра́зден, но в рука́х ді́ло, в усті́х же імі́л єси́ ви́ну моли́тву Ісу́сову і се́ю отрази́л єси́ бі́са, празднолю́бієм напа́дающаго.","Приспів: Преподо́бне о́тче Нико́ло, моли́ Бо́га о нас.","Да пи́щі Небе́сния прича́стник бу́деши, сластолю́бія отве́рглся єси́: нічто́же бо ядя́ше, кромі́ от ово́щія монасти́рськаго ма́ло, і та́ко соблю́л єси́ чистоту́ душі́ і ті́ла.","Приспів: Преподо́бне о́тче Нико́ло, моли́ Бо́га о нас.","По мно́гих твої́х по́стничеських труді́х прия́л єси́ от Бо́га дар єди́нім сло́вом неду́ги ісціля́ти і посо́бствовати в ско́рбіх. Молю́ся ті, і мене́ от одержа́щаго неду́га в здра́віє преміни́ ско́ро.","Многоплете́нними сітьми́ тща́ся враг отврати́ти Боголюби́вую ду́шу твою́ от до́браго трудолю́бія путі́, наусти́ ні́когда служа́щаго тебі́ врача́; ти же, свя́те, увіща́нієм увіща́л єси́ того́, я́ко да не тебі́, но своєму́ спасе́нію внима́єть.","Богородичен: Се́рдцем і душе́ю разврати́хся, і отве́ргшися да́нния мі благода́ті, в неподо́бния хожду́ путі́, но, пре́жде да́же не впаду́ в ру́ці враго́м, Ти, Ма́ти Бо́жия, упра́ви м'я на пе́рвоє блаже́нство: овча́ бо єсьм спасе́нния Твоєя́ огра́ди."]},{"h":"Пісня 6","ps":["Ірмос: Боже́ственноє сіє́ і всечестно́є соверша́юще пра́зднество, Богому́дрії, Богома́тере, прийді́те рука́ми воспле́щем, от Нея́ ро́ждшагося Бо́га сла́вим.","Приспів: Преподо́бне о́тче Нико́ло, моли́ Бо́га о нас.","Боже́ственним жела́нієм к Бо́жієй любві́ устреми́вся, вся находя́щия ті ско́рби, блаже́нне, сла́дці терпі́л єси́, разсужда́я рече́нноє: я́ко недосто́йни суть стра́сті ві́ка сего́ ко хотя́щей яви́тися в нас сла́ві.","Приспів: Преподо́бне о́тче Нико́ло, моли́ Бо́га о нас.","Увещава́ющему тя Петру́ врачу́ от трудо́в і́ночеських преста́ти, цілому́дренно отвіща́л єси́ мно́гажди, свя́те: преста́ни, отвраща́я м'я от сицева́го начина́нія, ні скорб бо, ні глад, ні тіснота́ отлучи́ть м'я от любве́ Христо́ви, єя́же ра́ди терплю́ вся находя́щая на м'я.","Приспів: Преподо́бне о́тче Нико́ло, моли́ Бо́га о нас.","Да во Христі́ Живо́т Ві́чний обря́щеши, умертви́л єси́ ті́ло твоє́ мно́гим воздержа́нієм і трудо́м і не лиши́лся єси́, єго́же жела́л: се бо ни́ні живе́ши со святи́ми во дво́ріх Небе́сних.","Єди́наго імі́я врача́ Христа́, нікогда́же попусти́л єси́ себе́ в болі́зні врачева́ти, но глаго́лал єси́ со Апо́столом: мні є́же жи́ти Христо́с, а є́же умре́ти приобрі́теніє; і сим сло́вом сам свой неду́г ісціля́л єси́.","Богородичен: Ізнемо́гшую мою́ ду́шу от гріхо́в мно́гих, посіще́нієм Твої́м ісціли́, Госпоже́, і водо́ю благода́ті Твоєя́ напо́й м'я, да свобо́дь сий душе́вних і тіле́сних неду́гов, порабо́таю Тебе́, Влади́чице моє́й, со усе́рдієм всегда́."]},{"h":"Кондак, глас 8","ps":["Вся кра́сная ми́ра сего́ і тлі́нноє бога́тство нівочто́же вміни́в, обогати́лся єси́ мно́гими чудеси́ і зна́менії от Христа́ Бо́га, Єму́же во весе́лії предстоя́, помина́й нас, чту́щих любо́вію па́м'ять твою́, да зове́м ті: ра́дуйся, Нико́ло пречу́дне."]},{"h":"Ікос","ps":["А́нгельськи на землі́ пожи́вша і со А́нгельськими чи́ньми ни́ні сві́тло на Небесі́х лику́юща, тя, блаже́нне, си́ми ублажа́єм пі́сньми: ра́дуйся, ро́да сві́тлость і княже́ніє презрі́вий; ра́дуйся, бога́тство і сла́ву тще́тную попра́вий; ра́дуйся, нищ і убо́г, вся оста́вль, Го́сподеві послі́довавий; ра́дуйся, го́рдость низложи́вий і смире́нію прилежа́вий; ра́дуйся, вся послуша́нія монасти́рськая проше́дий; ра́дуйся, в тіх со вся́ким смире́нієм преби́вий; ра́дуйся, пова́рства і вра́тарства невозгнуша́вийся; ра́дуйся, бра́тій твої́х, князе́й, отверги́йся сожи́тельства; ра́дуйся, сам от не́мощі возмоги́й і врача́ ісціли́вий; ра́дуйся, спасе́ніє враче́ві моли́твами твої́ми ісхода́тайствовавий і свою́, і о́наго смерть прозрі́вий; ра́дуйся, бра́ту твоєму́ по уме́ртвії твоє́м ісціле́ніє пода́вий; ра́дуйся, всім те́плі тя призива́ющим чу́дний і ско́рий помо́щниче; ра́дуйся, Нико́ло пречу́дне."]},{"h":"Пісня 7","ps":["Ірмос: Не послужи́ша тва́рі Богому́дрії, па́че Созда́вшаго, но, о́гненноє преще́ніє му́жеськи попра́вше, ра́довахуся, пою́ще: препі́тий отце́в Госпо́дь і Бог, благослове́н єси́.","Приспів: Преподо́бне о́тче Нико́ло, моли́ Бо́га о нас.","От коли́кия сла́ви преше́л єси́, кня́же, глаго́лаше ті Петр, і укоря́ше тя, блаже́нне, я́ко всім рабо́таєши і сме́тищу приседи́ши, но ти отвіща́л єси́ єму́: не погуби́х че́сти моєя́, па́че же сим прославля́юся, послі́дуя всім прише́дшему послужи́ти Христу́, Єму́же і зову́, благослове́н Бог оте́ць на́ших.","Приспів: Преподо́бне о́тче Нико́ло, моли́ Бо́га о нас.","Тебі́ хотя́й в болі́зні Петр уврачева́ти, сам разболі́ся, єго́же не зе́лієм, но моли́твою ісціли́л єси́ і наказа́л того́ не наді́ятися на враче́бную хи́трость, но то́кмо на Бо́га упова́ти, зову́щи: препі́тий отце́в Бо́же, благослове́н єси́.","Приспів: Преподо́бне о́тче Нико́ло, моли́ Бо́га о нас.","Послуша́ніє твоє́ у врат скончава́я, прови́діл єси́, свя́те, по тріє́х мі́сяціх і живота́ твоєго́ кончи́ну, тім призва́л єси́ Петра́ і увіщава́л єси́, да восприї́меть зді і́ночеський о́браз і вмі́сто тебе́ послу́жить Бо́гу, І́же єсть благослове́нний во ві́ки.","Ізміне́ніє жи́зні твоєя́ сли́шав Петр, припаде́ со слеза́ми к нога́м твої́м, преподо́бне, рида́ющи, я́ко лиша́ється господи́на своєго́; ти же воздви́г єго́, утіша́л і увіщава́л єси́ не скорбі́ти о сем, но зва́ти: благослове́н Бог оте́ць на́ших.","Богородичен: Ізміне́нія жи́зні моєя́ скве́рних ра́ди діл не іму́ща, кто м'я не воспла́четь, отхожду́ бо в путь неві́дом. От путі́ за́повідей Си́на Твоєго́ уклони́хся, ті́мже, слезя́, призива́ю Тя, Влади́чице, скажи́ мні путь, і пойду́ во і́стині, поя́: Препі́тая єси́, Богоро́дице, і Благослове́нная от ро́да в род."]},{"h":"Пісня 8","ps":["Ірмос: О́троки благочести́вия в пещі́ Рождество́ Богоро́дичо спасло́ єсть, тогда́ у́бо образу́ємоє, ни́ні же ді́йствуємоє, вселе́нную всю воздвиза́єть пі́ти Тебі́: Го́спода по́йте діла́ і превозносі́те Єго́ во вся ві́ки.","Приспів: Преподо́бне о́тче Нико́ло, моли́ Бо́га о нас.","Благочестному́дренні пожи́в і при́сно прови́дя ісхо́д свой, преподо́бне Нико́ло, сам себе́ угото́вал єси́ мі́сто во святі́й пеще́рі, є́же Петру́ на моле́ніє єго́ дарова́л єси́, глаго́ля: бу́ди тебі́, а́ще хо́щеши і я́коже Госпо́дь восхо́щеть, превозноси́мий во ві́ки.","Приспів: Преподо́бне о́тче Нико́ло, моли́ Бо́га о нас.","Дерзнове́ніє імі́яй к Бо́гу і упова́ніє по ві́рі непоколеби́мо, прия́л єси́ прозрі́нія дар, і́мже уві́дав по тріє́х днех отше́ствіє Петро́во к Бо́гу, повелі́л єси́ тому́ угото́витися к сицево́му ісхо́ду; он же по словесі́ твоєму́ Свята́я Святи́х приє́м, оти́де ра́дуяся і поя́: превозноси́мий Бог во ві́ки.","Приспів: Преподо́бне о́тче Нико́ло, моли́ Бо́га о нас.","Три́десять літ по сме́рті врача́ свя́то пожи́в і ві́рно Го́сподеві порабо́тав, стори́чния ізрасти́л єси́ плоди́, с ни́миже отше́л єси́, блаже́нне, ко святи́х Святі́йшему Го́споду Ісу́су, поя́ і превознося́ Єго́ во ві́ки.","Твоє́ сла́вноє і честно́є успе́ніє лю́діє сли́шаще, стеко́шася от всего́ гра́да, да́ти тебі́ послі́днєє цілова́ніє і погребо́ша тя со слеза́ми, несе́ннаго с ра́достію А́нгелов на ло́но Авраа́мле, да та́мо со всі́ми святи́ми предстої́ши Го́сподеві во ві́ки.","Богородичен: Жизнь вре́менная скончава́ється, уви́ мні! Ка́мо несе́н бу́ду, всіх челові́к окая́ннійший: Судія́ ждеть, Кни́ги разгну́шася і по діло́м мої́м злих часть наслі́дити мі єсть ізві́стно; но пре́жде да́же не отиду́ отсю́ду со уго́дником Твої́м Нико́лою, моли́ся, Госпоже́, Си́ну Твоєму́ благи́х ча́сти мні наслі́дити."]},{"h":"Пісня 9","ps":["Ірмос: Всяк земноро́дний да взигра́ється, Ду́хом просвіща́єм, да торжеству́єть же Безпло́тних умо́в єстество́, почита́ющеє свяще́нноє торжество́ Богома́тере, і да вопіє́ть: ра́дуйся, Всеблаже́нная Богоро́дице, Чи́стая Присноді́во.","Приспів: Преподо́бне о́тче Нико́ло, моли́ Бо́га о нас.","Всяк от земноро́дних да подража́єть житію́ Богохва́льнаго отця́, той бо сла́ву вре́менную на землі́ презрі́л, і во сла́ву ві́чную преше́д, ни́ні ра́дується, імі́яй престо́л недви́жим в Небе́сних селе́ніїх, іді́же і о нас мо́лить, да бу́дем наслі́дници блаже́нния жи́зні.","Приспів: Преподо́бне о́тче Нико́ло, моли́ Бо́га о нас.","Всяк, люб'я́й М'я, Мні послі́дуєть, да бу́деть со Мно́ю. Сія́ Єва́нгельськая внуши́в словеса́, преблаже́нний Свято́ша, возлюби́в Бо́га, Тому́ послі́дова і нічто́же па́че Того́ любве́ стяжа́ в ми́рі, ті́мже ни́ні живе́ть со Христо́м в Сві́ті непристу́пнім.","Приспів: Преподо́бне о́тче Нико́ло, моли́ Бо́га о нас.","Реки́й: прославля́ющаго М'я просла́влю,— іспо́лни обіща́ніє на тебі́, свя́те; не то́кмо бо тя просла́ви сама́го дароноше́ньми, но і крест твой, возгла́вниця і власяни́ця сла́в'яться от бра́та твоєго́ і воспомина́ються да́же досе́лі, я́ко сла́вная от них сотвори́шася.","От ро́да в ро́ди па́м'ять твоя́ сла́виться, преподо́бне о́тче: труди́ же і по́двиги твоя́ хва́лить Це́рков с на́ми, но і мо́щі твоя́, содержа́щіяся во святі́й пеще́рі, явля́єть ра́ка і созива́єть всіх моли́ти тя ни́ні я́ко те́плаго предста́теля і засту́пника в неможе́нії на́шем.","Богородичен: От всіх племе́н сла́вимая і почте́нная от Тро́йці Пресвяти́я, нам, в пі́сніх хва́лящим Тя, Чи́стая Ді́во, Предста́тельниця бу́ди і Засту́пниця ско́рая от вра́жиїх наві́т, да ви́ну поє́м ті: ра́дуйся, Богоро́дице Присноді́во."]},{"h":"Світилен","ps":["Храм Ду́ха Пресвята́го бил єси́, і, прише́д Оте́ць с Си́ном, оби́тель в тебі́ сотвори́, і тім Боже́ственних прича́стієм ра́йськаго тя граждани́на показа́; в не́мже ни́ні от Разу́мнаго дре́ва пита́яся і нетлі́нния сла́ви наслажда́яся, пом'яни́ і нас, ві́рою кла́няющихся ра́ці моще́й твої́х, о́тче преподо́бне.","Слава, і нині: Храм пречи́стий вопло́щшемуся із Тебе́ Сло́ву била́ єси́, Ді́во; храм м'я вся́каго беззако́нія су́ща, сотвори́ храм узаконе́нних повелі́ній Си́на Твоєго́ предста́тельством Твої́м, да селе́ніє Бо́жия благода́ті бив, досто́йно воспою́ Тя, я́ко вся о Бо́зі могу́щую, Богоотрокови́це."]}],"notes":[]},{"u":"Канон священномученику Киприану і мучениці Іустині","e":"Canon to the Hieromartyr Cyprian and the Martyr Justina","secs":[{"h":"Глас 4. Пісня 1","ps":["Ірмос: Мо́ря чермну́ю пучи́ну невла́жними стопа́ми дре́вній пішеше́ствовав Ізра́їль, крестообра́знима Моїсе́йовима рука́ма Амали́кову си́лу в пусти́ні побіди́л єсть.","Приспів: Священному́чениче Киприя́не і му́ченице Іусти́но, молі́те Бо́га о нас.","С Преми́рними чи́ньми ни́ні водворя́яся, о свяще́нная і Боже́ственная главо́, с Небесе́ при́зри на благоче́стно пою́щия тя і твої́ми моли́твами сохраня́й.","Приспів: Священному́чениче Киприя́не і му́ченице Іусти́но, молі́те Бо́га о нас.","Во мра́ці неві́дінія, преподо́бне, лю́ті одержи́м і душегу́бними страстьми́ пло́ті невоздержа́нієм ти разжига́єм, преложе́ніє пресла́вно обрі́л єси́ внеза́пу, всеблаже́нне.","Губи́телей у́бо на сіда́лищі пре́жде, о́тче, сіді́л єси́ і на сіда́лищі пресви́теров па́ки Христа́ просла́вил єси́, ізміни́вся явле́нно Влади́чнею Боже́ственною благода́тію.","Богородичен: Ді́ва по рождестві́ пребила́ єси́: Сама́го бо ро́ждши Творця́ всіх і Го́спода, необи́чно і стра́нно нам я́вльшася ті́лом, Богороди́тельнице Ма́ти Присноді́во."]},{"h":"Пісня 3","ps":["Ірмос: Весели́ться о Тебі́ Це́рков Твоя́, Христе́, зову́щи: Ти моя́ крі́пость, Го́споди, і прибі́жище, і утвержде́ніє.","Приспів: Священному́чениче Киприя́не і му́ченице Іусти́но, молі́те Бо́га о нас.","Я́ко Па́вел, ко Христу́ душе́вную любо́в преложи́в, Киприя́не всему́дре, того́ учени́к бил єси́.","Приспів: Священному́чениче Киприя́не і му́ченице Іусти́но, молі́те Бо́га о нас.","Обруча́єть ті Христо́с, вмі́сто риз стра́стних одія́ніє сла́ви да́руя і возрожде́нія оде́жду.","Поу́стник по́стничеський пре́жде би́вий терпіли́в, по́сліжде, Киприя́не всехва́льне, свиді́тель І́стини бил єси́.","Богородичен: Госпо́дьственно і і́стинно Тя, Богоро́дицю, ві́рнії почита́єм, Ти бо Бо́га родила́ єси́, плоть би́вша, Всенепоро́чная."]},{"h":"Сідален, глас 8","ps":["Нака́зан в пре́лести приле́жно, я́ко Па́вел, зван бисть с Небесе́, Кресто́м наставля́єм к сві́ту зна́нія, честни́я бо ді́ви любо́вію разжига́єм, тоя́ ра́ди сочета́лся єси́ Зижди́телю челові́ков. Тім обличи́в не́мощ вра́жию, с не́ю сподо́бился єси́ ли́ку му́чеников, Киприя́не, архієре́єв удобре́ніє, моли́ Христа́ Бо́га гріхо́в оставле́ніє пода́ти честву́ющим любо́вію святу́ю па́м'ять твою́.","Богородичен: В напа́сти многоплете́нния впад от враг ви́димих і неви́димих, бу́рею одержи́м безчи́сленних согріше́ній мої́х, і, я́ко к те́плому заступле́нію і покро́ву моєму́, Чи́стая, ко приста́нищу притека́ю Твоєя́ бла́гости. Ті́мже, Пречи́стая, із Тебе́ Воплоще́нному без сі́мене моли́ся прилі́жно о всіх рабі́х Твої́х, непреста́нно моля́щихтися, Богоро́дице Пречи́стая, моля́щи Єго́ при́сно согріше́ній оставле́ніє дарова́ти воспіва́ющим досто́йно сла́ву Твою́.","Хрестобогородичен: А́гнця і Па́стиря, і Ізба́вителя А́гниця зря́щи на Кресті́, восклиця́ше, пла́чущи, і, го́рко рида́ющи, вопія́ше: мир у́бо ра́дується, приє́мля Тобо́ю ізбавле́ніє, утро́ба же Моя́ гори́ть, зря́щи Твоє́ расп'я́тіє, є́же терпи́ши за милосе́рдіє ми́лости. Долготерпіли́ве Го́споди, ми́лости бе́здно і істо́чниче неісчерпа́ємий, умилосе́рдися і да́руй согріше́ній оставле́ніє ві́рою пою́щим Боже́ственния Стра́сті Твоя́."]},{"h":"Пісня 4","ps":["Ірмос: Вознесе́на Тя ви́дівши Це́рков на Кресті́, Со́лнце пра́ведноє, ста в чи́ні своє́м, досто́йно взива́ющи: сла́ва си́лі Твоє́й, Го́споди.","Приспів: Священному́чениче Киприя́не і му́ченице Іусти́но, молі́те Бо́га о нас.","Возбну́в, Богогла́се, от неі́стовства пе́рваго, де́монськую лесть і душетлі́нную пре́лесть всю обличи́л єси́ і, ра́дуяся, взива́л єси́: сла́ва си́лі Твоє́й, Го́споди.","Приспів: Священному́чениче Киприя́не і му́ченице Іусти́но, молі́те Бо́га о нас.","До́блественно Іусти́на укріпля́єма і Чи́стую Ді́ву і Обра́дованную зіло́ моля́щи, сіте́й ізбіже́ і ко́зней же вра́жиїх.","Укріпля́єма ві́рою твоєго́ Жениха́ і Кре́стною си́лою оді́яна, де́мони нея́тна, вопію́щи, пребила́ єси́: сла́ва си́лі Твоє́й, Го́споди.","Богородичен: І́же єстество́м свобо́ден сий, о́бразом раба́ обнища́ бога́тством бла́гости, Ма́ти Присноді́во, із Тебе́ по Іпоста́си все приє́м челові́чество."]},{"h":"Пісня 5","ps":["Ірмос: Ти, Го́споди, мой світ, в мир прише́л єси́, Світ Святи́й, обраща́яй із мра́чна неві́дінія ві́рою воспіва́ющія Тя.","Приспів: Священному́чениче Киприя́не і му́ченице Іусти́но, молі́те Бо́га о нас.","Побо́рницю іму́щи я́ві Чи́стую Богома́тер, обога́щшися, Іусти́но, честно́є ді́вство сохрани́ла єси́ невре́дно.","Приспів: Священному́чениче Киприя́не і му́ченице Іусти́но, молі́те Бо́га о нас.","Одушевле́нний Христо́в і красні́йшій о́браз, почти́м Іусти́ну, сокрове́нную добро́ту і некра́домоє возложе́ніє.","Неві́ста Христо́ва при́сная і нескве́рная, страда́нієм і поще́нієм восприє́мши, пра́ведно сугу́б віне́ць но́сить.","Богородичен: Ум А́нгельський і челові́чеський не мо́жеть сказа́ти неізрече́ннаго і пресла́внаго чудесе́ Рождества́ Твоєго́, Всечи́стая."]},{"h":"Пісня 6","ps":["Ірмос: Пожру́ Ті со гла́сом хвале́нія, Го́споди, Це́рков вопіє́ть Ті, от бісо́вськия кро́ве очи́щшися, ра́ди ми́лости от ребр Твої́х істе́кшею Кро́вію.","Приспів: Священному́чениче Киприя́не і му́ченице Іусти́но, молі́те Бо́га о нас.","Зло́би дна преіспо́дняго доше́л єси́, ко кра́йнійшей же па́ки доброді́телі, о́тче, возше́л єси́ на висоту́, пресла́вно ізміни́вся Боже́ственним Креще́нієм.","Приспів: Священному́чениче Киприя́не і му́ченице Іусти́но, молі́те Бо́га о нас.","Бил єси́ служи́тель де́монов пе́рвіє, но Христо́в Богоявле́нний учени́к показа́лся єси́, при́сною любо́вію жела́ніє возлюби́в послі́днєє.","Мно́гія ти Влади́ці приве́л єси́ му́ченики, ку́плей велича́йшую явля́я, кро́вію малі́йшею Ца́рство Небе́сноє, Богому́дре, купи́ти.","Богородичен: Расто́ргни моя́ плени́ці согріше́ній, Богоневі́сто, гріхо́внаго зако́на, Жи́зні зако́ном свобо́ду да́рующи, Влади́ку зако́на ро́ждшая."]},{"h":"Кондак, глас 1","ps":["От худо́жества волше́бнаго обрати́вся, Богому́дре, к позна́нію Боже́ственному, показа́лся єси́ ми́ру врач мудрі́йший, ісціле́нія да́руя честву́ющим тя, Киприя́не со Іусти́ною: с не́юже моли́ся Человіколю́бцю Влади́ці спасти́ ду́ші на́ша."]},{"h":"Ікос","ps":["Ціле́ній твої́х, свя́те, дарова́нія мні низпосла́в, і неду́гующеє моє́ се́рдце гно́єм гріхо́вним моли́твами твої́ми ісціли́, я́ко да сло́во пі́нія от скве́рних усте́н мої́х ни́ні принесу́ ті і воспою́ болі́зні твоя́, я́же показа́л єси́, священному́чениче, покая́нієм до́брим і блаже́нним і Бо́гу приближа́ющимся. Того́ бо удержа́н руко́ю, напра́вился єси́, я́ко по лі́ствице, к Небе́сним, непреста́нно моля́ся спасти́ ду́ші на́ша."]},{"h":"Пісня 7","ps":["Ірмос: Спаси́й во огні́ Авраа́мськия Твоя́ о́троки і, халде́ї уби́в, я́же пра́вда пра́ведно уловля́ше, препі́тий Го́споди, Бо́же оте́ць на́ших, благослове́н єси́.","Приспів: Священному́чениче Киприя́не і му́ченице Іусти́но, молі́те Бо́га о нас.","На священнонача́льство вшед, свяще́ннійший о́браз священнонача́льником себе́ і пра́вило яви́л єси́, взива́я: препі́тий Го́споди, Бо́же оте́ць на́ших, благослове́н єси́.","Приспів: Священному́чениче Киприя́не і му́ченице Іусти́но, молі́те Бо́га о нас.","Живонача́льния тебі́ десни́ці і́стинно ізміне́ніє, о́тче, наше́дшеє, му́дра тя сотвори́ Боговіща́теля, пою́ща: препі́тий Го́споди, Бо́же оте́ць на́ших, благослове́н єси́.","Ору́жіє непобіди́моє нам на проти́внаго, блаже́нне, ти яви́лся єси́, того́ облича́я ле́сти, пою́щим: препі́тий Го́споди, Бо́же оте́ць на́ших, благослове́н єси́.","Богородичен: Небе́снії ли́ци і Пренебе́снії собо́ри пісносло́в'ять із Тебе́, Богоро́дице, Рожде́ннаго, зову́ще: препі́тий Го́споди, Бо́же оте́ць на́ших, благослове́н єси́."]},{"h":"Пісня 8","ps":["Ірмос: Весели́ся, Ієрусали́ме, торжеству́йте, лю́б'ящії Сіо́на: ца́рствуяй бо во ві́ки, Госпо́дь Сил при́йде. Да благогові́єть вся земля́ от Лиця́ Єго́ і да вопіє́ть: благослові́те, вся діла́ Госпо́дня, Го́спода.","Приспів: Священному́чениче Киприя́не і му́ченице Іусти́но, молі́те Бо́га о нас.","Прему́дро е́ллинськия му́дрости небре́гл єси́, сла́вне, апо́столов же Боже́ственноє віща́ніє, Ду́хом бряця́ємо, о́тче, і о́гненними язи́ки я́сно ізглаша́ємо, вопія́л єси́: благослові́те, вся діла́ Госпо́дня, Го́спода.","Приспів: Священному́чениче Киприя́не і му́ченице Іусти́но, молі́те Бо́га о нас.","Восте́кл єси́ на висо́кая і преми́рная сві́тло селе́нія, Христу́ кро́вію, я́ко же́ртвою непоро́чною, приноси́м, о́тче, заколе́ніє жи́во, прия́тно і благоуго́дно, воспіва́я: благослові́те, вся діла́ Госпо́дня, Го́спода.","Побіжда́єми от в тебі́ все́льшіяся благода́ті, де́монстії полці́ отгоня́ються і отбіга́ють стра́сті неду́гующих, Богому́дре, ві́рнії же Боже́ственнаго сві́та насища́ємся, вопію́ще: благослові́те, вся діла́ Госпо́дня, Го́спода.","Богородичен: Лику́ють со А́нгельськими, Пречи́стая, си́лами о Рождестві́ Твоє́м, Богома́ти, і Богоро́дицю ві́рою Тя імену́ющії: Ти бо Влади́ку і Ізба́вителя нам родила́ єси́, Єму́же поє́м: благослові́те, вся діла́ Госпо́дня, Го́спода."]},{"h":"Пісня 9","ps":["Ірмос: Є́ва у́бо неду́гом преслуша́нія кля́тву всели́ла єсть, Ти же, Ді́во Богоро́дице, Прозябе́нієм чревоноше́нія ми́рові благослове́ніє процвіла́ єси́, тім Тя всі велича́єм.","Приспів: Священному́чениче Киприя́не і му́ченице Іусти́но, молі́те Бо́га о нас.","Сви́ше нас, благоче́стно пою́щих тя, назира́єши Боже́ственною благода́тію, твої́ми моли́твами, Богоглаго́льниче, і ору́жієм благоволе́нія вінчава́я, мир і спасе́ніє да́руй нам, я́ко священнонача́льник Боже́ственнійший.","Приспів: Священному́чениче Киприя́не і му́ченице Іусти́но, молі́те Бо́га о нас.","Тече́ніє ісціле́ній оби́льно персть твоя́ лю́б'ящим тя воздає́ть; тебі́ же, Киприя́не, жени́ Богоно́сни я́ко Боже́ственно сокро́вище приє́млють і усе́рдно явля́ють сокрове́ннаго, да всі тебі́ наслади́мся.","Напра́вити на́ше ко Христу́, пребога́те, ше́ствіє дія́нієм, і Богоуго́дним житіє́м, і чисті́йшим очище́нієм су́що Бо́жию ти́хость умоли́, я́ко ієра́рх сострада́тельнійший.","Богородичен: Укріпи́ на́шу душе́вную не́мощ, Богома́ти, си́лою Твоє́ю, разріши́ тяготу́, Пресвята́я, налага́ємую рабо́м Твої́м, ми́ру пра́вди Со́лнце несказа́нно возсія́вшая."]},{"h":"Світилен","ps":["Во волхва́х несосужде́нна і єди́наго пребо́льша, премі́ншаго нрав і попали́вшаго кни́ги, наставля́ющия ко пре́лести, і свиді́тельства віне́ць страннолі́пно приє́мшаго, Киприя́на похва́лим, страда́льцев зерца́ло.","Богородичен: Дре́вле божества́ наде́ждею прельсти́вий м'я злоко́зненний, пло́тним предложе́нієм прему́дренно па́ки прельща́ється от Ді́ви Возсія́вшаго; і си́це осужде́ніє пло́тноє пло́тію разріши́ся, сме́рті умертви́вшейся."]}],"notes":[]},{"u":"Канон преподобному Максиму Греку","e":"Canon to St Maximus the Greek","secs":[{"h":"Пісня 1","ps":["Ірмос: Пої́м, всі лю́діє, от го́ркия рабо́ти фарао́ні Ізра́їля ізмі́ншему і во глубині́ морсті́й нога́ми немо́крими Наста́вльшему піснь побі́дную, я́ко просла́вися.","Приспів: Преподо́бне о́тче Макси́ме, моли́ Бо́га о нас.","Воспі́ти кий язи́к возмо́жеть по достоя́нію твоя́, преди́вний о́тче, ве́лія ісправле́нія, висо́коє учи́тельство, в темни́ці і во у́зах му́ченичеськоє страда́ніє і долготерпі́ніє?","Приспів: Преподо́бне о́тче Макси́ме, моли́ Бо́га о нас.","Ка́ко воспоє́м і что тя нарече́м, предо́блій о́тче? Проро́ка ли, я́ко провіща́ неудо́б разуміва́ємая і ві́домая нам, апо́стола ли, я́ко зи́блемую проти́вними нам ві́три утверди́ христия́нськую ві́ру Боже́ственних писа́ній уче́нії, учи́теля ли, но воі́стину ничи́м же ху́ждши і ни́жши єси́ вели́ких о́ніх вселе́нських учи́тель.","Воспі́ти Свята́го і поклоня́ємаго Паракли́та в темни́ці ізвіще́ніє от А́нгела, приї́м, сотвори́л єси́ кано́н Свято́му Ду́ху, І́мже єще́ во во́лі просвіще́н, свяще́нния і Богодухнове́нния кни́ги соста́вил єси́.","Богородичен: Пої́м, всі лю́діє, святи́ню і сла́ву Пречи́стия і Всепі́тия Бо́жия Ма́тере, ви́шшую Небе́с і всіх у́мних Сил, поноси́вшую в пречи́стой Своє́й утро́бі Емману́їла, я́ко свя́та і пресла́вна єсть."]},{"h":"Пісня 3","ps":["Ірмос: Утверди́ мене́, Христе́, на недви́жимом ка́мені за́повідей Твої́х і просвіти́ м'я сві́том лиця́ Твоєго́: ність бо свят, па́че Тебе́, Человіколю́бче.","Приспів: Преподо́бне о́тче Макси́ме, моли́ Бо́га о нас.","Утверди́л єси́, преподо́бне Макси́ме, в се́рдці своє́м Боже́ственний страх, вся по́хоті плотська́я возненави́дів, сего́ ра́ди умудри́лся єси́, я́коже прост младе́нець, і вслід Го́сподеві восте́кл єси́.","Приспів: Преподо́бне о́тче Макси́ме, моли́ Бо́га о нас.","Утвержде́нієм імі́я распе́ншагося Го́спода Ісу́са Христа́, стра́нен, незна́єм, бездо́мен, безоте́чествен, безиме́нен, безсми́слен бил єси́, преподо́бне Макси́ме, пред свої́ми сро́дники, зна́ємими і дру́ги.","Утвержда́яся на за́повідіх Госпо́дніх, от го́рести темни́чния бил єси́ на мног час, я́ко мертв, но ді́ял єси́ о злонра́вних моли́тву, си́це глаго́ля: Го́споди, Ісу́се Христе́, Си́не Бо́га Жива́го, не поста́ви їм гріха́ сего́, клеве́щущих на м'я непра́вду.","Богородичен: Утверди́ нас ко хвале́нію Твоєму́, Ді́во, і сохрани́ без вре́да от вся́кия ко́зні лука́ваго, і сподо́би стоя́нія одесну́ю Єдиноро́днаго Си́на Твоєго́, Єму́же подоба́єть вся́кая сла́ва, честь і поклоне́ніє во ві́ки віко́в."]},{"h":"Сідален, глас 4","ps":["Ум украси́в поуче́нії Богодохнове́нних Писа́ній, тре́звенною моли́твою і бді́нії Богоуго́дними, утверди́л єси́ се́рдце своє́ в Го́споді ісполне́нієм за́повідей спаси́тельних Єго́, сего́ ра́ди прославля́ють тя ви́ну українськії лю́діє і Афо́н, і оби́тель Ватопе́дськая вку́пі с на́ми вопіє́ть: Макси́ме прему́дре, не оста́ви нас, моля́щихся тебі́."]},{"h":"Пісня 4","ps":["Ірмос: Ве́лія та́йна Твоєго́, Христе́, смотре́нія: сію́ бо сви́ше прови́дя богозри́тельно, Авваку́м, ізше́л єси́, вопія́ше Тебі́, во спасе́ніє люде́й Твої́х, Человіколю́бче.","Приспів: Преподо́бне о́тче Макси́ме, моли́ Бо́га о нас.","От та́йних єрети́чеських лжеуче́ній нічто́же утаї́ся от тебе́, преподо́бне Макси́ме, но благода́тію Свята́го і поклоня́ємаго Ду́ха вся тебі́ открове́на суть.","Приспів: Преподо́бне о́тче Макси́ме, моли́ Бо́га о нас.","Та́їнственних догма́тов Правосла́вния ві́ри не то́чію побо́рника і́стинна і ві́рна себі́ показа́, но і па́че прео́стра сіки́ра на вся, я́же под небесе́м, є́ресі яви́лся єси́.","Я́ко та́їн Свята́го Ду́ха строї́тель, і Небе́снаго жи́тельства рачи́тель, і зако́на Госпо́дня учи́тель воі́стину показа́лся єси́, прему́дре Макси́ме.","Богородичен: Ве́лію та́їнству Мойсе́й Богови́дець науче́н, зря купину́ неопали́му: купина́ – не́мощ челові́чеськаго єстества́, огнь же – Божество́ Єдиноро́днаго Си́на Ви́шняго, і́бо Бог наш – огнь єсть, пояда́яй гріхи́ на́ша, я́коже Боже́ственний апо́стол рече́."]},{"h":"Пісня 5","ps":["Ірмос: От но́щі у́тренююще, поє́м Тя, Христе́, Отцю́ Собезнача́льна і Спа́са душ на́ших, мир ми́рові пода́ждь, Человіколю́бче.","Приспів: Преподо́бне о́тче Макси́ме, моли́ Бо́га о нас.","Но́щію луна́, днем со́лнце просвіща́ють і веселя́ть твар всю ви́димую, житіє́ же і прему́дрость святи́х просвіща́ють і веселя́ть ду́ші всіх челові́ков, хотя́щих спасти́ся і в ра́зум і́стини прийти́. Си́це і писа́нія преподо́бнаго Макси́ма Гре́ка, я́ко богодухнове́нния труди́, велегла́сно вопію́ть.","Приспів: Преподо́бне о́тче Макси́ме, моли́ Бо́га о нас.","В нощі́ моля́щуся тебі́ в темни́ці, Богонача́льния і Преблаги́я Тро́йці про́мислом внем А́нгел Госпо́день і рече́: о ста́рче! Си́ми му́ками ізбу́деши ві́чних мук.","В нощі́, я́ко сладкогла́сний і добропі́снивий сла́вій, воспі́л єси́, прему́дре Макси́ме: не тужи́, не скорби́, ніже́ тоску́й о ни́хже, – любе́зна мі душе́, – стра́ждеши без пра́вди, твоя́ бо мзда ве́лія на Небесі́х.","Богородичен: От но́щі у́тренююще, поє́м Тя, Ді́во, Дщер Царе́ву, ря́сни злати́ми оді́яну і преіспещре́ну, лі́ствицю, ю́же Іа́ков ви́ді, го́ру, ю́же благоволи́ Бог жи́ти в ней, і́бо Госпо́дь всели́ться до конця́."]},{"h":"Пісня 6","ps":["Ірмос: Проро́ка спасл єси́ от ки́та, Человіколю́бче, і мене́ із глубини́ прегріше́ній возведи́, молю́ся.","Приспів: Преподо́бне о́тче Макси́ме, моли́ Бо́га о нас.","Проро́чеськи, преподо́бне Макси́ме, лю́ди облича́л єси́, к покая́нію приводя́: заблуди́хом, заблуди́хом от пра́ваго і незаблу́днаго жи́тельства преподо́бних і́нок і без ума́ тече́м к по́чести ви́шняго зва́нія.","Приспів: Преподо́бне о́тче Макси́ме, моли́ Бо́га о нас.","Проро́к покая́нія яви́лся єси́, преподо́бне Макси́ме, душі́ трезві́ніє снабдіва́я Боже́ственними словеси́ і із ро́ва страсте́й возводя́ омраче́нних гріхми́.","Проро́чеськия писа́нія, в та́йні глаго́ланния, я́вни соді́лал єси́, прему́дре Макси́ме, сего́ ра́ди послу́шають тя оби́льно всі лю́діє.","Богородичен: Проро́ки Тя провозвісти́ша, Ді́во Чи́стая, апо́столи пропові́даша, святі́ї всі ублажи́ша, ми же со Арха́нгелом вопіє́м: ра́дуйся, Благода́тная, Госпо́дь с Тобо́ю."]},{"h":"Кондак, глас 8","ps":["Богодухнове́нним Писа́нієм і Богосло́вія пропові́данієм неві́рствующих суєму́дріє обличи́л єси́, всебога́те, па́че же, в Правосла́вії ісправля́я, на стезю́ і́стиннаго позна́нія наста́вил єси́, я́коже свирі́ль Богогла́сная, услажда́я сли́шащих ра́зуми, непреста́нно весели́ши, Макси́ме досточу́дне, сего́ ра́ди мо́лим Тя: моли́ Христа́ Бо́га гріхо́в оставле́ніє низпосла́ти ві́рою пою́щим всесвято́є твоє́ успе́ніє, Макси́ме, о́тче наш."]},{"h":"Ікос","ps":["Ка́ко воспоє́м велича́йшему тезоімени́таго, Макси́ма предо́бляго? Преподо́бних кра́сна вінця́, страда́льцев тве́рдаго пра́вила, єретико́в нело́жнаго посрамле́нія, Це́ркві столпа́ непоколеби́маго, ді́вственник ізві́стнаго наста́вника і супру́жества честна́го засту́пника, филосо́фов прему́дршаго мудреця́, і́стини істо́чника приснотеку́щаго, і́нок похвалу́ і всіх люде́й воі́стину украше́ніє, сего́ ра́ди мо́лим тя, досточу́дне Макси́ме: моли́ Христа́ Бо́га гріхо́в оставле́ніє низпосла́ти ві́рою пою́щим всесвято́є твоє́ успе́ніє, Макси́ме, о́тче наш."]},{"h":"Пісня 7","ps":["Ірмос: О́бразу служи́ти, мусикі́йському согла́сію созива́ющу лю́ди, от пі́сней сіо́нських пою́ще оте́чеськи, о́троци Дави́дови мучи́телево разори́ша злочести́воє велі́ніє і пла́мень в ро́су преложи́ша, піснь воспіва́юще: превозноси́мий отце́в і наш Бо́же, благослове́н єси́.","Приспів: Преподо́бне о́тче Макси́ме, моли́ Бо́га о нас.","О́бразу промишле́нія Пресвяти́я Тро́йці піснь благода́рственну возда́в, преподо́бне Макси́ме, вся ни призва́л єси́ благослови́ти небла́зненно Отця́, і Си́на, і Свята́го Ду́ха, Єди́наго Бо́га в Тріє́х Іпоста́сіх.","Приспів: Преподо́бне о́тче Макси́ме, моли́ Бо́га о нас.","О́браз злострада́нія, терпі́нія і моли́тви показа́лся єси́, свя́те Макси́ме, па́че же і упова́нія, я́ко Бог Судія́ пра́веден, і крі́пок, і долготерпіли́в єсть, і Той возда́сть коєму́ждо по діло́м єго́.","О́браз преви́спренняго Богосло́вія стяжа́л єси́, прему́дре Макси́ме, сії́ єсть догма́ти Боже́ственних апо́стол і оте́ць, от Свята́го Паракли́та ізлія́нния, і́мже і нас науча́єши Богому́дрими свої́ми писа́нії.","Богородичен: О́браз пречи́стаго Твоєго́ рождества́, Ді́во Ма́ти, неізрече́нен і недові́дом єсть, Ти бо вселе́ніє преві́чнаго Єдиноро́днаго Си́на О́тча била́ єси́, не опали́вшися от Него́."]},{"h":"Пісня 8","ps":["Ірмос: В пла́мені о́гненні горя́щия пе́щі сохра́ншаго ді́ти і во зра́ці А́нгела снизше́дшаго к ним по́йте Го́спода і превозносі́те Єго́ во ві́ки.","Приспів: Преподо́бне о́тче Макси́ме, моли́ Бо́га о нас.","Пла́мене Боже́ственнаго Паракли́това облиста́нія возжелі́в, преподо́бне Макси́ме, сего́ ра́ди і сладча́йшим сві́том уче́нія і чуде́с огне́м отгна́л єси́ вся́кий мрак бісо́вський.","Приспів: Преподо́бне о́тче Макси́ме, моли́ Бо́га о нас.","Пла́мене геє́ннськаго бі́гати лю́ди научи́л єси́, преподо́бне Макси́ме, сих призива́я ді́лом соверша́ти за́повіді Христо́ви і отступи́ти зло́би, блуда́, лжі, го́рдості, льсти і хище́нія непра́веднаго чужи́х імі́ній.","Пла́менно нече́стіє єрети́чеськоє попали́л єси́, прему́дре Макси́ме, ві́ри же христия́нськия непоро́чния Боже́ственноє іспові́даніє із'ясни́в.","Богородичен: В пла́мені о́гненні горя́щия купини́ ви́ді Тя Мойсе́й Богови́дець, провозвісти́в безсі́менноє рождество́ Твоє́, Ді́во Пречи́стая, сего́ ра́ди і нас плотськи́х страсте́й свободи́."]},{"h":"Пісня 9","ps":["Ірмос: Тебі́, сві́тлую свіщу́ і Ма́тер Бо́жию, пречу́дную сла́ву і ви́шшую всіх тва́рей, пі́сньми велича́єм.","Приспів: Преподо́бне о́тче Макси́ме, моли́ Бо́га о нас.","Тебі́, сві́тлую свіщу́, і ум кра́йнійший, і столп непоколеби́м ві́ми, па́че же наста́вника мона́хов і єресе́й наказа́теля пропові́дуєм.","Приспів: Преподо́бне о́тче Макси́ме, моли́ Бо́га о нас.","Сві́тло от полу́денних стран возсія́л єси́, преподо́бне Макси́ме, сві́тло житіє́ показа́в, мрак лука́вствія прогоня́я і благоприя́тною моли́твою просія́в.","Свіща́ Боже́ственнаго ра́зума бив, дости́гл єси́ в позна́ніє Си́на Бо́жия, в му́жа соверше́нна, в мі́ру во́зраста Христо́ва, сего́ ра́ди і ми вопіє́м ті: блаже́н ти єси́ воі́стину по всему́, і по́двиги, і сла́вою, і благода́тію, я́же єси́ сви́ше получи́л.","Богородичен: Тебі́, і сві́тлую свіщу́ в нощі́ страсте́й, і покро́в благости́ні, і сті́ну необори́му от наві́т вра́жиїх, пі́сньми велегла́сно велича́єм."]},{"h":"Світилен","ps":["Світ возсія́л єсть преподо́бному Макси́му Боже́ственних слове́с і повелі́ній, сего́ ра́ди я́ко світ втори́й і ум кра́йнійший нам яви́ся."]}],"notes":[]},{"u":"Канон апостолу і євангелісту Матфею","e":"Canon to the Apostle and Evangelist Matthew","secs":[{"h":"Глас 4. Пісня 1","ps":["Ірмос: Отве́рзу уста́ моя́, і напо́лняться Ду́ха, і сло́во отри́гну Цари́це Ма́тері, і явлю́ся, сві́тло торжеству́я, і воспою́, ра́дуяся, Тоя́ чудеса́.","Приспів: Святи́й апо́столе і євангели́сте Матфе́є, моли́ Бо́га о нас.","Бога́тно пода́ждь мі все́льшуюся в тя благода́ть, Матфе́є всесла́вне і слуго́ Христо́в, да вопію́, сві́тло пропові́дая, і воспою́, ра́дуяся, твоя́ чудеса́.","Приспів: Святи́й апо́столе і євангели́сте Матфе́є, моли́ Бо́га о нас.","Весьма́ оста́вил єси́ земни́х смуще́ніє, Сло́ва бо я́ко усли́шав вопло́щшагося глас, і благода́ті яви́лся єси́ строї́тель і пропові́датель богоприя́тен, богоблаже́нне.","Самови́дець бив і слуга́ возсія́вшаго Сло́ва, апо́столе, Преві́чнаго Отця́, і проте́кл єси́, Того́ прише́ствіє благовіству́я всім язи́ком.","Богородичен: Сме́рті потребле́ніє і тлі разруше́ніє, Жи́зні же явле́ніє благовісти́л єси́, му́дре, Ді́ва бо во утро́бі заче́нши Непости́жнаго і мир обнови́."]},{"h":"Пісня 3","ps":["Ірмос: Твоя́ пісносло́вці, Богоро́дице, живи́й і незави́стний Істо́чниче, лик Себі́ совоку́пльшія, духо́вно утверди́, в боже́ственній Твоє́й сла́ві, вінце́в сла́ви сподо́би.","Приспів: Святи́й апо́столе і євангели́сте Матфе́є, моли́ Бо́га о нас.","Твоя́ апо́столи, Сло́ве Бо́жий, світи́льники показа́л єси́ жи́зні, мрак отгоня́ющия безбо́жия, Влади́ко, і Боже́ственною Твоє́ю сла́вою мир весь просвіща́ющия.","Приспів: Святи́й апо́столе і євангели́сте Матфе́є, моли́ Бо́га о нас.","Твої́м вооружи́во всеору́жієм Матфе́я хра́брійшаго, Спа́се, мучи́телей кріпча́йша сего́ соді́ял єси́, Влади́ко, і потреби́теля показа́л єси́ і́дольськия ле́сти, Человіколю́бче.","Язи́ка твоєго́ о́гненнаго віща́ніє де́монськая пожже́ ка́пища, Матфе́є богодохнове́нне, Паракли́тов орга́не, чрез Єго́же Христо́с пропові́дається, всіх Жизнь Іпоста́сная.","Богородичен: Труба́ богосло́вная, віща́ющая крі́пко, просвіти́ лю́ди, Матфе́я богому́драго, Тро́йці сія́ніє, па́че ума́ же воплоще́ніє Сло́ва із Тебе́, Пречи́стая."]},{"h":"Сідален, глас 8","ps":["Во вся конці́ протече́ му́дрих твої́х глаго́л я́ко воі́стину віща́ніє, всехва́льне Госпо́день апо́столе, боговиді́ніє всім я́сно пропові́дал єси́ і язи́ков неразу́міє в ра́зум приве́л єси́. Ті́мже, і́дольськоє омраче́ніє отгна́в, світ зна́нія во тьмі су́щим возсія́л єси́, Матфе́є всехва́льне, моли́ Христа́ Бо́га гріхо́в оставле́ніє дарова́ти чту́щим любо́вію святу́ю па́м'ять твою́.","Слава: Я́ко світи́льника Сві́та і ученика́, я́ко самови́дця Сло́ва боже́ственнаго всі хва́лим тя, Госпо́день апо́столе, і́бо, благода́тния твоя́ мре́жі простира́я, слове́сния ри́би уловля́єши повелі́нієм. Ті́мже і язи́ци уловля́хуся си́лою Ду́ха, наставля́ємі ві́рою, неботаї́нниче всехва́льне, моли́ Христа́ Бо́га гріхо́в оставле́ніє дарова́ти чту́щим любо́вію святу́ю па́м'ять твою́.","І нині: Я́ко Всенепоро́чная Неві́сто Творця́, я́ко Неіскусому́жная Ма́ти Ізба́вителя, прия́телище я́ко су́щи Уті́шителя, Препі́тая, беззако́нію м'я су́ща скве́рноє оби́телище і де́моном ігра́лище в ра́зумі би́вша, потщи́ся от тіх злоді́йства м'я ізба́вити і сві́тлоє жили́ще доброді́телей соверши́, Світоно́сная Нетлі́нная, отжени́ о́блак страсте́й і ви́шняго прича́стія сподо́би і Сві́та невече́рняго моли́твами Твої́ми."]},{"h":"Пісня 4","ps":["Ірмос: Неізслі́дний Бо́жий сові́т, є́же от Ді́ви воплоще́нія Тебі́, Ви́шняго, проро́к Авваку́м усмотря́я, зов'я́ше: сла́ва си́лі Твоє́й, Го́споди.","Приспів: Святи́й апо́столе і євангели́сте Матфе́є, моли́ Бо́га о нас.","Іпоста́сному Твоєму́ Сло́ву, Бо́же, науче́н, мирську́ю му́дрость разруши́ богови́дець учени́к, велегла́сно зов'я́ Тебі́: сла́ва си́лі Твоє́й, Го́споди.","Приспів: Святи́й апо́столе і євангели́сте Матфе́є, моли́ Бо́га о нас.","Ублаже́нному от Христа́, ко́є благохвале́ніє принесе́м тебі́, богоглаго́ливе? Не мо́жеть бо челові́к цвітя́щия на тебі́ благода́ті сло́вом ізрещи́, досточу́дне.","Нескве́рний твой і чи́стий ум ви́дів Височа́йший, я́коже свіщу́ на сві́щник висо́кий, су́щим во тьмі світя́щую, всім, богоявле́нне, предложи́.","Богородичен: Умерщвле́нноє єстество́ челові́чеськоє, Благослове́нная, возви́сила єси́, я́ко Височа́йшаго ро́ждшая крі́пость па́че єстества́, всепі́тая Отрокови́це, я́коже Матфе́й научи́."]},{"h":"Пісня 5","ps":["Ірмос: Ужасо́шася вся́чеськая о Боже́ственній сла́ві Твоє́й: Ти бо, неіскусобра́чная Ді́во, імі́ла єси́ во утро́бі над всі́ми Бо́га, і родила́ єси́ Безлі́тнаго Си́на, всім, воспіва́ющим Тя, мир подава́ющая.","Приспів: Святи́й апо́столе і євангели́сте Матфе́є, моли́ Бо́га о нас.","Благода́ть приє́м Всесвята́го Ду́ха, Боже́ственноє оби́телище показа́лся єси́; боже́ственно научи́в богозна́нія сві́ту, вві́рен бил догма́ти Христо́ви писме́ни ізложи́ти, я́ко самови́дець богоізбра́нний.","Приспів: Святи́й апо́столе і євангели́сте Матфе́є, моли́ Бо́га о нас.","Язи́к твой трость Паракли́та бисть, ско́роє ізбавле́ніє даю́щаго позна́вшим влади́чество Єго́ і му́дрих вди́шущаго душа́м ра́зум небе́сний, о Матфе́є всече́стне.","Сія́юща чудеси́ і ісціле́ній благода́тьми, тя Христо́с посла́ ми́ру, де́монськую попира́юща крі́пость і ду́ші просвіща́юща ві́рних, всіх пою́щих тя, ми́ра пропові́дника.","Богородичен: Ді́ва родила́ єси́ Си́на Преві́чнаго, в єстество́ обле́кшася челові́чеськоє, я́коже науча́я, богоглаго́ливий рече́, і спа́сшаго сіє́ от тлі коне́чною благости́нею, і Ді́ва пребила́ єси́."]},{"h":"Пісня 6","ps":["Ірмос: Прийдо́х во глубини́ морськи́я, і потопи́ла м'я єсть бу́ря мно́гих гріхо́в, но я́ко Бог із глубини́ возведи́ живо́т мой, Многоми́лостиве.","Приспів: Святи́й апо́столе і євангели́сте Матфе́є, моли́ Бо́га о нас.","Євангели́ст от ми́тарства я́ко послі́дова Тебі́, претвори́ся богоглаго́ливий всеси́льною Твоє́ю, Вседі́телю, крі́постію, Матфе́й всеїзря́днійший.","Приспів: Святи́й апо́столе і євангели́сте Матфе́є, моли́ Бо́га о нас.","Управля́ється твоєго́ благові́стія душепита́тельними словеси́ язи́ков мно́жество, возвиша́ємо к доброді́телей висо́кому верху́, о Матфе́є всеблаже́нне.","Матфе́я уловля́ються богоплете́нними ученика́ мре́жами собо́ри ві́рующих всегда́, к Твоєму́ позна́нію, Благоді́телю, наставля́ємі.","Богородичен: Ді́ву ро́ждшую воспису́я, благовіству́єть Тя, вся́чеськая Сотво́ршаго, без сі́мене і тлі, Всенепоро́чная, Матфе́й всеїзя́щнійший."]},{"h":"Кондак, глас 4","ps":["Мита́рства і́го отве́рг, пра́вди і́гу припря́глся єси́ і яви́лся єси́ купе́ць всеїзря́днійший, бога́тство прине́с ю́же с висоти́ прему́дрость. Отону́дуже пропові́дал єси́ і́стини сло́во і уни́лих воздви́гл єси́ ду́ші, написа́в час су́дний."]},{"h":"Ікос","ps":["Вра́жиє мучи́тельство ну́дить м'я неси́тно і душі́ моєя́ все сі́м'я восхища́єть, Матфе́є, дру́же Христо́в. Но сам, сі́м'я моли́тв твої́х дав, уплоди́ к твоєму́ служе́нію і покажи́ м'я піснопі́вця твоєго́ малі́йшаго і сказа́теля мно́гих твої́х і вели́ких ісправле́ній; і ко Христо́ві любві́ ка́ко, вся а́біє оста́вив, послі́довал єси́ те́плі Зва́вшему, пе́рвий бив благові́стник в ми́рі, написа́в час су́дний."]},{"h":"Пісня 7","ps":["Ірмос: Не послужи́ша тва́рі богому́дрії, па́че Созда́вшаго, но, о́гненноє преще́ніє му́жеськи попра́вше, ра́довахуся, пою́ще: препі́тий отце́в Госпо́дь і Бог, благослове́н єси́.","Приспів: Святи́й апо́столе і євангели́сте Матфе́є, моли́ Бо́га о нас.","Бил єси́ пе́рваго осія́нія боже́ственноє ізображе́ніє, я́ко учени́к Того́ світлостьми́ распаля́єм, Єму́же, поя́, глаго́лал єси́: препі́тий отце́в Госпо́дь і Бог, благослове́н єси́.","Приспів: Святи́й апо́столе і євангели́сте Матфе́є, моли́ Бо́га о нас.","Я́ко слуга́ Сло́ва, всеблаже́нне, в Боже́ственния оби́телі, іді́же Христо́с обита́єть, ти всели́лся єси́, я́коже тебі́ обіща́ пребоже́ственний отце́в Госпо́дь і Бог єди́н всіх.","Неду́зі, Матфе́є, отго́няться, і отбіга́єть мно́жество де́монов су́щими в тебі́ дарова́ньми Боже́ственнаго Ду́ха, в ни́хже піл єси́: препі́тий отце́в Госпо́дь і Бог, благослове́н єси́.","Богородичен: Всепі́тую Ді́ву написа́л єси́ боже́ственними твої́ми словеси́, Творця́ всіх ро́ждшую, апо́столе, Єму́же всі поє́м: препі́тий отце́в Госпо́дь і Бог, благослове́н єси́."]},{"h":"Пісня 8","ps":["Ірмос: О́троки благочести́вия в пещі́ Рождество́ Богоро́дичо спасло́ єсть, тогда́ у́бо образу́ємоє, ни́ні же ді́йствуємоє, вселе́нную всю воздвиза́єть пі́ти Тебі́: Го́спода по́йте, діла́, і превозносі́те Єго́ во вся ві́ки.","Приспів: Святи́й апо́столе і євангели́сте Матфе́є, моли́ Бо́га о нас.","Манове́ньми, я́же в Тебі́ неосла́бними, Матфе́й свяще́ннійший обожа́єм, положе́нієм же бив, єстество́м є́же бил єси́, вселе́нную, Влади́ко, привлече́ пі́ти Тебі́: Го́спода по́йте діла́ і превозносі́те во вся ві́ки.","Приспів: Святи́й апо́столе і євангели́сте Матфе́є, моли́ Бо́га о нас.","Я́коже мо́лнію вселе́нній, Сло́во богосло́ва посла́, мрак у́бо отгоня́ща, язи́ки же просвіща́юща богосло́вія догма́ти. Ті́мже і поя́ше: Го́спода по́йте діла́ і превозносі́те Єго́ во вся ві́ки.","Сло́вом чи́стим і умо́м Бог с тобо́ю бесі́довал єсть, ти́ну бо я́ко ізсі́кл єси́, Тому́ прибли́жился єси́ і приміси́лся єси́, сла́вне. Ті́мже і поє́ши: Го́спода по́йте діла́ і превозносі́те Єго́ во вся ві́ки.","Богородичен: На благодія́ніє челові́ков Сло́во воплоти́тися ізво́ли: двер бо ді́вства про́йде Госпо́дь і Богоро́дицю показа́. Ті́мже зове́м: Го́спода по́йте діла́ і превозносі́те Єго́ во вся ві́ки."]},{"h":"Пісня 9","ps":["Ірмос: Всяк земноро́дний да взигра́ється, Ду́хом просвіща́єм, да торжеству́єть же безпло́тних умо́в єстество́, почита́ющеє свяще́нноє торжество́ Богома́тере, і да вопіє́ть: ра́дуйся, Всеблаже́нная Богоро́дице, Чи́стая Присноді́во.","Приспів: Святи́й апо́столе і євангели́сте Матфе́є, моли́ Бо́га о нас.","Добро́ти у́мния прия́л єси́ діади́му боже́ственную, апо́столе, і Ца́рствія же благолі́пнійшим вінце́м украси́лся єси́ десни́цею Вседержи́телевою, і сві́тишися, му́дре, со а́нгели престо́лу предстоя́ Влади́ки Христа́, всеблаже́нне.","Приспів: Святи́й апо́столе і євангели́сте Матфе́є, моли́ Бо́га о нас.","Дре́ва жи́зні досто́йно получи́л єси́, пропові́дник Жива́го Бо́га, благовіствова́в жизнь ми́ру Боже́ственноє посіще́ніє: са́дом бо зна́нія не растли́л єси́ ум, преби́в нези́блен і неколе́блен Це́ркве степе́нь, всеблаже́нне.","Неві́сту Христо́ву боже́ственно украси́л єси́ Єва́нгелієм твої́м, я́ко дияди́мою, Це́рков, богоблаже́нне, і ни́ні боже́ственную твою́ па́м'ять торжеству́єть сві́тло, ю́же ізба́вити вся́каго обстоя́нія і бід лю́тих моли́, Матфе́є апо́столе.","Богородичен: Нідр не отступи́в Безнача́льнаго Роди́теля, Сло́во Безнача́льноє, я́коже благовіству́єть Матфе́й, пиша́, Бог воплоти́ся із Тебе́, Чи́стая, Всепі́тая, в челові́ч о́браз всеобра́зно весь оді́явся і того́ приє́м сво́йства."]},{"h":"Світилен","ps":["Сказа́ нам Боже́ственная чудодія́нія, сла́вний Христо́ва Єва́нгелія списа́тель, Матфе́й богоприя́тний, єго́же, любо́вію чту́ще, благосочета́нно воспої́м.","Слава: Мита́рства і́го отве́рг разу́мно, Христу́ послі́довал єси́, о Матфе́є богому́дре! Слідо́м же Того́ чу́дно послі́дуя, в прича́стії бил єси́ Того́ Ца́рствія і сла́ви о́бщник, і таї́нник неізрече́нних.","І нині: Всесвяти́я ру́ки Твоя́, Богоро́дице Ді́во, і́миже Зижди́теля носи́ла єси́, поднеси́ в моли́тву о нас к Нему́, я́ко да ізба́вить ни вся́ких іскуше́ній дия́вольських і получи́ти бу́дущих о́них благ сподо́бит, Всепі́тая."]}],"notes":[]},{"u":"Канон преподобному Паїсію Святогорцю","e":"Canon to St Paisios of Mount Athos","secs":[{"h":"Глас 8. Пісня 1","ps":["Ірмос: Колесницегони́теля фарао́ня погрузи́, чудотворя́й іногда́ Моїсе́йський жезл, крестообра́зно порази́в і разділи́в мо́ре, Ізра́їля же біглеця́ пішехо́дця спасе́, піснь Бо́гові воспіва́юща.","Приспів: Преподо́бне о́тче Паї́сіє, моли́ Бо́га о нас.","Даждь мі ра́зум, Христе́ Всеси́льне, да возмогу́ всеусе́рдно воспі́ти житіє́ і мно́гая чудеса́ преподо́бнаго Твоєго́, Паї́сія честна́го і многочу́днаго.","Приспів: Преподо́бне о́тче Паї́сіє, моли́ Бо́га о нас.","Благоче́стно, я́ко а́нгел, на землі́ пожи́в, сла́вне Паї́сіє, плоть і страсте́й воста́нія ду́ху покори́л єси́ і даро́в Бо́жиїх прия́телище яви́лся єси́, всім потре́бная подава́я.","Всея́ тва́рі Созда́теля те́плою мольбо́ю умилостивля́я, ско́рий помо́щник стра́ждущим і в ско́рбі су́щим яви́лся єси́, свя́те Паї́сіє, святи́я Гори́ похвало́.","Богородичен: В пучи́ні страсте́й погружа́єм, утопа́ю, Ма́ти Богоро́дице, ті́мже, я́ко ни́щий і окая́нний, взива́ю: моли́твами Твої́ми бу́рю іскуше́ній мої́х уста́ви, Гори́ святи́я Храни́тельнице."]},{"h":"Пісня 3","ps":["Ірмос: Утвержде́й в нача́лі небеса́ ра́зумом, і зе́млю на вода́х основа́вий, на ка́мені м'я, Христе́, за́повідей Твої́х утверди́, я́ко ність свят па́че Тебе́, Єди́не Человіколю́бче.","Приспів: Преподо́бне о́тче Паї́сіє, моли́ Бо́га о нас.","Христо́вою благода́тію побіди́тель на ду́хи лука́вия показа́лся єси́, о́тче Паї́сіє, зіло́ крі́пко смири́в ю́ношу Гео́ргия, си́лою бісо́вською одержи́ма і обольще́на би́вша губи́тельним уче́нієм.","Приспів: Преподо́бне о́тче Паї́сіє, моли́ Бо́га о нас.","Духоно́сний о́тче Паї́сіє! Госпо́дь вся́чеських, красе́н добро́тою па́че сино́в челові́чеських, Свой О́браз тебі́ ні́когда откри́ і іспо́лни тя благода́ті ве́лія.","Недоумі́єть ум челові́чеський, ка́ко я́ві прия́л єси́ в твоє́й ке́ллії многопі́тую великому́ченицю і ди́вную Євфи́мію, свя́те Паї́сіє блаже́нне, отце́в похвало́.","Богородичен: Ісціле́ній істо́чник і врачева́ніє ізря́дноє Тя, Ма́ти, ві́ми, удруча́ємії всі болі́зньми тіле́сними. Ті́мже с ві́рою про́сим Твоєя́, Богоневі́сто, боже́ственния по́мощі."]},{"h":"Сідален, глас 4","ps":["Непреста́нно в моли́тві пребива́я, ду́шу твою́ храм Ду́ха Свята́го соді́лал єси́, Паї́сіє преподо́бне, і столп сві́тел, ві́рния просвіща́яй, яви́лся єси́, моля́ о всіх Христа́, І́же всіх Соді́теля і Вседержи́теля.","Слава, і нині: Ді́во Неіскусому́жная, христия́н Упова́ніє і А́нгелов Весе́ліє! Ве́ліє дерзнове́ніє пред Престо́лом Си́на Твоєго́ іму́щи, при́сно моли́ся, Влади́чице, о чту́щих Тя."]},{"h":"Пісня 4","ps":["Ірмос: Ти моя́ крі́пость, Го́споди, Ти моя́ і си́ла, Ти мой Бог, Ти моє́ ра́дованіє, не оста́вль ні́дра О́тча, і на́шу нищету́ посіти́в. Тім с проро́ком Авваку́мом зову́ Ті: си́лі Твоє́й сла́ва, Человіколю́бче.","Приспів: Преподо́бне о́тче Паї́сіє, моли́ Бо́га о нас.","Си́лу с Небесе́ приє́м, тя́жкия болі́зні претерпіва́л єси́, богому́дре Паї́сіє, і славосло́вная пі́нія усе́рдно ко Христу́ возглаша́л єси́. Ті́мже і дар ісціле́нія душ і тіле́с прия́л єси́.","Приспів: Преподо́бне о́тче Паї́сіє, моли́ Бо́га о нас.","Уче́нію святи́х оте́ць тве́рдо слі́дуя, му́жественні в Солу́ни Христа́ іспові́дал єси́, всеблаже́нне, і, я́ко а́нгел, с про́чими і́ноки в путь богоразу́мний ше́ствовал єси́, о́браз ві́ри подая́ челові́ком.","Ру́ці твої́ преподо́бнії ко Го́споду воздіва́я, землі́ отступа́л єси́, всехва́льне Паї́сіє, і світ невеще́ственний мно́жицею лице́ твоє́ осіня́ше. Ті́мже і зря́щії в сія́нії лик твой зіло́ удивля́хуся.","Богородичен: Во утро́бу Твою́ Вседержи́тель всели́ся, Богоро́дице, і челові́ков сміше́ніє от тлі обнови́, кля́тву же разріши́в і смерть упраздни́в, темнозра́чнаго проти́вника беззако́ннаго горди́ню смири́ до конця́."]},{"h":"Пісня 5","ps":["Ірмос: Вску́ю м'я отри́нул єси́ от лиця́ Твоєго́, Сві́те Незаходи́мий, і покри́ла м'я єсть чужда́я тьма окая́ннаго, но обрати́ м'я і к сві́ту за́повідей Твої́х путі́ моя́ напра́ви, молю́ся.","Приспів: Преподо́бне о́тче Паї́сіє, моли́ Бо́га о нас.","Ду́хом дія́нія приходя́щих к тебі́ прозрева́я і попече́ніє ми́лостивноє показу́я, вся потре́бная ко спасе́нію їм подава́л єси́, богоно́се о́тче Паї́сіє.","Приспів: Преподо́бне о́тче Паї́сіє, моли́ Бо́га о нас.","Кро́ток і нестяжа́телен, моли́тви ді́латель приле́жний, тишини́ люби́тель і любве́ рачи́тель, Бо́га усе́рдний почита́тель і челові́ком ми́лостивий предста́тель яви́лся єси́, богому́дре Паї́сіє.","Суєсло́вія, зіло́ ві́рния соблазня́ющая, наставле́ньми і уче́ньми правосла́вними, зна́меньми і чудеси́ сокруши́л єси́, всеблаже́нне о́тче Паї́сіє.","Богородичен: Є́ва у́бо прама́ти кля́тву ро́да дре́вле прия́т, Ти же, Богоро́дице, ра́дость і мир Рождество́м Твої́м всім принесла́ єси́. Ті́мже Предста́тельницю челові́ком Твої́ раби́ Тя і́мами, Влади́чице."]},{"h":"Пісня 6","ps":["Ірмос: Очи́сти м'я, Спа́се, мно́га бо беззако́нія моя́, і із глубини́ зол возведи́, молю́ся, к Тебі́ бо возопи́х, і усли́ши м'я, Бо́же, спасе́нія моєго́.","Приспів: Преподо́бне о́тче Паї́сіє, моли́ Бо́га о нас.","Цілому́дренно на землі́ пожи́в, ві́рних душі́ словеси́ твої́ми бога́тно напита́л єси́, преподо́бне о́тче Паї́сіє, і о́браз благоче́стія і чи́стаго житія́ всім яви́л єси́.","Приспів: Преподо́бне о́тче Паї́сіє, моли́ Бо́га о нас.","Я́ко живи́тельний істо́чник, струї́ воздержа́нія ізлива́я, мно́жество ю́них напої́л єси́, Паї́сіє преподо́бне, і сих от блуда́ і нечистоти́ к пото́ку благода́ті приве́л єси́.","Правосла́вія догма́ти мно́жицею в житії́ твоє́м богому́дренно і умодержа́вно я́ві утвержда́л єси́, Паї́сіє преподо́бне, Святи́я Гори́ богоно́сний учи́телю.","Богородичен: Не і́мам да́ра сле́знаго, є́же пла́кати гріхо́в мої́х мно́жество, ні умиле́нія, ні стена́нія спаси́тельнаго, Ма́ти, оба́че мольба́ми Твої́ми ко Христу́, лю́тоє невоздержа́ніє моє́ сокруши́."]},{"h":"Кондак, глас 8","ps":["Святи́я Гори́ подви́жника пресла́внаго і Це́ркве моли́твенника те́плаго восхва́лим в пі́сніх всеусе́рдно, ві́рния к жи́зні ізря́дній наставля́юща і вся́кая проше́нія сих ісполня́юща, і та́ко єму́ возопії́м: ра́дуйся, о́тче Паї́сіє."]},{"h":"Ікос","ps":["Я́ко а́нгел в послі́дняя времена́ на Горі́ Афо́нстій яви́лся єси́, преподо́бне Паї́сіє, на землі́ бо благоче́стне пожи́в, подви́жников дре́вніх равностоя́тель показа́лся єси́. Ті́мже с любо́вію вопіє́м ті такова́я:","Ра́дуйся, Каппадокі́ї боже́ственноє рожде́ніє; ра́дуйся, Афо́на ве́ліє бога́тство.","Ра́дуйся, Ко́ници богодухнове́нная похвало́; ра́дуйся, кинові́ї Суроті́йськия украше́ніє.","Ра́дуйся, ріко́ многостру́йная боже́ственних дарова́ній; ра́дуйся, пото́че неістощи́мий спаси́тельних врачева́ній.","Ра́дуйся, я́ко прославля́єши оби́телі Афо́нськия; ра́дуйся, я́ко обита́єши на горі́ Сина́йстій.","Ра́дуйся, мно́гих благода́тних даро́в приє́мниче; ра́дуйся, о людськи́х неві́жествіїх печа́льниче.","Ра́дуйся, ізба́вителю лю́ті стра́ждущих; ра́дуйся, прови́дче помишле́ній сокрове́нних.","Ра́дуйся, о́тче Паї́сіє."]},{"h":"Пісня 7","ps":["Ірмос: Бо́жия снизхожде́нія огнь устиді́ся во Вавило́ні іногда́. Сего́ ра́ди о́троци в пещі́, ра́дованною ного́ю, я́ко во цві́тниці, лику́юще, поя́ху: благослове́н єси́, Бо́же оте́ць на́ших.","Приспів: Преподо́бне о́тче Паї́сіє, моли́ Бо́га о нас.","Науча́л єси́ ізря́дно наставле́ньми ю́них сосло́віє, є́же супру́жество ізбра́ти іли́ ті́сний путь і́ночеський предпочести́. Ті́мже о́нії с тобо́ю вопія́ху, пою́ще: благослове́н Бог оте́ць на́ших.","Приспів: Преподо́бне о́тче Паї́сіє, моли́ Бо́га о нас.","Неду́ги тіле́сния терпіли́вно под'є́м, в сла́дость тя́жкия болі́зні вміни́л єси́, преподо́бне о́тче Паї́сіє, ті́мже і прия́л єси́ от Бо́га благода́ть незави́стную, чудоді́йственне стра́сті многоразли́чния ісціля́ти.","Весели́ться оби́тель діви́чеськая, я́же в Суроти́, іму́щи, я́ко сокро́вище даро́в Свята́го Ду́ха, мо́щі твоя́, блаже́нне Паї́сіє, і Вседержи́телю восклиця́єть: благослове́н Бог оте́ць на́ших.","Богородичен: Струя́ми чуде́с Твої́х, Пренепоро́чная Влади́чице, земноро́дних чи́ни от пре́лести велія́ра, скорбе́й, многоразли́чних бід і болі́зней тіле́сних, Пречи́стая, свобожда́ються."]},{"h":"Пісня 8","ps":["Ірмос: Седьмери́цею пещ халде́йський мучи́тель Богочесті́вим неі́стовно разжже́, си́лою же лу́чшею спасе́ни, сія́ ви́дів, Творцю́ і Ізба́вителю вопія́ше: о́троци, благослові́те, свяще́нници, воспо́йте, лю́діє, превозносі́те во вся ві́ки.","Приспів: Преподо́бне о́тче Паї́сіє, моли́ Бо́га о нас.","Собра́нія ві́рних на Святі́й Горі́ к тебі́, о́тче, усе́рдно притека́ху, прия́ти твою́, преподо́бне, благода́ть і си́лу: ти бо от Бо́га мно́гая дарова́нія стяжа́л єси́ і во времена́ сія́ му́дрий наста́вник челові́ком показа́лся єси́.","Приспів: Преподо́бне о́тче Паї́сіє, моли́ Бо́га о нас.","Позна́вшії, преподо́бне, житія́ твоєго́ ізря́днійшая на горі́ Афо́нстій і во іні́х страна́х, воспіва́ють Го́спода Человіколю́бця: ти бо словеси́ і ді́ли, я́ко звізда́, возсія́л єси́ і тьму челові́ком стра́ждущим разгна́л єси́.","Всено́щними твої́ми стоя́нії і мно́гими пости́ о́браз ізря́дна подви́жника на Горі́ Святі́й і в Сина́ї яви́л єси́, всесла́вне Паї́сіє. Ти і ни́ні ко Христу́ за лю́ди ру́ці усе́рдно воздіва́єши, дре́внім отце́м равноче́стне.","Богородичен: Мно́гими согріше́ньми неду́гующії, жите́йськими попече́нії і душе́вними страстьми́ обдержи́мії, к Тебі́, Нескве́рній і Нетлі́нній Влади́чице, смире́нно вопіє́м: моли́твами Твої́ми із ро́ва прегріше́ній возведи́ нас."]},{"h":"Пісня 9","ps":["Ірмос: Ужасе́ся о сем Не́бо, і землі́ удиви́шася конці́, я́ко Бог яви́ся челові́ком пло́тськи, і чре́во Твоє́ бисть простра́ннійшеє Небе́с. Тім Тя, Богоро́дицю, А́нгелов і челові́к чинонача́лія велича́ють.","Приспів: Преподо́бне о́тче Паї́сіє, моли́ Бо́га о нас.","От ти́ни прегріше́ній ізба́влься, о́ко твоє́ душе́вноє очи́стил єси́ і тім болі́зні челові́ков лю́тия, душе́вния і тіле́сния я́сно зрел єси́, блаже́нне Паї́сіє, і всіх, приходя́щих к тебі́, на лу́чшая наставля́л єси́.","Приспів: Преподо́бне о́тче Паї́сіє, моли́ Бо́га о нас.","Я́ко дре́вле отці́, та́ко і ти неукло́нним путе́м Христо́вим богоуго́дно ше́ствовал єси́, Паї́сіє чу́дне, і ра́вно с Ти́хоном і про́чими спо́стники Афо́нськими о́браз святи́ні во дні на́ші яви́л єси́.","Я́ко імі́яй дерзнове́ніє во Ви́шніх, сохрани́ моли́твами твої́ми от вреда́ льсти́ваго, і злих житія́ находя́щих, і бу́ри прегріше́ній благоче́стно чту́щих па́м'ять твою́ і ра́достно пою́щих тя, преподо́бне.","Богородичен: Неі́стовствующия прило́ги лука́ваго отжени́ держа́вою Твоє́ю, Богоро́дице Ді́во, я́ко родила́ єси́ чу́дно Христа́, Побіди́теля Сла́внаго, потреби́вшаго горди́ню дре́вняго змі́я і главу́ того́ сокруши́вшаго."]},{"h":"Світилен","ps":["Преподо́бнаго Паї́сія, Гори́ Святи́я сла́ву, Суроті́йськия оби́телі храни́теля, путевождя́ моля́щихся і ю́них наста́вника в пі́ніїх почти́м, славосло́в'яще боже́ственне житіє́ того́ і дія́нія.","Слава, і нині: Ді́во Пресла́вная, христия́н утвержде́ніє, благогові́йноє предста́тельство немощни́м челові́ком, боля́щим ісціле́ніє і стра́ждущим крі́посте, вселе́нния покро́ве! Благоче́стно Тя воспіва́єм, раби́ Твої́."]}],"notes":[]},{"u":"Канон святителю Феофану, Затворнику Вишенському","e":"Canon to St Theophan the Recluse of Vyshensk","secs":[{"h":"Глас 8. Пісня 1","ps":["Ірмос: Во́ду проше́д, я́ко су́шу, і єги́петськаго зла ізбіжа́в, ізра́їльтянин вопія́ше: Ізба́вителю і Бо́гу на́шему пої́м.","Приспів: Святи́телю о́тче Феофа́не, моли́ Бо́га о нас.","Ра́достно принося́ще хвале́ніє, смире́нно к тебі́ припа́дающе, про́сим: прийми́ недосто́йноє моле́ніє на́ше, святи́телю о́тче Феофа́не.","Приспів: Святи́телю о́тче Феофа́не, моли́ Бо́га о нас.","А́нгеле земни́й і челові́че Бо́жий, в затво́рі Ви́шинськия оби́телі пребива́я, непреста́нно моля́ся ко Го́споду, із'ясня́л єси́ лю́дем путь ко спасе́нію.","Днесь соше́дшеся, ві́рнії, восхва́лим пі́сньми і пі́ньми духо́вними святи́теля Феофа́на, на́шего при́снаго к Бо́гу моли́твенника.","Богородичен: утверди́ нас, Ма́ти Бо́жия, во ві́рі Сину́ і Бо́гу Твоєму́, ди́вно прославля́ющему уго́дники Своя́ і дру́ги їх нариця́ющему."]},{"h":"Пісня 3","ps":["Ірмос: Небе́снаго кру́га верхотво́рче, Го́споди, і Це́ркве Зижди́телю, Ти мене́ утверди́ в любві́ Твоє́й, жела́ній кра́ю, ві́рних утвержде́ніє, Єди́не Человіколю́бче.","Приспів: Святи́телю о́тче Феофа́не, моли́ Бо́га о нас.","І́м'я твоє́, святи́телю Феофа́не, я́ко ми́ро, зе́млю на́шу облагоуха́, услажда́юще сердца́ ві́рних, призива́юще всіх к духо́вній ра́дости і спасе́нію.","Приспів: Святи́телю о́тче Феофа́не, моли́ Бо́га о нас.","Свя́тче Бо́жий, уго́дниче Христо́во Феофа́не, при́зри на не́мощі на́ша і ісціли́ ду́ші на́ша, страстьми́ при́сно обурева́ємия.","Я́ко пчела́ трудолюби́вая, с лу́га духо́внаго мед писа́ній оте́чеських нам предлага́єши, святи́телю, во спасе́ніє с моли́твою к тебі́ притека́ющих.","Богородичен: Феофа́не святи́телю, прийди́, ста́ни с на́ми, да просла́вим вку́пі Пресвяту́ю Ді́ву, Христа́ Бо́га ро́ждшую."]},{"h":"Сідален, глас 8","ps":["Житіє́ твоє́ сла́вно бисть і успе́ніє со святи́ми, свя́тче Бо́жий Феофа́не, ни́ні же у престо́ла всеви́шняго предстоя́й, моли́ся о нас, всеблаже́нне, да спасе́ть Госпо́дь ду́ші на́ша."]},{"h":"Пісня 4","ps":["Ірмос: Ти моя́ крі́пость, Го́споди, Ти моя́ і си́ла, Ти мой Бог, Ти моє́ ра́дованіє, не оста́вль ні́дра О́тча і на́шу нищету́ посіти́в. Тім с проро́ком авваку́мом зову́ ті: си́лі Твоє́й сла́ва, Человіколю́бче.","Приспів: Святи́телю о́тче Феофа́не, моли́ Бо́га о нас.","Феофа́не святи́телю, ра́зум твой му́дре Христу́ вві́рил єси́, ца́рствія ві́чнаго сподо́бися, моли́ ни́ні вся прему́дростію сотво́ршаго, да спасе́ть ду́ші на́ша. Єго́же возлюби́л єси́, Єго́же єди́наго возжелі́л єси́, Єго́же ра́ди в затво́рі подвиза́лся єси́, моли́ ни́ні, да спасе́ть ду́ші на́ша.","Приспів: Святи́телю о́тче Феофа́не, моли́ Бо́га о нас.","О́браз бил єси́ Богода́нній па́стві твоє́й, сло́вом, житіє́м, любо́вію, ду́хом, ві́рою і чистото́ю. Сего́ ра́ди тя я́ко і́стиннаго па́стиря почита́єм, Феофа́не о́тче наш.","Богородичен: Феофа́не Богому́дре, моли́ся о нас Пресвяті́й Влади́чице Богоро́дице, да Свої́м всеси́льним предста́тельством умоли́ть Христа́ спасти́ ду́ші на́ша."]},{"h":"Пісня 5","ps":["Ірмос: Вску́ю м'я отри́нул єси́ от Лиця́ Твоєго́, Сві́те Незаходи́мий, і покри́ла м'я єсть чужда́я тьма, окая́ннаго: но обрати́ м'я і к сві́ту за́повідей Твої́х путі́ моя́ напра́ви, молю́ся.","Приспів: Святи́телю о́тче Феофа́не, моли́ Бо́га о нас.","А́нгели на небесі́ ра́дуються, челові́ци на землі́ духо́вно торжеству́ють, па́м'ять соверша́юще святи́теля Феофа́на, ди́внаго о всіх нас моли́твенника.","Приспів: Святи́телю о́тче Феофа́не, моли́ Бо́га о нас.","Научи́ нас, блаже́нне Феофа́не, ві́діти Христа́, Сві́та і́стиннаго, просвіща́ющаго вся́каго челові́ка, гряду́щаго в мир.","Єго́же во́їнства небе́сная сла́в'ять, в житії́ своє́м непреста́нно прославля́л єси́, научи́ і нас, свя́тче Бо́жий, доброді́тельми Го́спода сла́вити.","Богородичен: Ви́шшую Небе́с і Чи́стшую сві́тлостей со́лнечних, ізба́вльшую нас от кля́тви, Влади́чицю ми́ра пі́сньми почті́м."]},{"h":"Пісня 6","ps":["Ірмос: Очи́сти м'я, Спа́се, мно́га бо беззако́нія моя́, і із глубини́ зол возведи́, молю́ся, к Тебі́ бо возопи́х, і усли́ши м'я, Бо́же спасе́нія моєго́.","Приспів: Святи́телю о́тче Феофа́не, моли́ Бо́га о нас.","Шел єси́ ті́сним путе́м ко спасе́нію, кро́ткий кро́ткому взива́я непреста́нно: мні приліпля́тися Бо́гові бла́го єсть.","Приспів: Святи́телю о́тче Феофа́не, моли́ Бо́га о нас.","І́стини Христо́ви вожделі́в, ско́рби і оби́ди ра́достно терпі́л єси́, помишля́я непреста́нно, я́коже віне́ць без побі́ди, та́кожде побі́да без по́двига не бива́єть.","Не забу́ди нас, чад твої́х, о́тче Феофа́не, в дому́ Отця́ Небе́снаго пребива́я, і сподо́би моли́твами твої́ми в черто́г Го́спода Сла́ви вни́ти.","Сла́ву і вся сокро́вища ми́ра презрі́л єси́, неукло́нно ше́ствуя ко го́рнему ми́ру, і ни́ні ра́достію а́нгельською ра́дуєшися, о́тче наш, святи́телю Феофа́не.","Богородичен: Кто Тебі́ не ублажи́ть, Пресвята́я Ді́во? Кто ли не воспоє́ть Твоєго́ Пречи́стаго Рождества́? Моли́ Чи́стая, Всеблаже́нная, Си́на Твоєго́ і Бо́га поми́ловатися душа́м на́шим."]},{"h":"Кондак, глас 4","ps":["Богоявле́нію тезоимени́тий, святи́телю Феофа́не, уче́ньми твої́ми мно́гі лю́ди просвіти́л єси́, со а́нгели ни́ні предстоя́ Престо́лу Святи́я Тро́йці, моли́ непреста́нно о всіх нас."]},{"h":"Ікос","ps":["Я́коже явле́ніє Боже́ственних дарова́ній воі́стину показа́лся єси́ землі́ Українській, святи́телю Феофа́не, па́стирю до́брий ста́да Христо́ва, вразумля́я житіє́м, сло́вом і писа́нієм наставля́я. І ни́ні Престо́лу Пресвяти́я Тро́йці предстоя́, со дерзнове́нієм воздіва́я преподо́бнії ру́ці твої́, моли́ непреста́нно о всіх нас."]},{"h":"Пісня 7","ps":["Ірмос: Бо́жия снизхожде́нія огнь устиді́ся во Вавило́ні іногда́. Сего́ ра́ди о́троци в пещі́ ра́дованною ного́ю, я́ко во цві́тниці, лику́юще, поя́ху: благослове́н єси́, Бо́же оте́ць на́ших.","Приспів: Святи́телю о́тче Феофа́не, моли́ Бо́га о нас.","Кре́стний путь Подвигополо́жника Христа́ ви́ну пред собо́ю імі́я, путе́м ті́сним, веду́щим в жизнь ві́чную, ше́ствовал єси́, блаже́нне, взива́я непреста́нно: благослове́н Бог оте́ць на́ших.","Приспів: Святи́телю о́тче Феофа́не, моли́ Бо́га о нас.","Ілії́ Фесви́тянину ре́вностію подража́л єси́, святи́телю Феофа́не, любо́вію боже́ственною се́рдце твоє́ распала́я, в терпі́нії ду́шу твою́ стяжа́л єси́, вопія́: благослове́н Бог оте́ць на́ших.","І́стини Боже́ственния ре́вностний пропові́дниче, му́дростію слове́с твої́х і уче́ній, о́тче Феофа́не, наставля́ємі, ку́пно с тобо́ю поє́м ни́ні: благослове́н Бог оте́ць на́ших.","Богородичен: Пода́ждь утіше́ніє рабо́м Твої́м, Богороди́тельнице Марі́є, да вопіє́м с Тобо́ю к Си́ну Твоєму́ і Спа́су на́шему: благослове́н Бог оте́ць на́ших."]},{"h":"Пісня 8","ps":["Ірмос: Седьмери́цею пещ халде́йський мучи́тель Богочесті́вим неі́стовно разжже́, си́лою же лу́чшею спасе́ни сія́ ви́дів, Творцю́ і Ізба́вителю вопія́ше: о́троци, благослові́те, свяще́нници, воспо́йте, лю́діє, превозносі́те во вся ві́ки.","Приспів: Святи́телю о́тче Феофа́не, моли́ Бо́га о нас.","О́троци, благослові́те, свяще́нници, воспо́йте, лю́діє, превозносі́те Христа́ во ві́ки, соверша́юще ве́ліє торжество́ прославле́нія уго́дника Бо́жия, святи́теля Феофа́на.","Приспів: Святи́телю о́тче Феофа́не, моли́ Бо́га о нас.","Досто́йно воспіва́ти Бо́жию Сла́ву науча́л єси́ всіх, пропові́дниче благоче́стія Феофа́не, і нас, ни́ні с ві́рою прише́дших к тебі́, сему́ научи́, да сла́виться і́м'я Бо́жиє во ві́ки.","Ві́ри тве́рдий побо́рниче, благоче́стія му́дрий пропові́дниче, правосла́вія ізря́дний Богосло́ве, Феофа́не, Ви́шинський затво́рниче, сподо́би нас, недосто́йних, в ра́дості духо́вній воспіва́ти Го́спода, превозноси́маго во вся ві́ки.","Богородичен: Ісціле́ній струї́ всегда́ ві́рним подає́ши, Ма́ти Бо́жия, ісціли́ ду́ші на́ша, моли́тв ра́ди уго́дника Бо́жия Феофа́на, да сла́вим Рождество́ Твоє́, Пречи́стая, і превозно́сим во вся ві́ки."]},{"h":"Пісня 9","ps":["Ірмос: ужасе́ся о сем Не́бо, і землі́ удиви́шася конці́, я́ко Бог яви́ся челові́ком пло́тськи, і чре́во Твоє́ бисть простра́ннійшеє Небе́с: тім Тя, Богоро́дицю, а́нгелов і челові́к чинонача́лія велича́ють.","Приспів: Святи́телю о́тче Феофа́не, моли́ Бо́га о нас.","Жи́зні ві́чния сподо́бился єси́, святи́телю, бу́ди хода́тай і моли́твенник те́плий о нас к Бо́гу, ві́рою па́м'ять твою́ свяще́нную пра́зднующих.","Приспів: Святи́телю о́тче Феофа́не, моли́ Бо́га о нас.","Но́вий воі́стину чудотво́рець яви́лся єси́, Феофа́не Богому́дре, я́ко ціли́тель преми́лостивий і врачь безме́здний душ і тіле́с всіх с ві́рою к тебі́ притека́ющих, ми́луя і утіша́я і щедро́ти твоя́ преізоби́льно ізлива́я.","І́стинно яви́лся єси́ моли́твенник те́плий о нас к Бо́гу, іспроси́, о́тче, у Творця́ вся́чеських, прегріше́ній оставле́ніє всім с ві́рою і любо́вію тя велича́ющим.","Челові́че Бо́жий, ві́рний дру́же Христо́в, прийми́ ми́лостивно моле́нія на́ша і принеси́ я ко Престо́лу Сла́ви Го́спода, Креще́нієм Свої́м Іорда́нськія струї́ освяти́вшаго.","Богородичен: Єго́же во́їнства Небе́сная сла́в'ять, єго́же во чре́ві носи́ла єси́, Богома́ти Пречи́стая, моли́ уще́дрити і спасти́ ду́ші на́ша."]},{"h":"Світилен","ps":["Світи́льника, сви́ше просвіща́ємаго, сві́том Боже́ственним осія́єма, святи́теля Феофа́на, ра́дующеся, пі́сньми почті́м."]}],"notes":[]},{"u":"Канон преподобному Феодосію Великому","e":"Canon to St Theodosius the Great","secs":[{"h":"Глас 2. Пісня 1","ps":["Ірмос: Во глубині́ постла́ іногда́ фараони́тськоє всево́їнство преоруже́нная си́ла, вопло́щшеєся же Сло́во всезло́бний гріх потреби́ло єсть, препросла́вленний Госпо́дь, сла́вно бо просла́вися.","Приспів: Преподо́бне о́тче Феодо́сіє, моли́ Бо́га о нас.","Я́ко мудр чинонача́льник наш, о́тче Феодо́сіє, боголі́пно піснь предначни́ прише́дшему во всеми́рноє спасе́ніє Христу́ Бо́гу і всесвяту́ю па́м'ять твою́ с Собо́ю просла́вльшему.","Приспів: Преподо́бне о́тче Феодо́сіє, моли́ Бо́га о нас.","Із пусти́ні Предте́ча Христо́в, от Ааро́нови Єлисаве́ти прозяби́й, при́йде; в купі́лі же Феодо́сій роди́вся Ду́хом, пустиннограждани́н бисть, Ісу́су послі́дствуя.","Кре́щшуся в струя́х Христу́, ізра́їльтеськаго собо́рища потреби́ся шата́ніє, в Це́ркві же равноа́нгельно жи́тельство насади́ся, є́же неукло́нно соверши́л єси́, всеблаже́нне Феодо́сіє.","О́бщник стра́сті бив, о́тче, поще́нієм нас ра́ди на Кресті́ Пригвожде́нному, досто́йно сообра́зен бил єси́ Того́ воскресе́нія і снаслі́дник бил єси́ сла́ви, Феодо́сіє.","Богородичен: Отрокови́ць боже́ственний лик боже́ственнійше в Тя до́брую імену́ють, Богоро́дице Влади́чице, добро́тами укра́шенную Божества́: добротвори́тельноє бо Сло́во па́че сло́ва родила́ єси́."]},{"h":"Пісня 3","ps":["Ірмос: Процвіла́ єсть пусти́ня я́ко крин Го́споди, язи́чеськая неплодя́щая це́рков, прише́ствієм Твої́м, в не́йже утверди́ся моє́ се́рдце.","Приспів: Преподо́бне о́тче Феодо́сіє, моли́ Бо́га о нас.","Вода́ми покрива́я преви́спренняя, Госпо́дь тіле́сно оді́яшеся в струи́ Іорда́нськия, в Не́мже утверди́ся се́рдце моє́.","Приспів: Преподо́бне о́тче Феодо́сіє, моли́ Бо́га о нас.","Світ во Іорда́ні Боже́ственний возсія́вий, прозябе́ніє су́щим на землі́ богода́нноє, благослове́нія і проізволе́нія блага́го проявля́єть тя, Феодо́сіє.","Оста́вил єси́ мир і я́же в ми́рі, преподо́бне, би́вшему обнаже́нію Влади́чню подо́б'яся на Іорда́ні, Феодо́сіє.","Крест Спа́сов на ра́мена взем, поте́кл єси́ на гроб Єго́, я́коже єле́нь на істо́чники водни́я спаси́тельния, всеблаже́нне Феодо́сіє.","Богородичен: Чи́ни ужасо́шася а́нгельстії, Всечи́стая, і челові́чеськая устраши́шася сердца́ о рождестві́ Твоє́м. Тім Тя, Богоро́дице, ві́рою почита́єм."]},{"h":"Сідален, глас 8","ps":["Воздержа́нієм, і болі́зньми, і моли́твами ду́шу твою́ украси́в боголі́пно, бил єси́ соприча́стник му́чеником, блаже́нне, і чуде́с воі́стину да́ри прия́л єси́, є́же ісціля́ти неду́ги ві́рою чту́щих тя. Ті́мже і де́монов отгоня́я мно́жества, подає́ши ісціле́нія челові́ком благода́тію, богоно́се Феодо́сіє, моли́ Христа́ Бо́га гріхо́в оставле́ніє пода́ти пра́зднующим ві́рою па́м'ять твою́.","Слава, і нині: Іорда́н струя́ми слу́жить, і Іоа́нн простира́єть ру́ку тлі́нную, я́вльшуся Тебі́, Неви́диме, пло́тію ко креще́нію. Но ов у́бо возвраща́шеся всп'ять стра́хом, ов же а́біє держа́ше с тре́петом Тя, Нетлі́ннаго. Воі́стину А́гнець Бо́жий, Істо́чник присноживо́тний, істо́чники же, і моря́, і челові́ки освяти́в: Тро́йця бо просія́, сви́ше Си́на Тя імену́єть Роди́тель, і Святи́й Дух снизхо́дить."]},{"h":"Пісня 4","ps":["Ірмос: Прише́л єси́ от Ді́ви не хода́тай, ні а́нгел, но Сам Го́споди вопло́щся, і спасл єси́ всего́ м'я челові́ка; тім зову́ ті: сла́ва си́лі Твоє́й, Го́споди.","Приспів: Преподо́бне о́тче Феодо́сіє, моли́ Бо́га о нас.","Во вода́х глави́ зміє́в сокруши́л єси́, і Ду́хом, Сло́ве Бо́жий, обнови́л єси́ всего́ м'я, челові́ка. Тім вопію́ Ті: сла́ва си́лі Твоє́й, Го́споди.","Приспів: Преподо́бне о́тче Феодо́сіє, моли́ Бо́га о нас.","Прекло́ньшему главу́ Предте́чі, уподо́бився Христу́ покоре́нієм і ізря́дним смире́нієм, о́тче Феодо́сіє, на доброді́телі возше́л єси́ столп непоколеби́мий.","Ді́ві і Ма́тері послужи́в Христа́ Бо́га, непобори́му благода́ть прия́л єси́ Ду́ха, о́тче Феодо́сіє, і враги́ неви́димия низложи́л єси́.","Волхво́в тя сла́вний верте́п приє́мий, дароно́сця показа́ нас ра́ди кре́щшемуся Христу́, ві́ру, Феодо́сіє, і с наде́ждею любо́в принося́ща.","Страстьми́ Влади́ки Христа́ укріпля́єм, со́вістію любе́зною претерпі́л єси́ муче́ніє, о́тче Феодо́сіє, с те́мним боря́ся мироде́ржцем.","Богородичен: Зачала́ єси́ во утро́бі Твоє́й безсі́менно Го́спода і Сего́ родила́ єси́, воплоще́нна, спаса́ющаго мир моли́твами Твої́ми. Ті́мже Ті зове́м: ра́дуйся, Присноді́во Влади́чице."]},{"h":"Пісня 5","ps":["Ірмос: Хода́тай Бо́гу і челові́ком бил єси́, Христе́ Бо́же: Тобо́ю бо Влади́ко, к світонача́льнику Отцю́ Твоєму́, от но́щі неві́дінія, приведе́ніє і́мами.","Приспів: Преподо́бне о́тче Феодо́сіє, моли́ Бо́га о нас.","Возже́г ум, І́же нас во вода́х Обнови́вшаго, му́дре утверди́л єси́, низве́рженний поще́нієм, пові́шеньми ті́ло, всеблаже́нне Феодо́сіє.","Приспів: Преподо́бне о́тче Феодо́сіє, моли́ Бо́га о нас.","Житіє́ при́сно сме́рті положи́в поуче́ніє, отити́ же тща́вся к Я́вльшемуся нас ра́ди пло́тію, себі́ сотвори́л єси́ гроб, Феодо́сіє.","Смерть Христо́ву во́льную твой учени́к сла́вний Васи́лій, о́тче Феодо́сіє, подража́я, но́вий обновля́єть гроб, ра́дуяся.","Богородичен: Се во утро́бі, Богоро́дице Всечи́стая, Христа́ Бо́га па́че сло́ва імі́ла єси́, я́коже Іса́їя прорече́, па́че єстества́ же Сего́, Богороди́тельнице, родила́ єси́."]},{"h":"Пісня 6","ps":["Ірмос: В бе́здні гріхо́вній валя́яся, неізслі́дную милосе́рдія Твоєго́ призива́ю бе́здну: от тлі, Бо́же м'я возведи́.","Приспів: Преподо́бне о́тче Феодо́сіє, моли́ Бо́га о нас.","Нетлі́ніє нам дарова́л єси́, Христе́, во воскресе́нії Твоє́м, ті́мже Васи́лій, сла́вний уго́дник Твой, і у́мер, я́коже жив, явля́ється.","Приспів: Преподо́бне о́тче Феодо́сіє, моли́ Бо́га о нас.","Очища́яй мир креща́ється, мене́ ра́ди Бог челові́к по мні бив, Єго́же во двух єстества́х, Феодо́сіє блаже́нне, пропові́дал єси́.","Сла́дость весе́лія Христу́ Бо́гу, мироно́сиць сле́зи обра́щшему в ра́дость, Феодо́сіє, то́ки слез твої́х іска́паша.","Богородичен: Милосе́рдія Твоєго́ сподо́би м'я, Я́же Ми́лостивійшаго Сло́ва Ро́ждшая, Своє́ю кро́вію от тлі челові́ки Ізба́вльшаго."]},{"h":"Кондак, глас 8","ps":["Насажде́н во дво́ріх Го́спода твоєго́, преподо́бними твої́ми доброді́тельми красно́ процві́л єси́ і умно́жил єси́ ча́да твоя́ в пусти́ні, слез твої́х ту́чами напая́ємая, стадонача́льниче Бо́жий Боже́ственних дворо́в. Ті́мже зове́м: ра́дуйся, о́тче Феодо́сіє."]},{"h":"Ікос","ps":["Челові́к у́бо єстество́м бил єси́, о́тче, но яви́лся єси́ сограждани́н а́нгелов: я́ко бо безпло́тен, на землі́ пожи́в, му́дре, плотсько́є все промишле́ніє отве́ргл єси́. Ті́мже і от нас сли́шиши: ра́дуйся, отця́ благочести́ваго о́трасле; ра́дуйся, ма́тере благогові́йния вітв; ра́дуйся, пусти́нний граждани́не всекра́сний; ра́дуйся, вселе́нния світи́льниче многосві́тлий; ра́дуйся, я́ко от ю́ности послі́довал єси́ Христу́; ра́дуйся, я́ко ув'яди́л єси́ плотські́я сла́сти; ра́дуйся, мона́шествующих хода́тай спасе́нія; ра́дуйся, унива́ющих о́браз утіше́нія; ра́дуйся, мно́гія от ле́сти ізба́вивий; ра́дуйся, то́ки чуде́с да́руя; ра́дуйся, о ни́щих попече́ніє сотвори́вий; ра́дуйся, наш предста́телю і ізба́вителю. Ра́дуйся, о́тче Феодо́сіє."]},{"h":"Пісня 7","ps":["Ірмос: Богопроти́вноє велі́ніє беззако́ннующаго мучи́теля висо́к пла́мень вознесло́ єсть: Христо́с же простре́ Богочести́вим отроко́м ро́су духо́вную, Сий Благослове́н і Препросла́влен.","Приспів: Преподо́бне о́тче Феодо́сіє, моли́ Бо́га о нас.","Струю́, попаля́ющую гріх, і пла́мень, ороша́ющ челові́чеський род, Го́споди, во Твоє́м креще́нії совокупи́в, Сло́ве Бо́жий, превозноси́мий Бо́же, благослове́н єси́ і препросла́влен.","Приспів: Преподо́бне о́тче Феодо́сіє, моли́ Бо́га о нас.","Пещ Сотво́ршему Іорда́н, тебі́ сама́го, я́ко кади́ло, всесоже́гл єси́, преподо́бне, і пла́мень небе́сний, нело́жен о́браз Боже́ственнаго манове́нія приє́м, храм водрузи́л єси́, душ спаси́тельний.","Твої́ми воєво́дстви Мойсе́єва повину́ються, благода́ті я́вльшейся, преподо́бне: враги́ бо неви́димия низложи́в, град небе́сний наслі́дують твої́ лю́діє, всехва́льне.","Струя́ми Погре́бшему гріх тебі́ сама́го обита́лище сотвори́л єси́, Феодо́сіє, богоуго́дноє, храм созда́в, приноси́ти непреста́нную піснь законоположи́л єси́ многоязи́чними гла́си.","Отроко́в подража́я дерзнове́ніє, мучи́теля огнедохнове́нноє преще́ніє укори́л єси́, му́дре предста́тельствуя по Це́ркві Христо́ві, о́тче Феодо́сіє, єя́же ра́ди во́льно яви́ся пло́тію распина́ємий.","Богородичен: Всечи́стоє зача́тіє, нетлі́нноє рождество́ Ти Єди́на показа́ла єси́, Ді́ва преби́вши: Бо́га бо зачала́ єси́, над всі́ми Су́щаго, Чи́стая, Челові́ка би́вша ві́рних на спасе́ніє і ізбавле́ніє."]},{"h":"Пісня 8","ps":["Ірмос: Пещ іногда́ о́гненная во Вавило́ні ді́йства разділя́ше, Бо́жиїм велі́нієм халде́ї опаля́ющая, ві́рния же ороша́ющая, пою́щия: благослові́те вся діла́ Госпо́дня Го́спода.","Приспів: Преподо́бне о́тче Феодо́сіє, моли́ Бо́га о нас.","Пещ іногда́ во Вавило́ні струи́ Іорда́нськия ізобрази́, Боже́ственним Креще́нієм проти́вния опаля́ющи, ві́рния же ороша́ющи, пою́щия: благослові́те, вся діла́ Госпо́дня, Го́спода.","Приспів: Преподо́бне о́тче Феодо́сіє, моли́ Бо́га о нас.","Тіле́сних страсте́й предизше́д пре́жде отше́ствія, Феодо́сіє, от нідр земни́х вод ізима́я, ю́ноши явля́єшися, зову́щу: благослові́те, вся діла́ Госпо́дня, Го́спода.","Бисть твої́х рук благослове́ніє, во струя́х креща́ющагося Христа́ Боже́ственнійшеє повелі́ніє, невла́жній землі́ ро́днійшая вода́ і грі́ющеє со́лнце: зерно́ бо во многопло́ден клас пшени́ци безсі́менно пита́шеся.","Во мрак ми́сленний Сві́та Боже́ственнійшаго ти вшед, Феодо́сіє, і скрижа́ли пе́рстом Бо́жиїм написа́в се́рдцю твоєму́, благоче́стія уче́нія прине́сл єси́ ученико́м твої́м, кни́гу жи́зні, всеблаже́нне.","Ві́ру тве́рду кровоточи́вия, о́тче, подража́вши жена́, ру́бищу косну́вшися, я́коже тьма, су́щим в тебі́ просвіще́нієм неду́г отгна́ся, бил бо єси́ ізбра́нія сосу́д я́вльшемуся Христу́.","Тро́їчен: Тя, із Бо́га Бо́га ви́дівше, тіле́сні я́вльшагося Христа́ неізглаго́ланно, позна́хом у́бо Неви́димаго Отця́ Твоєго́ і Ду́ха Твоєго́ Свята́го, зову́ще: благослові́те, вся діла́ Госпо́дня, Го́спода.","Богородичен: Ти Отцю́ Неразлу́чнаго, во утро́бі богому́жно Жи́тельствовавшаго, безсі́менно зачала́ єси́ і несказа́нно родила́ єси́. Тім Тя спасе́ніє всіх нас ві́ми."]},{"h":"Пісня 9","ps":["Ірмос: Безнача́льна Роди́теля Син, Бог і Госпо́дь, вопло́щся от Ді́ви, нам яви́ся, омраче́нная просвіти́ти, собра́ти расточе́нная, тім Всепі́тую Богоро́дицю, велича́єм.","Приспів: Преподо́бне о́тче Феодо́сіє, моли́ Бо́га о нас.","Собо́ри пропові́дал єси́, богому́дре Феодо́сіє, честни́х равночи́сленни Єва́нгелій Христо́вих, проізволе́нієм кров му́ченичеську приє́м ре́вностію, і му́ченик без кро́ве благоче́стія яви́лся єси́.","Приспів: Преподо́бне о́тче Феодо́сіє, моли́ Бо́га о нас.","Суд непра́веднаго пра́ведно осуди́, за твоє́ ізгна́ніє прогна́вш і ху́льними устна́ми нечести́вую ду́шу із'є́мш, жи́зні же лиши́вш жи́зні врага́, преподо́бне.","Твоя́ помина́юще уче́нія, Феодо́сіє, во двою́ существу́ Христа́ пропові́даєм, дві во́лі ві́дуще, єсте́ственни, і ді́йственни, і самовла́стни, в Бо́зі, кре́щшемся пло́тію.","Тезоіме́нно дая́ніє бла́го от Отця́ сві́тов, душ і тіле́с врачь бил єси́, снідь оби́льна і питіє́, і́же во гла́ді та́ющих і жа́жди, і наги́х одія́ніє, і па́дающих ісправле́ніє.","Не преста́й ста́до твоє́ назира́я, о́тче преподо́бне, і, твоє́ помина́я обіща́ніє, є́же я́ко наде́жді ко́тви непрело́мни прив'яза́хом ка́меню, ко Христу́ хода́тая тя іму́ще, Феодо́сіє.","Єди́ницю Тричи́сленную, Тро́йцю Єдиносу́щную правосла́вно пою́ще, ві́рнії, просла́вим, несіко́мо Пребоже́ственноє Єстество́ Трисія́нноє, невече́рнюю Зарю́, єди́ну нетлі́нную, Світ нам возсія́вшую.","Богородичен: Я́ко у́тро обріла́ся єси́ ра́ннєє в жите́йстей но́щі, ді́вства заря́ми облиста́ющи, Восто́к Со́лнця ми́сленнаго пра́вди нам я́вльшая, Богома́ти Всечи́стая."]},{"h":"Світилен","ps":["Очи́стихомся сві́тло, Христе́ мой, очище́нієм Твої́м і ни́ні пра́здничною ра́достію, Феодо́сія честна́го па́м'ятію, обогати́хомся, ті́мже мона́шествующих веселя́ться чи́ни.","Слава, і нині: Яви́ся Спас Благода́ть і І́стина во струя́х Іорда́нських, і су́щия во тьмі і сі́ні спя́щия просвіти́л єсть: і́бо при́йде і яви́ся Світ Непристу́пний."]}],"notes":[]},{"u":"Канон рівноапостольній Ніні, просвітительці Грузії","e":"Canon to St Nino, Equal-to-the-Apostles, Enlightener of Georgia","secs":[{"h":"Глас 1. Пісня 1","ps":["Ірмос: Спасе́ лю́ди чудоді́йствуяй Влади́ка, мо́крую мо́ря во́лну оземлени́в дре́вле; во́лею же ро́ждься от Ді́ви, стезю́ прохо́дну небесе́ полага́єть нам. Єго́же, по Существу́ ра́вна же Отцю́ і челові́ком, сла́вим.","Приспів: Свята́я равноапо́стольная Ні́но, моли́ Бо́га о нас.","Отве́рзи устні́ мої́, Христе́ Бо́же, да восхвалю́ ді́ву равноапо́стольную і пропові́дницю Ні́ну воспою́, і просвіти́ ум мой, да досто́йную цві́ти слове́с укра́шу по достоя́нію.","Приспів: Свята́я равноапо́стольная Ні́но, моли́ Бо́га о нас.","Рі́чі чужди́х ті племе́н уразумі́ла єси́, прехва́льная Ні́но, і, от Ду́ха Свя́та умудре́на би́вши, во виді́нії Сама́го Го́спода узрі́ла єси́. Ті́мже в землі́ непло́дній, богому́драя ді́во, лю́ди І́верськия ко Христу́ привела́ єси́.","Жестосе́рдия ва́рвари, куми́ром служа́щия, я́ко голуби́ця, от за́пада воспари́вшая, любо́вію твоє́ю обрати́ла єси́ ко Творцю́ і, благода́тію обновле́нния, неві́сто Христо́ва непоро́чная, Жениху́ твоєму́ обручи́ла єси́.","Богородичен: Сосу́д благости́ні Твоєя́, Пречи́стая Ді́во Богоро́дице, бисть свята́я ді́ва, і страну́, жре́бієм Тебі́ свиді́тельствовану, просвіти́. Сего́ ра́ди мо́лим Тя: сію́ прийми́ с Тобо́ю в моли́тву о вопію́щих Тебі́: поми́луй жре́бій Твой."]},{"h":"Пісня 3","ps":["Ірмос: При́зри на пі́нія рабо́в, Благоді́телю, врага́ смиря́я вознесе́нную горди́ню, нося́й же, Всеви́дче, гріха́ преви́ше, непоколе́блемо утвержде́ния, Бла́же, півці́ основа́нієм ві́ри.","Приспів: Свята́я равноапо́стольная Ні́но, моли́ Бо́га о нас.","Милосе́рдія ра́ди Своєго́ ми́лостивно пом'яну́в нас, усе́рдну благові́стницю соді́ла тя Бог, жену́ су́щу, му́жеським сми́слом укра́шену, і іспо́лнену Ду́ха Свя́та яви́ нам, і твоє́ю про́повідію о Христі́, чрез ві́ру в Него́, нас усинови́л єсть.","Приспів: Свята́я равноапо́стольная Ні́но, моли́ Бо́га о нас.","Покрива́ло от серде́ць на́ших безчу́вственних отпаде́, отягче́нний слух наш от гла́са про́повіді твоєя́ откри́ся, омраче́ніє ума́ на́шего разсі́яся сві́том уче́нія Христо́ва, тобо́ю возвіще́ннаго, о свята́я равноапо́стольная Ні́но, до́блественная учени́це Христо́ва.","Покланя́вшіїся іногда́ куми́ром і пребива́вшії во тьмі нече́стія от ле́сти і́дольськия твої́м прише́ствієм, блаже́нная Ні́но, свободи́шася, Арма́з же вострепета́, єгда́ гром возгремі́, і неі́стовства За́дена преста́ша.","Богородичен: Тобо́ю, Богоро́дице Ді́во, от ро́ва нече́стія под'я́ти би́хом, єгда́ Ті уго́дно бисть просвіще́ніє на́ше жено́ю сотвори́ти, повнегда́ же ізи́ти нам от купі́лі святи́я, позна́хом Си́на Твоєго́ і Бо́га на́шего блаже́нною Ни́ною."]},{"h":"Сідален, глас 2","ps":["Я́коже со́лнце незаходи́моє, Со́лнця пра́вди — Христа́ Бо́га пропові́дниця, світоза́рная звізда́, сві́тлий вселе́нния світи́льник, неоціне́нноє сокро́вище І́верськия страни́, днесь Ни́на в землі́ на́шей сія́єть і благоуха́єть, наста́вниця на́ша, равноапо́стольная раба́ Христо́ва."]},{"h":"Пісня 4","ps":["Ірмос: Ро́да челові́ча обновле́ніє дре́вле, поя́, проро́к Авваку́м предвозвіща́єть, ви́діти неізрече́нно сподо́бився о́браз: млади́й Младе́нець бо із гори́ — Ді́ви ізи́де, люде́й во обновле́ніє, Сло́во.","Приспів: Свята́я равноапо́стольная Ні́но, моли́ Бо́га о нас.","Я́коже лев, безстра́шна преби́вши, крі́пці Христа́ Бо́га пропові́дала єси́: па́рф'ян си́лою чуде́с улови́ла єси́, Гаяні́ю же і Рипсимі́ю по́двигом до́блественнаго їх му́ченичества в дар Христу́ принесла́ єси́. Той же сохрани́ тебі́ саму́ю, во є́же просвіти́ти тобо́ю І́верськую страну́.","Приспів: Свята́я равноапо́стольная Ні́но, моли́ Бо́га о нас.","Я́коже оре́л, во о́чію твоє́ю возобрази́ла єси́ І́верськую страну́ на́шу, пресла́вная Ні́но, і, свято́ю ре́вностію по Бо́зі разже́гшися, святи́м Єва́нгелієм сію́ просвіти́ла єси́.","Власть іму́щи разгна́ти мглу, му́драго царя́ просвіти́ла єси́, равноапо́стольному царю́ Константи́ну уподо́бльшися, наста́внице на́ша і врачу́ сми́сленний. Сего́ ра́ди ублажа́єм і́м'я твоє́, ді́во, пропові́днице Христа́, вели́кая равноапо́стольная Ні́но.","Богородичен: От ле́сти і́дольськия Тобо́ю, Богоро́дице, ізба́влени би́вше лю́діє І́верстії, ї́хже Тебі́ жре́бій показа́, і, благові́стієм преподо́бния ма́тере на́шея Ни́ни озаре́ни би́вше, взива́ють к Тебі́: ізбавле́ніє на́ше, спаси́ ни, Ма́ти Христа́ Бо́га."]},{"h":"Пісня 5","ps":["Ірмос: Із но́щі діл омраче́нния пре́лести очище́ніє нам, Христе́, бо́дренно ни́ні соверша́ющим піснь, я́ко Благоді́телю, прийди́, подава́яй удо́бну стезю́, по не́йже востека́юще, обря́щем сла́ву.","Приспів: Свята́я равноапо́стольная Ні́но, моли́ Бо́га о нас.","Падо́ша і́доли во страні́ І́верстій і созда́шася хра́ми Госпо́дні тобо́ю, ма́ти на́ша. Ми же, ча́да Сіо́на, тобо́ю просвіще́ни би́вше, днесь прославля́єм Трийпоста́сноє Божество́, сла́вим Честни́й Крест Христа́ і честву́єм цільбоно́сний хито́н Єго́.","Приспів: Свята́я равноапо́стольная Ні́но, моли́ Бо́га о нас.","Си́нове тіх, і́же от дній столпотворе́нія Вавило́нська злоче́стієм пліне́ні би́ша і піснь Госпо́дню воспіва́ти не разумі́ша, ни́ні ізше́дше от святи́я купі́лі, глаго́лють: во Христа́ облеко́хомся, во Христа́ крести́вшеся.","Єгда́ ца́рствова фарао́н над єги́птяни, ті́ї, во тьмі єги́петстій сідя́ще, і́стинному Бо́гу служи́ти не мого́ша; днесь же ми, ча́да Сіо́на, Ни́ною ізба́влени би́вше, ра́достно пої́м Го́сподеві.","Богородичен: Єгда́ приспі́ ко мні врачь, Пресвята́я Богоро́дице, тогда́ воста́х от одра́ моєго́, немощству́яй, і преподо́бною Ни́ною ізба́вихся от ле́сти і́дол нечи́стих, — сія́ род І́верський взива́єть, глаго́ля, — воспіва́ю Тя, упова́ніє моє́, Ма́ти Бо́жия."]},{"h":"Пісня 6","ps":["Ірмос: Обита́я Іо́на в преіспо́дніх морськи́х, прийти́ моля́щеся і бу́рю утоли́ти; унзе́н же аз му́чащаго стріло́ю, Христу́ воспіва́ю, зол губи́телю, ско́ро прийти́ Тебе́ к моє́й лі́ності.","Приспів: Свята́я равноапо́стольная Ні́но, моли́ Бо́га о нас.","Возсія́вшу сві́ту от за́пада, преста́ни, сі́вері, і пові́й, ю́же, со́лнце бо восхо́дить разгна́ти мглу, і близ єсть дхнове́ніє теплоти́, во є́же та́яти ле́ду: се гряде́ть пропові́дниця Христа́, Ни́на свята́я.","Приспів: Свята́я равноапо́стольная Ні́но, моли́ Бо́га о нас.","От тьми і́дольськия ізба́влени би́вше тобо́ю, равноапо́стольная Ні́но, всі лю́діє Картали́нстії воспіва́ють тя і умиле́нно взива́ють: отжени́ от нас зло́бу, дия́вола же і супоста́ти на́ша порази́.","Угото́ванная тобо́ю при столпі́ животво́рнім і мі́сті хране́нія хито́на Госпо́дня купі́ль свята́я не мертви́ть младе́нці, но сія́ возражда́єть, єле́єм святи́м умаща́ющи. Ті́мже вопіє́м ті: ра́дуйся, ді́во, равноапо́стольная Ні́но.","Богородичен: Наде́ждо непости́дная наді́ющихся на Тя, єди́на, ро́ждшая па́че єстества́ пло́тію Христа́ Бо́га на́шего, Того́ со блаже́нною Ни́ною моли́ пода́ти І́верстій страні́ утвержде́ніє і преспі́яніє во ві́рі і всім нам пре́жде конця́ житія́ ісправле́ніє."]},{"h":"Кондак, глас 2","ps":["Прийді́те днесь всі, воспої́м ізбра́нную от Христа́ равноапо́стольную пропові́дницю Бо́жия сло́ва, му́друю благові́стницю, лю́ди Картали́нії приве́дшу на путь живота́ і і́стини, Богома́тере учени́цю, усе́рдную засту́пницю і неусипа́ющую храни́тельницю на́шу, Ні́ну прехва́льную."]},{"h":"Ікос","ps":["В гу́сліх духо́вних да восхва́литься му́драя пропові́дниця, Іве́рії просвіти́тельниця, в купі́лі креще́нія ізбра́нними па́стирми освяти́вшая лю́ди, жре́бієм свиді́тельствованния, равноапо́стольная, возлю́бленная раба́ Христо́ва, я́же де́сять за́повідей Бо́жиїх прия́т, я́коже Мойсе́й Богови́дець. Прийді́те у́бо, днесь ублажи́м пі́сньми усе́рдную засту́пницю і неусипа́ющую храни́тельницю на́шу, Ні́ну прехва́льную."]},{"h":"Пісня 7","ps":["Ірмос: Всецаря́ любо́вію уловле́ннії, о́троци укори́ша безчи́сленно яря́щася мучи́теля злобо́жноє язиковре́діє. І́мже повину́ся огнь мно́гий, Влади́ці глаго́лющим: во ві́ки благослове́н єси́.","Приспів: Свята́я равноапо́стольная Ні́но, моли́ Бо́га о нас.","Черто́зі царя́ і цари́ці я́ко плі́нницю і стра́нницю тя призрі́ша, оба́че і сія́ от плі́на преіспо́дняго благода́тію Христо́вою привела́ єси́ ко Христу́ Бо́гу, Ні́но равноапо́стольная, благові́стнице спасе́нія.","Приспів: Свята́я равноапо́стольная Ні́но, моли́ Бо́га о нас.","Внегда́ воздви́гнути тебі́ столп святи́й і возді́яти ру́ці твої́, устраши́шася си́ли дия́вола і со тре́петом біжа́ща, возрида́ша го́рко. Ми же вопіє́м: благослове́н єси́, Христе́ Бо́же, во ві́ки.","Возвіща́ємим словесе́м твої́м, падо́ша ниць лю́діє, я́ко от гла́са труб царе́вих, і ца́рства і ца́ріє вострепета́ша, глаго́люще: О, плі́ннице і плі́нних свобожде́ніє! Бу́ди благослове́нно прише́ствіє твоє́.","Богородичен: Я́ві предрече́нная проро́ки, Ма́ти Бо́жия, Пренепоро́чная Ді́во Марі́є, пребива́нієм Твої́м во Єги́пті с Богомладе́нцем Ісу́с Христо́м, істука́ни єги́петськия сокруши́ла єси́ до основа́ній, і Ни́ною потреби́ла єси́ куми́ри Картали́нії, бу́ди благослове́нна, Присноді́во."]},{"h":"Пісня 8","ps":["Ірмос: Утро́бу неопа́льно образу́ють Отрокови́ці і́же во ве́тсім опаля́ємії ю́ноши, преєсте́ственно ражда́ющую запечатлі́нну; обоя́ же содіва́ющи чудоді́йство єди́но, лю́ди к пі́нію возставля́єть благода́ть.","Приспів: Свята́я равноапо́стольная Ні́но, моли́ Бо́га о нас.","Па́м'яті святи́я Ни́ни подоба́єть пра́зднество. Прийді́те у́бо, ві́рнії, Христу́, просла́вим і возблагодари́м ми́лостиваго Бо́га. Ро́ди же, і племена́, і ча́да Сіо́на, в духо́вній ра́дости торжеству́йте ку́пно с на́ми, глаго́люще: сла́ва пропові́днице Христа́ і Бо́га на́шего.","Приспів: Свята́я равноапо́стольная Ні́но, моли́ Бо́га о нас.","Ра́дуйся, страно́ Картали́нськая, от Ни́ни вінце́м Христо́вим вінча́нная, світи́ся і благоукраша́йся: призива́єть бо ни равноапо́стольная свята́я Ни́на, сві́том Госпо́днім вся озаря́ющи.","Ти запові́дала єси́ нам, равноапо́стольная, ві́ру свя́то блюсти́, є́йже новообраще́нния лю́ди научи́ла єси́. Сего́ ра́ди вертогра́ди, я́же насади́ла єси́ в духо́вній па́стві твоє́й, посіти́ і утверди́.","Богородичен: О, Ма́ти Христа́ Бо́га, Творця́ су́щих, сподо́бльшійся Тобо́ю жи́зні ві́чния род Картали́нський храни́ моли́твами Ни́ни блаже́нния."]},{"h":"Пісня 9","ps":["Ірмос: Люби́ти у́бо нам я́ко безбі́дноє стра́хом удо́біє молча́ніє; любо́вію же, Ді́во, пі́сні тка́ти, спротяже́нно сложе́нния, неудо́бно єсть. Но і, Ма́ти, си́лу, єли́ко єсть проізволе́ніє, даждь.","Приспів: Свята́я равноапо́стольная Ні́но, моли́ Бо́га о нас.","Вожделі́нна нам па́м'ять твоя́, ди́вно чудоді́йство твоє́, свя́то житіє́ твоє́ — вся нам бива́ють во бла́го тобо́ю, Ні́но цілому́дренная.","Приспів: Свята́я равноапо́стольная Ні́но, моли́ Бо́га о нас.","Прия́телище моще́й твої́х, благода́ть істоча́ющих, утвержде́ніє єсть страні́ Івери́йстій. Сего́ ра́ди і взива́єть к тебі́: блаже́нная Ні́но, охраня́й нас твої́м заступле́нієм.","Пропові́днице і просвіти́тельнице, при́зри на пі́ніє на́ше умиле́нноє і уми́лостиви к нам Го́спода, не попусти́ нам, хвали́ твоєя́ ревни́телем, во грісі́х поги́бнути і, предстоя́щи престо́лу Бо́жию, моли́ Христа́ Бо́га спасти́ся душа́м на́шим.","Богородичен: Усли́ши моле́нія на́ша, Ма́ти Бо́жия, і преподо́бния Ни́ни заступле́нієм отжени́ от нас вся іскуше́нія, да́руй нам ми́лость Твою́ і побі́ду на враги́."]},{"h":"Світилен","ps":["Равноапо́стольная пропові́днице і благові́стнице Христо́ва, от наві́т вра́жиїх ізбавля́ющая ни! А́ще і в ні́дріх землі́ сокрове́на єси́ от о́чію на́шею, оба́че жива́ пребива́єши у престо́ла Христа́ Бо́га на́шего. Бу́ди у́бо засту́пниця усе́рдно чту́щим тя."]}],"notes":[]},{"u":"Канон преподобному Антонію Великому","e":"Canon to St Anthony the Great","secs":[{"h":"Глас 8. Пісня 1","ps":["Ірмос: Колесницегони́теля фарао́ня погрузи́ чудотворя́й іногда́ Моїсе́йський жезл, крестообра́зно порази́в і разділи́в мо́ре, Ізра́їля же біглеця́, пішехо́дця спасе́, піснь Бо́гові воспіва́юща.","Приспів: Преподо́бне о́тче Анто́ніє, моли́ Бо́га о нас.","Безсме́ртія і жи́зні є́мся ві́чния я́ві і Трисія́нния зари́, о́тче, насища́яся, просвіще́нієм благода́ті омраче́нную ду́шу мою́ озари́ти помоли́ся, я́ко да досто́йно воспою́ тя.","Приспів: Преподо́бне о́тче Анто́ніє, моли́ Бо́га о нас.","Млад сий во́зрастом тілесе́, нов путь доброді́телі восприє́м, сим безбі́дно ше́ствовал єси́, зако́ну но́вому повину́яся Спа́сову, треблаже́нне, і живоно́сним повелі́нієм Єва́нгелія послі́дуя.","Трисо́лнечним сія́нієм, всему́дре, озаря́єм, злоу́мноє, блаже́нне, де́монов свирі́пство, і звіре́й зія́нія, і ран болі́зні, я́коже паучи́ну, разори́л єси́, Боже́ственним разжиза́єм жела́нієм.","Богородичен: Я́ко Бо́жия Ма́ти, дерзнове́ніє іму́щи к ро́ждшемуся із Тебе́ Єдиноро́дному Сло́ву, і Отцю́ Собезнача́льному, і Соєсте́ственному Ду́ху, моля́щи не преста́й от бід спасти́, Всенепоро́чная, Тя, Богоро́дицю, сла́в'ящия."]},{"h":"Пісня 3","ps":["Ірмос: Утвержде́й в нача́лі небеса́ ра́зумом і зе́млю на вода́х основа́вий, на ка́мені м'я, Христе́, за́повідей Твої́х утверди́, я́ко ність свят, па́че Тебе́, Єди́не Человіколю́бче.","Приспів: Преподо́бне о́тче Анто́ніє, моли́ Бо́га о нас.","Утвержде́нним по́мислом і крі́пким терпі́нієм страсте́й ув'яди́л єси́ пла́мень, в безстра́стія сві́тлую оде́жду, Анто́ніє, оді́ялся єси́, о́тче, і спасе́нія ри́зу.","Приспів: Преподо́бне о́тче Анто́ніє, моли́ Бо́га о нас.","Крепча́йшия прило́ги де́монов дерза́ющих і зві́рськими о́брази подо́б'ящихся, пренебре́гл єси́ тіх немощну́ю си́лу, крі́пкаго бо імі́л єси́ во бранеіх Спомо́щника.","Богоно́сець, нача́ла тьми і вла́сті обличи́во воздержа́нієм крі́пким, до́блественний побіди́тель, Анто́ніє, бил єси́, по́стников сла́ва, мона́шествующих похвала́.","Богородичен: Умерщвле́нний мой ум живо́тним ді́йством, із Тебе́ я́вльшимся ми́ру, воздви́гни, Чи́стая, і к жи́зні наста́ви, я́же сме́рті две́рі разо́ршая єди́на Рождество́м Твої́м."]},{"h":"Сідален, глас 8","ps":["Ду́шу твою́ связа́в любо́вію Христо́вою, земна́я возненави́дів вся му́дре, водвори́лся єси́, о́тче преподо́бне, в пусти́нях і гора́х, разу́мнаго бо дре́ва вкуси́в, сла́вне, я́ко от незаходи́мих, таї́нниче, а́нгельськи просія́л єси́. Ті́мже і, мрак проше́д пло́ті твоєя́, тьму отгна́л єси́ де́монов, Анто́ніє, і, мона́шествующих предизбра́нний, моли́ Христа́ Бо́га прегріше́ній оставле́ніє пода́ти чту́щим любо́вію святу́ю па́м'ять твою́.","Богородичен: Я́ко Всенепоро́чная Неві́сто Творця́, я́ко Неіскусому́жная Ма́ти Ізба́вителя, прия́телище я́ко су́щи Уті́шителя, Всепі́тая, беззако́нія м'я су́ща скве́рноє оби́телище і де́монов ігра́лище в ра́зумі би́вша, потщи́ся от тіх злоді́йства м'я ізба́вити і сві́тлоє жили́ще доброді́телей соверши́, Світоно́сная Нетлі́нная. Отжени́ о́блак страсте́й, і ви́шняго прича́стія сподо́би, і Сві́та Невече́рняго моли́твами Твої́ми."]},{"h":"Пісня 4","ps":["Ірмос: Ти моя́ крі́пость, Го́споди, Ти моя́ і си́ла, Ти мой Бог, Ти моє́ ра́дованіє, не оста́вль ні́дра О́тча, і на́шу нищету́ посіти́в. Тім с проро́ком Авваку́мом зову́ Ті: си́лі Твоє́й сла́ва, Человіколю́бче.","Приспів: Преподо́бне о́тче Анто́ніє, моли́ Бо́га о нас.","Доброді́телей лі́ствицю Боже́ственную употреби́в, к висоті́, о́тче, возше́л єси́ і Бо́га ви́діл єси́, на ней утвержде́на і да́ри раздава́юща руко́ю богаті́йшею ві́рно пою́щим: си́лі Твоє́й сла́ва, Человіколю́бче.","Приспів: Преподо́бне о́тче Анто́ніє, моли́ Бо́га о нас.","Весь Бо́гу освяти́лся єси́, Анто́ніє, єди́н Єди́ному, всему́дре, єдиня́яся доброді́телію і бесі́дами і богоявле́нія, я́ко чист, сподобля́єм: землі́ бо і земни́х отступи́в, досто́йно небе́сноє обрі́л єси́ наслажде́ніє.","Ум і ду́шу очи́стив, Анто́ніє, пре́лесть, о́тче, душегу́бную, і кова́рствія, і ле́сти го́ркия, і мечта́нія враго́в обличи́л єси́, пострада́в бо, нави́кл єси́ і, научи́вся, учи́ши мона́шествующих мно́жества, всеблаже́нне.","Богородичен: Бо́га, із Тебе́ воплоще́ннаго, моли́, непрело́жно, є́же бі, преби́вша і єсте́ственно ра́вна Отцю́, і Тебі́, Ро́ждшей, би́вша Єдиносу́щна, проще́ніє прегріше́ній і душ спасе́ніє пою́щим Тя ві́рою дарова́ти."]},{"h":"Пісня 5","ps":["Ірмос: Вску́ю м'я отри́нул єси́ от лиця́ Твоєго́, Сві́те незаходи́мий, і покри́ла м'я єсть чужда́я тьма окая́ннаго? Но обрати́ м'я, і к сві́ту за́повідей Твої́х путі́ моя́ напра́ви, молю́ся.","Приспів: Преподо́бне о́тче Анто́ніє, моли́ Бо́га о нас.","Живу́ща в тебі́ імі́я вся ви́дящаго Бо́га, блаже́нне, науча́юща тя, і просвіща́юща, і умудря́юща, душ, треблаже́нне, чи́стих і блаже́нних восхо́ди зрі́ти сподо́бился єси́.","Приспів: Преподо́бне о́тче Анто́ніє, моли́ Бо́га о нас.","Ісціле́ній тебі́ благода́ть на неду́ги разли́чния дарова́ і на ду́хи нечи́стия Христо́с власть, му́дре: єстество́ бо, о́тче, побіди́в, па́че єстества́ даро́в причасти́лся єси́ Ду́ха.","Богородичен: Тя сті́ну іму́ще і предста́тельством Твої́м соблюда́єми, Твоє́ю боже́ственною сла́вою хва́лящеся, Тя блажи́м: Ти бо, Всечи́стая, душа́м на́шим істоча́єши весе́ліє і ра́дованіє."]},{"h":"Пісня 6","ps":["Ірмос: Бе́здна гріхо́в і прегріше́ній бу́ря м'я смуща́єть і во глубину́ ну́жднаго рі́єть м'я, отча́янія, но Твою́ крі́пкую ру́ку мні простри́, я́ко Петро́ві, о Упра́вителю, і спаси́.","Приспів: Преподо́бне о́тче Анто́ніє, моли́ Бо́га о нас.","Зако́нноє страда́льчеськи житіє́ от м'я́гких ногте́й восприї́м, богому́дре, да́же до конця́ соблю́л єси́ і, я́ко боже́ствен до́блественник, віне́ць прия́л єси́ побі́ди от всіх Ца́рствующаго.","Приспів: Преподо́бне о́тче Анто́ніє, моли́ Бо́га о нас.","Іму́ще тя к Бо́гу моли́твенника кріпча́йша, блаже́нне, і о́бщника попече́ній, і предста́теля, і побо́рника, і хода́тая благоче́стна, от вся́ких спаса́ємся бід, і напа́стей, і обстоя́ній.","Богородичен: Вознесла́ єси́ всеї́стинно па́дшеєся челові́чеськоє существо́, во зра́ці Боже́ственнім і Отця́ в ра́венстві, ви́димаго Си́на неізмі́ннаго, Богома́ти, без сі́мене во чре́ві поноси́вши."]},{"h":"Кондак, глас 2","ps":["Жите́йськія молви́ отри́нув, безмо́лвно житіє́ сконча́л єси́, Крести́теля подража́яй вся́ким о́бразом, преподо́бнійший, с ним у́бо тя почита́єм, отце́в нача́льниче, Анто́ніє."]},{"h":"Ікос","ps":["Христо́в глас усли́шав, ше́ствовал єси́ в слід Того́ за́повідей, наг житія́ бив, і отве́ргл єси́ попече́нія вся стяжа́ній, імі́ній і рабо́в твої́х, і сестри́ любле́ніє, богоно́се Анто́ніє, і, єди́н в пусти́нях Бо́гу бесі́дуя чисті́йше, ра́зума благода́ть прия́л єси́, ю́же мі посли́, в пі́сніх тя пою́щему, отце́в нача́льниче, Анто́ніє."]},{"h":"Пісня 7","ps":["Ірмос: Бо́жия снисхожде́нія огнь устиді́ся во Вавило́ні іногда́, сего́ ра́ди о́троци в пещі́, ра́дованною ного́ю, я́ко во цві́тниці, лику́юще поя́ху: благослове́н єси́, Бо́же оте́ць на́ших.","Приспів: Преподо́бне о́тче Анто́ніє, моли́ Бо́га о нас.","Ча́ші би́ша арома́ть лани́ти твоя́, доброді́телей благово́ніє і спасе́ніє благоуха́ющия, я́ко от цві́тника, ві́рою зову́щим: благослове́н Бог оте́ць на́ших.","Приспів: Преподо́бне о́тче Анто́ніє, моли́ Бо́га о нас.","Благода́ть Ду́ха Всесвята́го, в тя все́льшися, духо́в гони́теля лука́вствія, о́тче, соді́ла і мона́шествующих обучи́теля, зову́ща: благослове́н Бог оте́ць на́ших.","Богородичен: Марі́ю Пречи́стую і Всесвяту́ю восхва́лим: То́ю бо благода́ть нам істоча́ється па́че ума́ даро́в, я́ко от пото́ка Боже́ственния бла́гости, Ю́же благочести́вим по́мислом ни́ні ублажи́м."]},{"h":"Пісня 8","ps":["Ірмос: Седьмери́цею пещ халде́йський мучи́тель богочесті́вим неі́стовно разжже́, си́лою же лу́чшею спасе́ни сія́ ви́дів, Творцю́ і Ізба́вителю вопія́ше: о́троци, благослові́те, свяще́нници, воспо́йте, лю́діє, превозносі́те во вся ві́ки.","Приспів: Преподо́бне о́тче Анто́ніє, моли́ Бо́га о нас.","В моли́твах бо́дроє, в поще́ніїх благомо́щноє, терпіли́вноє в напа́стіх, Анто́ніє, ума́ чистото́ю на землі́, я́ко а́нгел, показу́я, Бо́гу вопія́л єси́: о́троци, благослові́те, свяще́нници, воспо́йте, лю́діє, превозносі́те во вся ві́ки.","Приспів: Преподо́бне о́тче Анто́ніє, моли́ Бо́га о нас.","Моли́твами, преподо́бне, і мольба́ми приближа́яся ти непреста́нно к Бо́гу, восте́кл єси́ к висоті́ превзя́тій, де́монських сіте́й ізбі́г, свободи́вся же тіх мучи́тельства, богому́дре, воспіва́єши: свяще́нници, по́йте, лю́діє, превозносі́те во вся ві́ки.","Но́вий Мойсе́й бив, в пусти́ні побі́ду на враги́ і бори́тели поста́вил єси́, лю́ди предводя́, по́стников собо́р во весе́лії і но́вом жи́тельстві, вопію́щих Влади́ці: свяще́нници, благослові́те, лю́діє, превозносі́те во вся ві́ки.","Богородичен: Богороди́тельнице Всечи́стая, душі́ моєя́ я́зви і гріхо́вния стру́пи очи́сти, істо́чниками омива́ющи, су́щими із боку́ Рождества́ Твоєго́ і су́щими із того́ очища́ющи струя́ми, к Тебі́ бо взива́ю, і к Тебі́ прибіга́ю, і Тя призива́ю, Богоблагода́тную."]},{"h":"Пісня 9","ps":["Ірмос: Ужасе́ся о сем не́бо, і землі́ удиви́шася конці́, я́ко Бог яви́ся челові́ком пло́тськи, і чре́во Твоє́ бисть простра́ннійшеє небе́с. Тім Тя, Богоро́дицю, а́нгелов і челові́к чинонача́лія велича́ють.","Приспів: Преподо́бне о́тче Анто́ніє, моли́ Бо́га о нас.","Наста́ світоно́сний твой пра́здник, всеблаже́нне о́тче Анто́ніє, іспо́лнь ра́дости, іспо́лнь весе́лія духо́внаго, іспо́лнь Свята́го Ду́ха, іспо́лнь благоуха́нія і просвіще́нія, і ни́ні, іму́ще тя поще́нія пра́вило і законополо́жника, ра́дуємся.","Приспів: Преподо́бне о́тче Анто́ніє, моли́ Бо́га о нас.","Не преста́й моля́ Ізба́вителя, всечестни́й о́тче, дарова́ти благогові́йно па́м'ять твою́ соверша́ющим свяще́нную, прегріше́ній оставле́ніє, дарова́ній раздая́ніє, боже́ственноє предста́тельство, душ спасе́ніє, ві́чноє ра́дованіє.","Равноа́нгелен пожи́в на землі́, равноа́нгельну обрі́л єси́ сві́тлость, тіх бо богови́днійшим сія́нієм в прича́стії бил єси́. С ни́миже і ра́дуєшися всегда́, я́ко боже́ственний проро́к, я́ко му́ченик вінцено́сець, я́ко мона́шествующих верхо́вник.","Богородичен: Зачала́ єси́, Ді́во, без сі́мене вся́чеськая созда́вшаго Сло́во Бо́жиє, кромі́ хоті́ній плотськи́х, і без істлі́нія родила́ єси́, без болі́зней ма́терніх. Тім Тя, Богоро́дицю, і язи́ком, і се́рдцем іспові́дающе, велича́єм."]},{"h":"Світилен","ps":["Світ єдинонра́вних показа́лся єси́, сві́та ходи́ти стезя́ми благочести́вия научи́в, Анто́ніє, отце́в о́тче, і пла́мень мо́лнії па́ки огнь іспуща́я і попаля́я де́монов полки́.","Богородичен: Тя пі́сньми немо́лчними ублажа́єм, Ді́во, я́ко от Тро́йці Єди́наго родила́ єси́, Богоро́дице, і носи́ла єси́ на боже́ственних об'я́тіїх Пресу́щественноє Сло́во, невра́щно і неізмі́нно."]}],"notes":[]},{"u":"Канон святителю Григорію Богослову","e":"Canon to St Gregory the Theologian","secs":[{"h":"Глас 1. Пісня 1","ps":["Ірмос: Христо́с ражда́ється — сла́віте! Христо́с с небе́с — сря́щіте! Христо́с на землі́ — возносі́теся! По́йте Го́сподеві, вся земля́, і весе́лієм воспо́йте, лю́діє, я́ко просла́вися.","Приспів: Святи́телю, о́тче Григо́ріє, моли́ Бо́га о нас.","Богосло́ва втора́го, столпа́ Сві́та небе́снаго, му́дрости Бо́жия трубу́, прийді́те, сего́ слове́с рачи́теліє, любо́вію соше́дшеся, восхва́лим того́, я́ко богопропові́дника.","Приспів: Святи́телю, о́тче Григо́ріє, моли́ Бо́га о нас.","Сло́во О́тчеє Безнача́льноє, всіх я́ко Бог проми́сленник, промисли́тельною си́лою тя, блаже́нне, Це́ркві, я́коже ма́тері, сло́вом і му́дростію облагодати́в твой ум, дар да́руєть.","Ум влади́ку творя́, стра́сті плотські́я удержа́л єси́ і, вмісти́телен бив Боже́ственних озаре́ній, Єди́наго Бо́га в Тріє́х Ли́ціх просвіти́л єси́ ни че́ствовати, Григо́ріє.","Богородичен: Бо́жия му́дрость храм Себі́ созда́, в Твоє́й всенепоро́чній утро́бі всели́вшися, Благода́тная, і па́че ума́ Сему́ соєдини́вшися по Іпоста́си, Чи́стая, яви́ся я́ко Челові́к."]},{"h":"Пісня 3","ps":["Ірмос: Пре́жде вік от Отця́ рожде́нному нетлі́нно Си́ну і в послі́дняя от Ді́ви воплоще́нному безсі́менно, Христу́ Бо́гу возопії́м: вознеси́й рог наш, Свят єси́, Го́споди.","Приспів: Святи́телю, о́тче Григо́ріє, моли́ Бо́га о нас.","Імі́я прему́дрости істо́чник, непреста́нно істоча́ющ твої́х всему́дрих уче́ній, Христо́ву Це́рков, всеблаже́нне, іспо́лнил єси́, над всі́ми вопію́щую Бо́гу: свят єси́, Го́споди.","Приспів: Святи́телю, о́тче Григо́ріє, моли́ Бо́га о нас.","Благоче́стія велегла́сен пропові́дник і благознамени́ть богосло́вія богосло́в, сокро́вище боговиді́нія оби́льно предлага́ється і раздає́ть бога́тно нам бога́тство неот'є́млемо.","Ри́тор огнедухнове́нний, боговіща́нная цівни́ця благода́ті, богосло́вним вдохнове́нієм і віща́нієм богодухо́вним благознамени́ті возшумі́в, Триіпоста́снаго Существа́ нам піснь воспі́.","Богородичен: Богороди́тельнице, Цари́це всея́ тва́рі, Царя́ вся́чеських моля́щи не преста́й, Христа́, Єго́же нам родила́ єси́ на спасе́ніє су́щих на землі́, спасти́ пою́щия Тя."]},{"h":"Сідален, глас 8","ps":["Отве́рз уста́ сло́вом Бо́жиїм, отри́гнул єси́ прему́дрость, пропові́дниче Сві́та, і мудрова́ніє Боже́ственноє вселе́нній всі́ял єси́, отце́во воі́стину утверди́л єси́ догма́ти, по Па́влу яви́лся єси́ ві́ри побо́рник. Тім і а́нгелов сограждани́н єси́ і сих собесі́дник яви́вся, блаже́нне, богосло́ве Григо́ріє, моли́ Христа́ Бо́га прегріше́ній оставле́ніє дарова́ти пра́зднующим любо́вію святу́ю па́м'ять твою́.","Слава, і нині, Богородичен: Помишле́ньми попо́лзся лука́вими, во глубину́ впадо́х гріхо́вную і, стеня́, зову́ Ті от се́рдця, Всечи́стая: на мні удиви́ бога́тую ми́лость, і Твоєго́ благоутро́бія безмі́рную пучи́ну, і щедро́т Твої́х неісчи́сленноє бога́тство і даждь мі покая́ніє і прегріше́ній проще́ніє, да любо́вію зову́ Тебі́: моли́ Христа́ Бо́га прегріше́ній оставле́ніє дарова́ти мні, Тя бо наде́жду імі́ю, раб Твой."]},{"h":"Пісня 4","ps":["Ірмос: Жезл із ко́рене Ієссе́єва і цвіт от него́, Христе́, от Ді́ви прозя́бл єси́, із гори́, Хва́льний, приосіне́нния ча́щи прише́л єси́, вопло́щся от Неіскусому́жния, Невеще́ственний і Бо́же, сла́ва си́лі Твоє́й, Го́споди.","Приспів: Святи́телю, о́тче Григо́ріє, моли́ Бо́га о нас.","Таї́нник Тро́йці бив, Сея́ просвіти́л єси́ вселе́нную ра́зумом, му́дре, догма́тов лучи́ ізблиста́я, преподо́бне, твоєго́ ізві́стнаго учи́тельства, єму́же поуча́ющеся при́сно, всі благоче́стно восхваля́єм тя.","Приспів: Святи́телю, о́тче Григо́ріє, моли́ Бо́га о нас.","У́тро благоче́стія сві́тлоє, зарю́ трисо́лнечную в себі́ приє́м, возсія́л єси́, і нощ мра́чную злочести́вих єресе́й заре́ю твої́х догма́тов му́дрих отгна́л єси́, і ду́ші, о́тче, ві́рних уясни́л єси́.","Ум Пресу́щний, істо́чник Сло́ва і Ду́ха, із Присносу́щнаго богосло́вним гро́мом, всеблаже́нне, богосло́вствуя, благоче́стно научи́л єси́, сему́ от Него́ науча́єм, я́ко предочи́стив твой ум ве́щних, о́тче, прия́тій.","Возше́л єси́ на го́ру доброді́телей, от до́льних пресели́вся і ме́ртвих діл отступи́в, і скрижа́ли, руко́ю Бо́жиєю напи́санния, догма́ти твоєго́ чи́стаго богосло́вія прия́л єси́, тайноводи́телю Боже́ственних та́їнств, Григо́ріє.","Богородичен: Ра́зумом па́дшаго Ада́ма возста́вила єси́, Всенепоро́чная, Іпоста́сную ро́ждши Жизнь із ложе́сн діви́чеських, очище́нних Ду́хом, і к безстра́стній, і боже́ственнійшей, і нетлі́нній пи́щі сего́ возвела́ єси́, Влади́чице."]},{"h":"Пісня 5","ps":["Ірмос: Бог Сий ми́ра, Оте́ць щедро́т, вели́каго Сові́та Твоєго́ А́нгела, мир подава́юща, посла́л єси́ нам; тім, богоразу́мія к сві́ту наста́вльшеся, от но́щі у́тренююще, славосло́вим Тя, Человіколю́бче.","Приспів: Святи́телю, о́тче Григо́ріє, моли́ Бо́га о нас.","Глаго́л твої́х Боже́ственноє віща́ніє і догма́тов благода́ть Боже́ственная, я́ко ско́рость мо́лнії, всю обтече́ зе́млю, Тро́йце во Єди́ниці, Єди́нице в Тро́йці, покланя́тися, богосло́ве, богосло́вствуя і науча́я нас.","Приспів: Святи́телю, о́тче Григо́ріє, моли́ Бо́га о нас.","Возжела́л єси́ і́стинно му́дрости Бо́жия, і слове́с добро́ту возлюби́л єси́, і всіх предпочти́л єси́ кра́сних, су́щих на землі́, ті́мже тя вінце́м, всеблаже́нне, дарова́ній благолі́пно украси́ і богосло́ва соді́ла.","Разу́мно ти Су́щаго, я́ко дре́вле Мойсе́й, ви́діти, богоглаго́ливе, вожделі́л єси́, і Сего́ за́дняя, ка́менем покри́вся, ви́діти сподо́бился єси́, і пучи́ни научи́лся єси́ Боже́ственния му́дрости, непости́жно явля́ємия.","Богородичен: І́же дре́вле Є́ву, прама́тер Твою́, Созда́вий із Тебе́ зи́ждеться, тоя́ осужде́ніє і преслуша́ніє я́ві ісціля́я і разріша́я, я́ко Щедр і Влади́ка всіх, Богороди́тельнице Ма́ти Ді́во."]},{"h":"Пісня 6","ps":["Ірмос: Із утро́би Іо́ну младе́нця ізблева́ морськи́й звір, якова́ прия́т; в Ді́ву же все́льшеєся Сло́во і плоть приє́мшеє про́йде, сохра́ншеє нетлі́нну: Єго́же, бо не пострада́ істлі́нія, Ро́ждшую сохрани́ неврежде́нну.","Приспів: Святи́телю, о́тче Григо́ріє, моли́ Бо́га о нас.","Струя́ми му́дрих уче́ній твої́х, всему́дре, А́рієв ум му́тнійший ізсуши́л єси́, в тишині́ храня́ па́ству твою́ непотопле́нну, я́коже слове́сний ковче́г, в не́мже благоче́стія сі́мена положи́л єси́ добро́тою слове́с твої́х.","Приспів: Святи́телю, о́тче Григо́ріє, моли́ Бо́га о нас.","Да Честни́я Тро́йці осія́нієм обогати́ши ум, о́тче, уясни́л єси́, я́коже нескве́рноє і новоочище́нноє зерца́ло, воздержа́нієм ізря́дним соді́лав. Ті́мже і богови́днійший показа́лся єси́ Боже́ственними явле́ньми.","Весь сраствори́вся заре́ю Ду́ха, бил єси́ світи́льник, о́тче, всесві́тел, сві́тлостію твої́х слове́с просвіща́яй конці́ і богосло́вія чистото́ю украша́яй кра́сноє торжество́ ві́рних, богосло́ве Григо́ріє.","Нов Самуї́л богода́нен яви́лся єси́, дан Бо́гу, і пре́жде зача́тія, всеблаже́нне, цілому́дрієм і чистото́ю украша́єм і свяще́нства всесвято́ю оде́ждею, о́тче, удобре́н, хода́тайствуя Зижди́телю і зда́нію.","Богородичен: Сви́ток чист, Сло́во приє́мий напи́санноє, пре́жде неопи́санноє, Божество́м, предзна́лася єси́ проро́ки і пе́рвіє, Ма́ти Ді́во, Марі́є Богоневі́сто: Ти бо Неодержи́маго во утро́бі Твоє́й несказа́нно вмісти́ла єси́."]},{"h":"Кондак, глас 3","ps":["Богосло́вним язи́ком твої́м сплете́нія ри́торськая разруши́вий, сла́вне, правосла́вія оде́ждею, сви́ше істка́нною, Це́рков украси́л єси́, ю́же і нося́щи, с на́ми зове́ть, твої́ми ча́ди: ра́дуйся, о́тче, богосло́вія у́ме кра́йнійший."]},{"h":"Ікос","ps":["От богосло́вния і висо́кия му́дрости твоєя́ іспо́лни мой ум, убо́гий і стра́стний, я́ко да воспою́ житіє́ твоє́, о́тче: не могу́ бо сло́ва принести́ тебі́, а́ще не ти пода́си мі крі́пость сло́ва, і ра́зум, і му́дрость, я́ко да от твої́х твоя́ принесу́ тебі́, і от бога́тства доброді́телей твої́х отту́ду обря́щу вину́, і увінча́ю честну́ю і святу́ю твою́ главу́, с ві́рними взива́я: ра́дуйся, о́тче, богосло́вія у́ме кра́йнійший."]},{"h":"Пісня 7","ps":["Ірмос: О́троци, благоче́стію совоспита́ни, злочести́ваго велі́нія небре́гше, о́гненнаго преще́нія не убоя́шася, но, посреди́ пла́мене стоя́ще, поя́ху: отце́в Бо́же, благослове́н єси́.","Приспів: Святи́телю, о́тче Григо́ріє, моли́ Бо́га о нас.","Все жела́ніє і сла́дость я́ві сло́во твоє́, все, Григо́ріє, по́лно весе́лія і сві́тлости, благоуха́нія насища́я ві́рою пою́щия: отце́в Бо́же, благослове́н єси́.","Приспів: Святи́телю, о́тче Григо́ріє, моли́ Бо́га о нас.","Умо́м просвіще́нним Істо́чника просвіще́ній дости́гл єси́ і, отону́дними мо́лніями распаля́єм, опали́л єси́ Євно́мієво язикобо́ліє, Тро́йце вопія́: отце́в Бо́же, благослове́н єси́.","Отве́рз хля́би бе́здни му́дрих догма́тов твої́х, заусти́в же істо́чника му́дрости, покри́л єси́ пре́лести началовожди́, облиста́єм ві́чним Сві́том і Трисо́лнечним.","Богородичен: Я́ко дождь на руно́, низше́д, в Твою́ всели́ся утро́бу ми́ра ріка́, істо́чник бла́гости, І́же ка́плі дожде́вния ісчита́я, отце́в Бо́же, благослове́н єси́."]},{"h":"Пісня 8","ps":["Ірмос: Чу́да преєсте́ственнаго росода́тельная ізобрази́ пещ о́браз: не бо, я́же прия́т, пали́ть ю́ния, я́ко ніже́ огнь Божества́ — Ді́ви, в Ню́же вни́де утро́бу. Тім, воспіва́юще, воспоє́м: да благослови́ть твар вся Го́спода і превозно́сить во вся ві́ки.","Приспів: Святи́телю, о́тче Григо́ріє, моли́ Бо́га о нас.","Ра́вно Отцю́ Сло́во і Дух бла́гостію і ца́рством, благочести́во научи́л єси́, су́щественно і єсте́ственно то́ждество зна́я і єдине́ніє. Ті́мже вопіє́ши, ра́дуяся: да благослови́ть твар вся Го́спода і превозно́сить во вся ві́ки.","Приспів: Святи́телю, о́тче Григо́ріє, моли́ Бо́га о нас.","Сла́ви а́нгельськия удосто́їлся єси́, я́ко бо а́нгел, просія́л єси́ ми́ру, Тро́йце, всему́дре, очи́стив прилі́жно ду́шу же, і ті́ло, і мисль. Є́йже ни́ні воспіва́єши, веселя́ся: да благослови́ть твар вся Го́спода і превозно́сить во вся ві́ки.","Ми́лостива моли́твами твої́ми Влади́ку соді́лав, іспроси́, о́тче, прегріше́ній оставле́ніє ві́рою свяще́нную і всепра́зднственную твою́ па́м'ять пра́зднующим. В не́йже, веселя́щеся, воспіва́єм: да благослови́ть твар вся Го́спода і превозно́сить во вся ві́ки.","Таї́нник Триіпоста́снаго Єдинонача́лія і Божества́, су́щаго в Тро́йці, доброді́телей обуче́ньми бив, Тро́їчеський богосло́в показа́лся єси́, всеблаже́нне. І ни́ні воспіва́єши, ра́дуяся: да благослови́ть твар вся Го́спода і превозно́сить во вся ві́ки.","Богородичен: І́же арха́нгельськими пісносло́вії сла́вимоє бога́тноє Сло́во нас ра́ди обнища́, Тя Ма́тер, добро́ту Іа́ковлю благослове́нную, ізбра́в. Ті́мже, воспіва́юще, поє́м: да благослови́ть твар вся Го́спода і превозно́сить во вся ві́ки."]},{"h":"Пісня 9","ps":["Ірмос: О́браз чи́стаго рождества́ Твоєго́ огнепали́мая купина́ показа́ неопа́льная; і ни́ні на нас напа́стей свирі́піющую угаси́ти, мо́лимся, пещ, да Тя, Богоро́дице, непреста́нно велича́єм.","Приспів: Святи́телю, о́тче Григо́ріє, моли́ Бо́га о нас.","Дає́ть тебі́ жизнь нетлі́нную Нача́льная Тро́йця, Ю́же богосло́вил єси́, приє́мши, Єя́ ра́ди по́двиги твоя́, і уче́нія, і боре́нія, Є́йже ни́ні, о́тче, предстої́ши, о ми́рі моли́твенник ізя́щнійший.","Приспів: Святи́телю, о́тче Григо́ріє, моли́ Бо́га о нас.","Заре́ю Трисія́нния сві́тлости, от Єди́наго проісходя́щею Божества́, осія́єм, священнотаї́нниче Григо́ріє, пою́щия тя ві́рою спаса́й і твої́х догма́тов богосло́вієм світово́ждствуй.","Тече́ніє до́броє соверши́л єси́, за Нача́льную Тро́йцю подвиза́вся, і обоже́ніє я́ко богосло́в получи́л єси́, і боже́ственнаго твоєго́ жела́нія ісполне́ніє прия́л єси́ досто́йно, Церкве́й благоукраше́ніє.","Богородичен: О, стра́шнаго Твоєго́ чудесе́! Ти бо, Ді́во Богоро́дице, та́їнство, пре́жде родо́в і пре́жде віко́в сокрове́нноє в Бо́зі, вся́чеськая Созда́вшем, ро́ждши Бо́га Сло́ва, несказа́нно яви́ла єси́."]},{"h":"Світилен","ps":["Меч слове́с твої́х і си́ла сего́ язи́ки отсіче́ неві́рних до конця́, я́ко вещ бо терно́вную, тіх попали́л єси́ безбо́жная новосіче́нія, Тро́йце научи́л єси́ покланя́тися боголі́пно, Григо́ріє Богосло́ве.","Слава: Єди́нице Трийпоста́сній і Тро́йце соверше́нней в Єди́ном Божестві́, всему́дре богосло́ве, научи́л єси́ покланя́тися: Світ, реки́й, Отця́ і Си́на Світ, па́ки же Світ Ду́ха Свята́го. Но Єди́н Світ, Неразді́лен, Неслія́нен, Єди́н бо Бог, уясня́яй Єдиносу́щноє, о Григо́ріє блаже́нне!","І нині: С Богома́терію і Ді́вою Марі́єю і Васи́лієм, всему́дре, предстоя́й вели́ким, Непристу́пній Тро́йце, мир ми́ру, тишину́ Це́ркві, побі́ди і нам спасе́ніє іспроси́, ни́ні восхваля́ющим тя, богосло́ве архієре́ю Григо́ріє, ри́торе церко́вний."]}],"notes":[]},{"u":"Канон святителю Іоанну Золотоустому","e":"Canon to St John Chrysostom","secs":[{"h":"Глас 8. Пісня 1","ps":["Ірмос: Колесницегони́теля фарао́на погрузи́ чудотворя́й іногда́ Моїсе́йський жезл, крестообра́зно порази́в і разділи́в мо́ре, Ізра́їля же біглеця́, пішехо́дця, спасе́, піснь Бо́гові воспіва́юща.","Приспів: Святи́телю о́тче Іоа́нне, моли́ Бо́га о нас.","Покая́нія бив теплі́йший пропові́дник, Златоу́сте, пока́ятися мні, о́тче, Бо́гу моли́ся от всего́ се́рдця моєго́ і дре́вніх прегріше́ній ісціли́ти я́зви твої́м страда́тельством умоли́.","Приспів: Святи́телю о́тче Іоа́нне, моли́ Бо́га о нас.","Всю зарю́ Свята́го Ду́ха, о́тче, приї́м, всесві́тел яви́лся єси́ столп, предводи́телен Це́ркве, преподо́бне, сві́тел же о́блак, всеблаже́нне, осіня́ющ правосла́вних собо́ри.","От Христа́ рукоположе́н учи́тель, Боже́ственная уче́нія златови́дним язи́ком, ми́слію же Богому́дрою бога́тно ти істочи́л єси́: Бо́жия бо ріка́, вод іспо́лнен Ду́ха, яви́лся єси́, Богоявле́нне Златоу́сте.","Богородичен: Преукра́шена разли́чієм благода́ті, Богора́дованная, О́тчеє Сло́во, плоть би́вшеє за благоутро́біє мно́гоє па́че ума́ і словесе́, Благослове́нная, родила́ єси́, преби́вши Ді́ва нескве́рная."]},{"h":"Пісня 3","ps":["Ірмос: Утвержде́й в нача́лі Небеса́ ра́зумом і зе́млю на вода́х основа́вий, на ка́мені м'я, Христе́, за́повідей Твої́х утверди́, я́ко ність свят, па́че Тебе́, Єди́не Человіколю́бче.","Приспів: Святи́телю о́тче Іоа́нне, моли́ Бо́га о нас.","Умо́м Ти Христо́вим обога́щся, твої́м чи́стим житіє́м челові́ком спасе́нія бил єси́ споспі́шник і повіствова́тель, ді́йствитель, Златоу́сте, учи́тельства точа́ спаси́тельная, Богодохнове́нне.","Приспів: Святи́телю о́тче Іоа́нне, моли́ Бо́га о нас.","От невеще́ственних сокро́вищ Ду́ха ти обогати́вся, от істо́чников спасе́нія поче́рпл єси́ приснотеку́щий істо́чник уче́ній і напої́л єси́ все Це́ркве, преподо́бне о́тче, лице́.","Олядене́вшия душе́вния, Златоу́сте, ни́ви, прему́дрим земледі́ланієм слове́с ізчи́стил єси́, му́дре, і плодоно́сни показа́л єси́, Небе́сними ту́чами сія́ напая́я, Богоприя́тне.","Богородичен: Поро́ка в Тебі́ і скве́рни ність отню́д, Ді́во, оби́тель же па́че яви́лася єси́ Небе́сних бла́гостей, в Тебі́ бо всели́ся доброді́телей вся святи́ня, Всенепоро́чная."]},{"h":"Сідален","ps":["Неізрече́нния му́дрости Богови́дно поче́рпл єси́ бога́тство ра́зума, всім сокро́вищствовал єси́ Правосла́вія во́ди, ві́рних у́бо сердца́ Боже́ственне веселя́щия, неві́рних же мні́нія досто́йно погружа́ющия: тім отобою́ду благоче́стія по́тами показа́лся єси́ непобі́дний Тро́йці побо́рник, Іоа́нне Златоу́сте. Моли́ Христа́ Бо́га гріхо́в оставле́ніє дарова́ти пра́зднующим любо́вію святу́ю па́м'ять твою́."]},{"h":"Пісня 4","ps":["Ірмос: Ти моя́ крі́пость, Го́споди, Ти моя́ і си́ла, Ти мой Бог, Ти моє́ ра́дованіє, не оста́вль ні́дра О́тча, і на́шу нищету́ посіти́в. Тім с проро́ком Авваку́мом зову́ Ті: си́лі Твоє́й сла́ва, Человіколю́бче.","Приспів: Святи́телю о́тче Іоа́нне, моли́ Бо́га о нас.","Іна́го нам апо́столов єдинонра́внаго, і́же промишле́нієм всіх промишля́я, я́ко Благ, даде́ Христо́с тя, Небе́снаго тайново́дства пропові́дника і Боже́ственнаго сказа́теля та́їн Го́рніх, Іоа́нне всеблаже́нне Златоу́сте.","Приспів: Святи́телю о́тче Іоа́нне, моли́ Бо́га о нас.","Златоза́рнаго і златослове́снаго, почти́м Златоу́стаго Іоа́нна, вся позлати́вшаго златови́дними сія́нії уче́нія і мир язи́ком просвіти́вша, зла́та світлі́йшим і сві́та по́лнійшим, істоча́ющим благода́ть Боже́ственную.","Весь бил єси́ Бо́жиє жили́ще, весь яви́лся єси́ орга́н Ду́ха, возглаша́ющ вся́кия доброді́телі Богодохнове́нную піснь, і спасе́нія вину́, і добро́ту явля́я Небе́снаго Ца́рствія, Іоа́нне всеблаже́нне Златоу́сте.","Ти Бо́жиє благоутро́біє пропові́дал єси́, покая́нія о́брази ізлага́я, і злих отбіжа́нія ізя́щнійше поуча́я, преблаже́нне і всесоверше́ннійше, і о ді́ліх ізря́дних поуче́нія істоча́я, всече́стне о́тче Златоу́сте.","Богородичен: По Бо́зі предста́тельницю Тя стяжа́хом, Ти бо Бо́жия Ма́ти била́ єси́ Творця́ і Соді́теля, і наш зрак приє́мшаго, Всенепоро́чная, і сей спа́сшаго от тлі і сме́рти і сла́вою Боже́ственною просла́вившаго."]},{"h":"Пісня 5","ps":["Ірмос: Вску́ю м'я отри́нул єси́ от лиця́ Твоєго́, Сві́те Незаходи́мий, і покри́ла м'я єсть чужда́я тьма, окая́ннаго; но обрати́ м'я і к сві́ту за́повідей Твої́х путі́ моя́ напра́ви, молю́ся.","Приспів: Святи́телю о́тче Іоа́нне, моли́ Бо́га о нас.","Церко́внаго світи́льника всі тя ві́ми світови́днійшаго і душа́м спаси́тельнаго, восхища́ющаго сія́ із горта́ні смертоно́сния і к жи́зні путеводя́ща ві́чній, о́тче приснопіва́ємий.","Приспів: Святи́телю о́тче Іоа́нне, моли́ Бо́га о нас.","Разруша́єши ополче́нія єрети́чествующих, треблаже́нне, огради́вся благоче́стія ору́жії і му́жеством душі́, свяще́ннійше, собира́єши же, ра́дуяся пресві́тло, правосла́вних ли́ки сою́зом Ду́ха.","Іспо́лнени, я́коже фія́ли, Боже́ственних арома́ть лани́ти твоя́ і вселе́нную у́мними благово́нії веселя́ть мирова́рним тайново́дством разумі́ній і добро́тою слове́с твої́х, всему́дре.","Богородичен: Я́ко Бо́га заче́нши, Соді́теля же, і Зижди́теля, і Го́спода, ро́ди Тя всі челові́честії, Чи́стая, ублажа́ють, і Безтіле́сних разу́мная чинонача́лія я́ко Ма́тер Бо́жию Тя сла́в'ять."]},{"h":"Пісня 6","ps":["Ірмос: Очи́сти м'я Спа́се, мно́га бо беззако́нія моя́, і із глубини́ зол возведи́, молю́ся: к Тебі́ бо возопи́х, і усли́ши м'я, Бо́же спасе́нія моєго́.","Приспів: Святи́телю о́тче Іоа́нне, моли́ Бо́га о нас.","Му́дростію духо́вною мир весь обогати́л єси́, словесе́ раздава́тель бив бога́тий: бога́та бо сви́ше, ієра́рше, благода́ть ізлія́ся твої́м устна́м.","Приспів: Святи́телю о́тче Іоа́нне, моли́ Бо́га о нас.","Во всю, я́ко мо́лнія, зе́млю ізи́де віща́ніє твоє́, і си́ла же твої́х глаго́л, Златоу́сте, я́ко труба́ велегла́сная, вселе́нния вся огласи́ конці́.","Сви́ше во істка́нную ри́зу оді́явся, всеблаже́нне, доброді́телей і слове́с красото́ю обложи́вся, і́стини яви́лся єси́ сла́вноє утвержде́ніє.","Богородичен: Вседержи́тельною си́лою нося́й вся́чеськая, в немощну́ю плоть із Тебе́ оді́явся, Ді́во Пренепоро́чная, на благодія́ніє челові́ков Человіколю́бець."]},{"h":"Кондак, глас 6","ps":["От Небе́с прия́л єси́ Боже́ственную благода́ть, і твої́ми устна́ми вся учи́ши покланя́тися в Тро́йці єди́ному Бо́гу, Іоа́нне Златоу́сте, всеблаже́нне преподо́бне, досто́йно хва́лим тя: єси́ бо наста́вник, я́ко Боже́ственная явля́я."]},{"h":"Ікос","ps":["Всіх Творцю́ преклоня́ю колі́на, преві́чному Сло́ву ру́ки простира́ю, сло́ва іща́ дарова́ніє, да воспою́ преподо́бнаго, єго́же Сам возвели́чи, глаго́леть бо проро́ком Живи́й во ві́ки: просла́влю ві́рою сла́в'ящия М'я. І́же у́бо в дре́вніх Самуї́ла возви́сивий, просла́ви ни́ні ієра́рха: тала́нт бо, єму́же вві́рися, до́брі ку́пльствовав, Царю́ принесе́, тім і превозви́шши єго́ Пресу́щественний. Сего́ благода́ті прошу́ недосто́йний аз сло́во прия́ти мі, да возмогу́ благоче́стно воспі́ти того́: конце́й бо той єсть наста́вник, я́ко Боже́ственная явля́я."]},{"h":"Пісня 7","ps":["Ірмос: Бо́жия снизхожде́нія огнь устиді́ся во Вавило́ні іногда́, сего́ ра́ди о́троци в пещі́ ра́дованною ного́ю, я́ко во цві́тниці, лику́юще, поя́ху: благослове́н єси́, Бо́же оте́ць на́ших.","Приспів: Святи́телю о́тче Іоа́нне, моли́ Бо́га о нас.","Бла́гости бе́здну і благоутро́бія нави́к Бо́жия, пору́чник яви́лся єси́ спасе́нія ка́ющимся те́плі і вседу́шно Го́споду зову́щим: благослове́н Бог оте́ць на́ших.","Приспів: Святи́телю о́тче Іоа́нне, моли́ Бо́га о нас.","Управля́єши, Златоу́сте, уче́нії твої́ми вся́кую мисль, і душе́вния врачу́єши не́мощі, я́ко сострада́тельнійший, і благотеку́щим споє́ши, веселя́ся: благослове́н Бог оте́ць на́ших.","Возви́сился єси́, бив ізбра́н, преподо́бен, незло́бив, свяще́нник Височа́йшаго, пра́вдою оді́ян сві́тло і весе́лієм, зови́й, всебога́те: благослове́н Бог оте́ць на́ших.","Богородичен: Зачала́ єси́, Пречи́стая, Су́щаго над всі́ми Бо́га і Го́спода, благоволи́вшаго спасти́ челові́чеський род от тлі́нія і сме́рті. Єго́же, досто́йно пою́ще, зове́м: благослове́н Бог оте́ць на́ших."]},{"h":"Пісня 8","ps":["Ірмос: Седьмери́цею пещ халде́йський мучи́тель Богочесті́вим неі́стовно разжже́, си́лою же лу́чшею спасе́ни, сія́ ви́дів, Творцю́ і Ізба́вителю вопія́ше: о́троци, благослові́те, свяще́нници, воспо́йте, лю́діє, превозносі́те во вся ві́ки.","Приспів: Святи́телю о́тче Іоа́нне, моли́ Бо́га о нас.","І́же разу́мно словесе́м твої́м бесі́дующе, Златоу́сте, Богосло́вія честно́му у́чимся, і всепло́дствуєм благи́х поле́зноє, і зло́би отбіга́єм вре́да: о́бщий бо строї́тель спасе́нія бил єси́, вопія́: превозносі́те Христа́ во ві́ки.","Приспів: Святи́телю о́тче Іоа́нне, моли́ Бо́га о нас.","За ни моли́ Влади́ку, Златоу́сте, сострада́тельнійшеє дерзнове́ніє імі́я і ми́лостивною і человіколю́бною твоє́ю, о́тче, любо́вію: тя бо ко Спа́су предлага́єм, ві́рнії, хода́тая же, і предста́теля, і теплі́йша моли́твенника, Богому́дре ієра́рше, всеблаже́нне Іоа́нне.","Ю́ношськоє противле́ніє, і непрекло́нноє мудрова́ніє, і ца́рствующих непра́вду обличи́л єси́, те́плі предста́тельствуя оби́димия, преподо́бне; і сиро́т, і вдов, і ни́щих оте́ць бил єси́ любо́вним предложе́нієм, превозносі́те, вопія́, Христа́ во ві́ки.","Богородичен: Тіле́сними образова́нії, і разли́чними гада́нії, і символи́чеськими, і знамена́тельними пред'явле́ньми, Твоє́ провозвісти́ша Богоглаго́ливії рождество́, преєсте́ственноє і чу́дноє, Ді́во; тім Тя, веселя́щеся, благоче́стно воспіва́єм, Христа́ превознося́ще во вся ві́ки."]},{"h":"Пісня 9","ps":["Ірмос: Ужасе́ся о сем Не́бо, і землі́ удиви́шася конці́, я́ко Бог яви́ся челові́ком пло́тськи, і чре́во Твоє́ бисть простра́ннійшеє Небе́с: тім Тя, Богоро́дицю, А́нгелов і челові́к чинонача́лія велича́ють.","Приспів: Святи́телю о́тче Іоа́нне, моли́ Бо́га о нас.","І́стинно наслажда́яся, о́тче, жи́зні, о не́йже подвиза́лся єси́, єли́ко мо́щно, на землі́ житіє́м преізя́ществовав А́нгельським і Христо́в стяжа́в язи́к і уста́ ти́хая: спасти́ся, Богоглаго́ливе, моли́ тя ві́рою ізя́щні блажа́щим.","Приспів: Святи́телю о́тче Іоа́нне, моли́ Бо́га о нас.","Словеса́ твоя́, треблаже́нне, словеса́ жи́зні, жизнь хода́тайствующая неконе́чную: тя бо істо́чника теку́ща показа́ Христо́с і реку́, пролива́ющу Боже́ственних пото́ки уче́ній, сла́дости і́стинно пото́к, оставле́нія же струю́ і покая́нія сві́тла пропові́дника.","Хода́тай яви́лся єси́, священнонача́льниче, Бо́га і челові́ков пресві́тлий, ти бо світи́льник яви́лся єси́ благоче́стія Богосві́тлий і Боже́ственнаго зна́нія і ми́лостині наказа́тель: тім тя, златосло́ве, серде́чною любо́вію ни́ні досто́йно велича́єм.","Богородичен: Чи́стая препросла́вленная Ма́ти Бо́жия, пою́щия Тя любо́вію спаса́й, іскуше́ній молву́ разріша́ющи ми́лостивно. Я́ко бо Бо́га ро́ждши, вся, єли́ко хо́щеши, соверша́єши, успіва́єши невозбра́нно і мо́жеши, Ді́во. Тім Тя всі велича́єм."]},{"h":"Світилен","ps":["Златоза́рними словеси́ твої́ми Христо́ва Це́рков світле́ється я́сно, о Златоу́сті о́тче! Ду́ші же веселя́ться ві́рних, почита́ющия всесвяту́ю твою́ па́м'ять, ти бо всім показа́лся єси́ покая́нія наста́вник і вождь спасе́нія."]}],"notes":[]},{"u":"Канон святителям Василію Великому, Григорію Богослову і Іоанну Золотоустому","e":"Canon to the Hierarchs Basil the Great, Gregory the Theologian and John Chrysostom","secs":[{"h":"Глас 2. Пісня 1","ps":["Ірмос: Гряді́те, лю́діє, пої́м піснь Христу́ Бо́гу, разді́льшему мо́ре і наста́вльшему лю́ди, я́же ізведе́ із рабо́ти єги́петськия, я́ко просла́вися.","Приспів: Святи́теліє Васи́ліє Вели́кий, Григо́ріє Богосло́ве, Іоа́нне Златоу́сте, молі́те Бо́га о нас.","Ко́є благодаре́ніє, ко́є противовоздая́ніє, подоба́ющеє на́шим, челові́ци, принесе́ться от нас благоді́телем, і́миже ко є́же до́брі би́ти наставля́ємся?","Приспів: Святи́теліє Васи́ліє Вели́кий, Григо́ріє Богосло́ве, Іоа́нне Златоу́сте, молі́те Бо́га о нас.","Вити́йстії язи́ци, і хи́трости, і кова́рства, і вся слове́с си́ла ни́ні во вину́ да сподви́гнуться єди́ну і, честву́юще взаї́м, да почту́ть.","Сво́йственнаго у́бо їм не терп'я́ху, даби́ что стяжа́ти на землі́, небому́дреннії, храни́теліє же яви́шася о́бщества і предста́теліє, о́бщих у́бо і похва́л да сподо́б'яться.","Богородичен: Тя, о́бщеє любоче́стіє, Всенепоро́чная, на́шего єстества́, всі сла́вим, уста́ єди́ни би́вше і єди́но согла́сіє соверши́вше."]},{"h":"Пісня 3","ps":["Ірмос: На ка́мені м'я ві́ри утверди́в, разшири́л єси́ уста́ моя́ на враги́ моя́, возвесели́бося дух мой, внегда́ пі́ти: ність свят, я́коже Бог наш, і ність пра́веден, па́че Тебі́, Го́споди.","Приспів: Святи́теліє Васи́ліє Вели́кий, Григо́ріє Богосло́ве, Іоа́нне Златоу́сте, молі́те Бо́га о нас.","Труба́ вели́кая Це́ркве, світи́льник, просвіща́яй вселе́нную, пропові́дник, віща́нієм об'є́мляй вся конці́, великоімени́тий Васи́лій сподвиза́єть собра́ніє сіє́.","Приспів: Святи́теліє Васи́ліє Вели́кий, Григо́ріє Богосло́ве, Іоа́нне Златоу́сте, молі́те Бо́га о нас.","Сві́тел от житія́ і веще́й, сві́тел от слове́с і уче́ній, во всіх пресіява́я па́че всіх, я́коже друго́є па́че звізд со́лнце, многопі́тий Богосло́в днесь блажи́ться.","Се світ ми́ра ми́ру сві́тить, се землі́ соль зе́млю услажда́єть, се дре́во жи́зні безсме́ртія плоди́ предлага́єть, Златоу́стий святи́й. І́же умре́ти не хотя́щії, прийді́те, наслажда́йтеся.","Богородичен: Вся от небитія́ в битіє́ Сотвори́вий і єстество́ Да́вий коєму́ждо би́вших, То́йже і да́нная єстества́ прелага́ти вість, я́коже хо́щеть. Отону́дуже і сли́шимо єсть, я́ко і Ді́ва ро́ждши, — кто не удиви́ться?"]},{"h":"Сідален, глас 8","ps":["Вели́кия світи́льники світоза́рния, Це́ркве столпи́ неразори́мия согла́сно да восхва́лим, і́же до́брих наслажда́ющіїся і слове́с тіх, ку́пно і благода́ті: прему́драго Златоглаго́лива і Вели́каго Васи́лія с Григо́рієм сві́тлим Богосло́вом. К ни́мже і возопії́м, от се́рдця зову́ще: святи́теліє тревелича́йшії, молі́теся Христу́ Бо́гу прегріше́ній оставле́ніє дарова́ти пра́зднующим любо́вію святу́ю па́м'ять ва́шу.","Слава: Прему́дрость приє́мше от Бо́га, я́ко апо́столи іні́ї тріє́ Христо́ви, сло́вом ра́зума составля́єте догма́ти, я́же пре́жде словеси́ прости́ми низлага́ху, ри́баріє в ра́зумі си́лою Ду́ха, подоба́ше бо та́ко про́стій на́шей ві́рі составле́ніє стяжа́ти. Отню́дуже всі вопіє́м вам: молі́теся Христу́ Бо́гу прегріше́ній оставле́ніє дарова́ти пра́зднующим любо́вію святу́ю па́м'ять ва́шу.","І нині: Ду́шу мою́, Ді́во, смире́нную, бу́рею житія́ іскуше́ній ни́ні я́ко кромі́ управле́нія би́вшую, потопля́ємую волна́ми, гріхо́в бре́менем я́вльшуся преіспо́лнену і во дно а́дово прийти́ бі́дствующу, предвари́, Богоро́дице, моли́тв Твої́х ми́лостію, тишину́ подаю́щи і бід ізима́ющи. Приста́нище бо Ти єси́ небу́рноє, моля́щися Си́ну Твоєму́ і Бо́гу прегріше́ній оставле́ніє дарова́ти мі: Тя бо і́мам наде́жду, недосто́йний раб Твой."]},{"h":"Пісня 4","ps":["Ірмос: Прише́л єси́ от Ді́ви не хода́тай, ні а́нгел, но Сам Го́споди вопло́щся, і спасл єси́ всего́ м'я челові́ка; тім зову́ ті: сла́ва си́лі Твоє́й, Го́споди.","Приспів: Святи́теліє Васи́ліє Вели́кий, Григо́ріє Богосло́ве, Іоа́нне Златоу́сте, молі́те Бо́га о нас.","Разу́мливи от ни́жнія му́дрости би́вше, правле́ніє, пресла́внії, от Боже́ственния стяжа́сте, ті́мже, я́ко раби́ню, сію́ о́ной всему́дре покори́сте.","Любому́дрії, му́дрия а́ще лю́біте, умудрі́теся і глаго́лати научі́теся всі, і́же словесе́м чудя́щіїся, дія́нія опа́сству і виді́нія отту́ду обуча́ющеся.","Богородичен: Я́ко по́зден дождь, напосліди́ би́вий, у́тренній, вод і віко́в Соді́тель, во чре́во Твоє́ ука́нув, Всенепоро́чная, во вре́м'я прохлажда́яй оскудева́ющия."]},{"h":"Пісня 5","ps":["Ірмос: Просвіще́ніє во тьмі лежа́щих, спасе́ніє отча́янних, Христе́ Спа́се мой, к Тебі́ у́тренюю, Царю́ ми́ра, просвіти́ м'я сія́нієм Твої́м, іно́го бо ра́зві Тебе́ Бо́га не зна́ю.","Приспів: Святи́теліє Васи́ліє Вели́кий, Григо́ріє Богосло́ве, Іоа́нне Златоу́сте, молі́те Бо́га о нас.","Ти істо́чник Твої́х дарова́ній іспи́ти весьма́, Человіколю́бче, дал єси́ святи́м, ума́лен ніка́коже істоща́нієм, мир же весь упої́в і́же от чре́ва їх боже́ственними пото́ки.","Приспів: Святи́теліє Васи́ліє Вели́кий, Григо́ріє Богосло́ве, Іоа́нне Златоу́сте, молі́те Бо́га о нас.","Что мі зла́то? Что мі бога́тство, і сла́ва, і могу́тство? Ди́мове, расходя́щіїся по возду́ху: вся да ісче́знуть, вся да прено́сить вітр. Мні бога́тство єди́но многорачи́тельно — учи́телей тро́йця вити́йствующая.","То́чить ріка́ нетлі́нную пи́щу і Боже́ственноє питіє́, то́чить а́лчущим безсме́ртноє бра́шно і жа́ждущим нетлі́нноє питіє́, вода́ жива́ во ві́ки і содержа́щая жи́ви пію́щия: всі многотеку́щия жи́зні наси́тітеся.","Богородичен: Імі́яше крі́пость на ни зло́ба, но не в коне́ць: ізнемо́же бо по Ді́ві, в крі́пості Си́льнаго ро́ждшей, под'є́мшаго плотську́ю не́мощ і си́льнаго в зло́бі умертви́вша."]},{"h":"Пісня 6","ps":["Ірмос: Бе́здна м'я мно́га гріхо́вная окружа́єть, і вопію́ Ті, проро́ка подража́яй: от тлі м'я, Го́споди, возведи́.","Приспів: Святи́теліє Васи́ліє Вели́кий, Григо́ріє Богосло́ве, Іоа́нне Златоу́сте, молі́те Бо́га о нас.","Сво́йства в Тро́йці три сбогосло́віте: нерожде́ніє Отця́, Сло́ва же рожде́ніє і Ду́ха ісхожде́ніє Сама́го.","Приспів: Святи́теліє Васи́ліє Вели́кий, Григо́ріє Богосло́ве, Іоа́нне Златоу́сте, молі́те Бо́га о нас.","Днесь до́му сему́ світоявле́нноє спасе́ніє: два бо і три со́бранния Христо́с, во і́м'я Своє́ почеству́яй, посреді́ прису́тствуєть сих.","Неіспи́танна земна́я глубина́ к небе́сній висоті́, но от землі́ святи́я вознесе́ ви́шше небе́с небе́сноє жела́ніє.","Богородичен: Нов Тя істо́чник, Ді́во, і вину́ та́їн іму́ще, тріє́ богоглаго́льници но́вими предложе́ньми новолі́пноє прили́чествуєть нарече́ніє."]},{"h":"Кондак, глас 2","ps":["Свяще́нния і боговіща́нния пропові́дники, верх учи́телей, Го́споди, прия́л єси́ в наслажде́ніє благи́х Твої́х і упокоє́ніє: труди́ бо о́ніх і смерть прия́л єси́ па́че вся́каго всепло́дія, Єди́не, прославля́яй святи́я Твоя́."]},{"h":"Ікос","ps":["Кто дово́лен своя́ устні́ разве́рзти і подви́гнути язи́ко к ди́шущим огне́м си́лою Сло́ва і Ду́ха? Оба́че толи́ко рещи́ дерзну́: я́ко все прейдо́ша челові́чеськоє єстество́ сі́ї тріє́ мно́гими і вели́кими дарова́ньми, дія́нієм же і виді́нієм, по обоєму́ сві́тли превозше́дше. Ті́мже зіло́ вели́ких даро́в ти́я сподо́бил єси́, я́ко ві́рния Твоя́ служи́телі, Єди́не, прославля́яй святи́я Твоя́."]},{"h":"Пісня 7","ps":["Ірмос: Богопроти́вноє велі́ніє беззако́ннующаго мучи́теля висо́к пла́мень вознесло́ єсть: Христо́с же простре́ Богочести́вим отроко́м ро́су духо́вную, Сий Благослове́н і Препросла́влен.","Приспів: Святи́теліє Васи́ліє Вели́кий, Григо́ріє Богосло́ве, Іоа́нне Златоу́сте, молі́те Бо́га о нас.","Побіжда́ється, блаже́ннії, і отбіга́єть я́же пре́жде непостоя́нная де́рзость єресе́й: воск же, растаява́ємий от лиця́ огня́, любоді́їчноє же вся́коє уче́ніє показу́ється, ва́шим приража́ющеєся огнедохнове́нним віща́нієм.","Лжи́вих у́бо уклони́шася е́ллинських буєсло́вій, увіще́ніє же томи́тельство, є́же в челові́ціх, єди́но ізбра́ша, под ни́мже і́стину сі́ї тріє́ утверди́вше, си́це весь сонм ві́рних побіжда́ють словеси́ і увіщева́ють.","Богородичен: В Тебі́ вся́ко прорече́ніє воспочи́ і коне́ць прия́ше удивля́ющеє глаго́лющия: із Тебе́ же світлі́є і прорече́ній чудеса́ то́чать, Чи́стая, му́дрия явля́юща сказа́телі."]},{"h":"Пісня 8","ps":["Ірмос: В пещ о́гненную ко отроко́м євре́йським снизше́дшаго і пла́мень в ро́су прело́жшаго Бо́га, по́йте діла́ я́ко Го́спода, і превозносі́те во вся ві́ки.","Приспів: Святи́теліє Васи́ліє Вели́кий, Григо́ріє Богосло́ве, Іоа́нне Златоу́сте, молі́те Бо́га о нас.","Разуміва́єм благоче́стно і прославля́єм єдиноче́стно Єди́но Єстество́, безмірномо́щную Єди́ницю же і Тро́йцю, вся сія́ словеси́ пра́в'ящую лу́чшими. Та́ко бо сла́вити тріє́ богоно́снії преда́ша, с ни́миже покланя́ємся Єй во ві́ки.","Соєдини́шася тріє́ богопропові́дници, соєдини́вшії Тро́йцю і Неразді́льноє во всіх соблю́дшії, Боже́ственним єстество́м: єди́ну от Тоя́ восприя́ша неразді́льную сла́ву, в похвале́ніє єди́но созива́ющую превознося́щия Ю во ві́ки.","Богородичен: Приє́м, є́же по нам, возда́в же Своє́ Благоді́тель, соді́я то́кмо, не пострада́ же, Ді́во: твори́ть бо, но не в тлі́ніє устроя́єть, па́че же і стражда́ во́лею, стра́стію стра́сті ріши́ть, я́коже тріє́ отці́ нас тайноуча́ть."]},{"h":"Пісня 9","ps":["Ірмос: Безнача́льна Роди́теля Син, Бог і Госпо́дь, вопло́щся от Ді́ви, нам яви́ся, омраче́нная просвіти́ти, собра́ти расточе́нная, тім Всепі́тую Богоро́дицю, велича́єм.","Приспів: Святи́теліє Васи́ліє Вели́кий, Григо́ріє Богосло́ве, Іоа́нне Златоу́сте, молі́те Бо́га о нас.","Се ва́ше ді́ланіє і па́ства, за ю́же велича́йшія болі́зні претерпі́сте, во єди́но соше́дшеся, ку́пно же три ви соприє́мше, о́бщую і́мать похвалу́ ва́ше сладча́йшеє соєдине́ніє.","Приспів: Святи́теліє Васи́ліє Вели́кий, Григо́ріє Богосло́ве, Іоа́нне Златоу́сте, молі́те Бо́га о нас.","Не обоюдоо́стрий меч благода́ть, но трео́стрий на ра́тников тоя́ предлага́єть: єди́н небокова́нен меч, треми́ кріпостьми́ ізощре́н, при́сно побо́рствуяй по Трисія́нном Єди́ном Божестві́.","Ва́ше жи́тельство на небесі́х бя́ше, пресла́внії, і плоть нося́щих во ві́ки нескве́рну, в ни́хже всесоверше́нні ни́ні живу́ще, су́щим на землі́ нам пребива́ющим ви́шняя молі́те і ми́слити, і ді́яти.","Богородичен: Тісни́ть м'я широта́ Твої́х вели́чий, Влади́чице, подавля́ющи сло́во от ча́стости, і пресла́вно мі случа́ється є́же недоуміва́тися от благомо́щества, ті́мже толи́ко Тя Возвели́чившаго сла́вим."]},{"h":"Світилен","ps":["Три світоза́рния світи́льники, па́че со́лнечних луч от Світонача́льния Тро́йці і Трисо́лнечния Єди́ници, преєсте́ственно смі́шени, богоно́сния восхва́лим отці́.","Слава: Сві́та прия́телища, світолу́чния мо́лнії, Васи́лія ни́ні Вели́каго, Григо́рія Богосло́ва, Златоу́стаго Іоа́нна, да восхва́лим всі.","І нині: Єди́нственноє Божество́, О́тче, Си́не і Ду́ше, мольба́ми Васи́лія, Григо́рія і Іоа́нна і Пречи́стия Богоро́диці да не отлучу́ся Твоєя́ сла́ви."]}],"notes":[]},{"u":"Канон святителю Феодосію, архієпископу Чернігівському","e":"Canon to St Theodosius, Archbishop of Chernihiv","secs":[{"h":"Глас 8. Пісня 1","ps":["Ірмос: Во́ду проше́д, я́ко су́шу, і єги́петськаго зла ізбіжа́в, ізра́їльтянин вопія́ше: Ізба́вителю і Бо́гу на́шему пої́м.","Приспів: Святи́телю о́тче Феодо́сіє, моли́ Бо́га о нас.","Прийми́ хвале́ніє, от уст недосто́йних тебі́ приноси́моє, і возда́ждь те́плими твої́ми моли́твами к Бо́гу чту́щим святу́ю па́м'ять твою́, о́тче наш Феодо́сіє.","Приспів: Святи́телю о́тче Феодо́сіє, моли́ Бо́га о нас.","От ю́ности Го́спода возлюби́л єси́, чистоту́ непоро́чну сохраня́я, от ді́тства Тому́ приліпи́лся єси́ чи́стою твоє́ю душе́ю, в простоті́ і незло́бії се́рдце твоє́ соблюда́я. Ті́мже і ча́до Бо́жиє воі́стину бил єси́, свя́те Феодо́сіє.","Бла́го єсть му́жу, єгда́ во́зьметь яре́м в ю́ності своє́й, глаго́леть Писа́ніє. Сему́ глаго́лу послі́дуя, с ра́достію і́го Госпо́днє от ю́ности восприя́л єси́ і бил єси́ і́нок преізря́дний, блаже́нне Феодо́сіє.","Богородичен: Пресвята́я Ді́во, Ма́ти Бо́жия, Засту́пнице на́ша непости́дная, спаси́, усли́ши нас, страстьми́ лю́ті одержи́мих, і даждь ру́ку по́мощі моли́твами Твої́ми."]},{"h":"Пісня 3","ps":["Ірмос: Небе́снаго кру́га Верхотво́рче, Го́споди, і Це́ркве Зижди́телю, Ти мене́ утверди́ в любві́ Твоє́й, жела́ній кра́ю, ві́рних утвержде́ніє, єди́не Человіколю́бче.","Приспів: Святи́телю о́тче Феодо́сіє, моли́ Бо́га о нас.","Блаже́нні ни́щії ду́хом, глаго́леть Госпо́дь; сему́ спаси́тельному глаго́лу внима́я, па́че всіх доброді́телей нищету́ духо́вную потща́лся єси́ стяжа́ти, преподо́бне, возлюби́в ту́ю, я́ко огра́ду крі́пку от вся́каго іскуше́нія і я́ко боголюбе́зную ма́тер всіх доброді́телей.","Приспів: Святи́телю о́тче Феодо́сіє, моли́ Бо́га о нас.","Позна́в, я́ко от послуша́нія ражда́ється смире́ніє, от смире́нія же безстра́стіє, всім се́рдцем возлюби́л єси́ послуша́ніє, во всем во́лю свою́ і зли́я по́мисли отсіка́я. Ті́мже і безстра́стія дости́гл єси́, угото́вав ду́шу твою́ в чи́стую оби́тель Ду́ха Пресвята́го.","Кро́тость ве́лію стяжа́л єси́, богому́дре Феодо́сіє, вся ско́рбная благоду́шне претерпіва́я, вся́кую оби́ду і уничиже́ніє в молча́нії любо́вію покрива́я. Сего́ ра́ди і прия́л єси́ наслі́діє на землі́ живи́х, іді́же пра́веднії во ві́ки пребива́ють, сла́в'яще Го́спода Ісу́са.","Богородичен: Не і́мами дерзнове́нія к Си́ну і Бо́гу Твоєму́, Пресвята́я Влади́чице, не і́мами дерзнове́нія і к Тебі́, Пренепоро́чная, гріхми́ при́сно оскверня́ємі, а́ще не Сама́ Ти, Премилосе́рдая Ма́ти, воззове́ши нас, заблу́ждших, к покая́нію, наде́ждею спасе́нія отріва́ющи от нас вся́коє уни́ніє і разліне́ніє."]},{"h":"Сідален, глас 4","ps":["Яви́лся єси́ світи́льник благода́тний, о́тче наш Феодо́сіє, ти́хим сві́том смире́нія і любве́ сія́яй і нас любо́вію твоє́ю озаря́яй. Ті́мже і ми, любо́вію чту́ще па́м'ять твою́, вопіє́м ті: моли́ о нас, святи́телю Бо́жий, новоявле́нний чудотво́рче.","Богородичен: Мно́гими прегріше́нії ум помраче́н іму́ще, вопіє́м ко Твоєму́ крі́пкому заступле́нію, Богоро́дице Ді́во: просвіти́ о́чі душ на́ших і возсія́й нам покая́нія зарю́, моли́твами уго́дника твоєго́ святи́теля Феодо́сія, єди́на Чи́стая і Благослове́нная."]},{"h":"Пісня 4","ps":["Ірмос: Ти моя́ крі́пость, Го́споди, Ти моя́ і си́ла, Ти мой Бог, Ти моє́ ра́дованіє, не оста́вль ні́дра О́тча, і на́шу нищету́ посіти́в. Тім с проро́ком Авваку́мом зову́ Ті: си́лі Твоє́й сла́ва, Человіколю́бче.","Приспів: Святи́телю о́тче Феодо́сіє, моли́ Бо́га о нас.","Не́мощію отягче́н і ста́ростію претружде́н бив, архипа́стир Ла́зар пе́рвіє у́бо сослужи́теля, посліди́ же і наслі́дника себі́ устроя́єть тя, святи́телю Феодо́сіє, і це́ркві Черни́говстій світи́льника, ю́же моли́твами твої́ми просвіща́й во вся ві́ки.","Приспів: Святи́телю о́тче Феодо́сіє, моли́ Бо́га о нас.","Воі́стину че́сти і вла́сті святи́тельськия досто́їн яви́лся єси́, о́тче Феодо́сіє, сло́вом прему́др бив, житіє́м же доброді́телен, в Боже́ственних Писа́ніїх іску́сен і слове́сния о́вці наставля́ти зіло́ дово́лен.","Благоче́стієм украша́яся і в духо́внім жи́тельстві всім лю́дем страни́ Черні́говськия ізві́стен бив, єдиноду́шні ті́ми ізбра́н бил єси́ во вели́коє служе́ніє Це́ркві Бо́жієй, о́тче Феодо́сіє, ю́же і ни́ні назира́й твої́ми моли́твами.","Богородичен: Мно́го мо́жеть моли́тва пра́веднаго поспішеству́єма, глаго́леть Іа́ков, брат Госпо́день. Мно́го мо́жеть і моли́тва святи́теля Феодо́сія, споспішеству́єма Твоє́ю Ма́тернею моли́твою, Пресвята́я Влади́чице Богоро́дице: єси́ бо предста́тельство, і покро́в, і заступле́ніє на́ше, Благода́тная."]},{"h":"Пісня 5","ps":["Ірмос: Вску́ю м'я отри́нул єси́ от лиця́ Твоєго́, Сві́те незаходи́мий, і покри́ла м'я єсть чужда́я тьма окая́ннаго? Но обрати́ м'я, і к сві́ту за́повідей Твої́х путі́ моя́ напра́ви, молю́ся.","Приспів: Святи́телю о́тче Феодо́сіє, моли́ Бо́га о нас.","Ра́довахуся лю́діє гра́да Черни́гова, зря́ще тебі́ сві́тлостію са́на святи́тельськаго облече́на, і ку́пно со архипа́стирем Ла́зарем престо́лу благода́ті Бо́жия предстоя́ща, і преподо́бния своя́ ру́ці о па́стві возді́юща, і, Христа́ благодаря́ще, сердці́ свої́ми умиля́хуся.","Приспів: Святи́телю о́тче Феодо́сіє, моли́ Бо́га о нас.","О́браз бил єси́ всей богода́нній па́стві твоє́й, сло́вом і житіє́м, любо́вію і ду́хом, ві́рою і чистото́ю. Сего́ ра́ди не то́чію о́вці твоя́ любо́вію к тебі́ приліпля́хуся, но і іносла́внії тя я́ко челові́ка Бо́жия, о́тче наш Феодо́сіє, почита́ху.","Па́стир воі́стину до́брий слове́сному ста́ду твоєму́, святи́телю Феодо́сіє, бил єси́, ду́шу твою́ за о́вці твоя́ положи́ти гото́вий. Ті́мже і яви́лся єси́ оби́димим у́бо засту́пник непреобори́мий, пра́вди же ревни́тель неустраши́мий, си́льних ми́ра сего́ с любо́вію облича́я і пасо́мих свої́х оте́чеськи вразумля́я, заблу́ждшия же на путь пра́вий прему́дре наставля́я.","Богородичен: Умерщвле́нную ду́шу мою́ оживи́, па́дшую возста́ви, уязвле́нную ісціли́, ум мой просвіти́, іскуше́ній во́лни укроти́, Ма́ти Бо́жия, Ді́во Пресвята́я, і спаси́ м'я моли́твами Твої́ми, Пречи́стая."]},{"h":"Пісня 6","ps":["Ірмос: Моли́тву пролію́ ко Го́споду і Тому́ возвіщу́ печа́лі моя́, я́ко зол душа́ моя́ іспо́лнися і живо́т мой а́ду прибли́жися, і молю́ся, я́ко Іо́на: от тлі, Бо́же, возведи́ м'я.","Приспів: Святи́телю о́тче Феодо́сіє, моли́ Бо́га о нас.","От ю́ности і́нок преізря́дний бив, і́ночеськия оби́телі с любо́вію созида́л єси́ і вся на по́льзу житія́ і́ночеськаго в тіх благоустроя́л єси́, всіх при́сно к Бо́гу наставля́я оте́чеськими твої́ми поуче́ньми, о́тче наш, Феодо́сіє богому́дре.","Приспів: Святи́телю о́тче Феодо́сіє, моли́ Бо́га о нас.","Благолі́пні ду́шу твою́ во храм Ду́ха Бо́жия доброді́тельми устроя́я, благолі́піє до́му Бо́жия возлюби́л єси́ і, всеусе́рдноє попече́ніє о том імі́я, єще́ і хра́ми но́ви созида́л єси́ во сла́ву Творця́ і Бо́га, мир весь несказа́нною красото́ю благоукраси́вшаго.","Ра́достію а́нгельською, святи́телю Бо́жий, ра́довался єси́, єгда́ ча́да твоя́ во і́стині ходя́ща ви́діл єси́, і, я́коже оте́ць чадолюби́вий, се́рдцем твої́м о заблужда́ющихся скорбі́л єси́ і о спасе́нії всіх моли́тву твори́л єси́, вся любо́вію об'є́мля і о всіх предста́тельствуя, о́тче наш, святи́телю Феодо́сіє.","Богородичен: Прийді́те, всі ві́рнії, припаде́м к те́плій Засту́пнице ро́да на́шего, Ма́тері Бо́жієй, і во умиле́нії се́рдця воззове́м: Пресвята́я Влади́чице Богоро́дице, покри́й нас благода́тним покро́вом Твої́м і моли́твами Твої́ми ізба́ви нас от вся́каго зла."]},{"h":"Кондак, глас 4","ps":["Па́стирей Нача́льнику Христу́ труди́лся єси́, святи́телю Феодо́сіє, на па́жити духо́вній слове́сния твоя́ о́вці пита́я, і ціле́бен дар от Христа́ Спа́са прия́л єси́, во є́же не́мощі душе́вния і тіле́сния ціли́ти всіх, с ві́рою к ціле́бним твої́м моще́м приходя́щих. Ті́мже і ни́ні, свя́те, моли́ся всім і́м'я твоє́ призива́ющим от наві́тов вра́жиїх спасти́ся і поми́ловатися душа́м на́шим."]},{"h":"Ікос","ps":["Дар Бо́жий воі́стину яви́лся єси́ землі́ Українській, свя́те Феодо́сіє, от ю́ности бо себе́ Бо́гу возложи́в, по́двигом до́брим до конця́ подвиза́лся єси́ і дарова́нія ве́лія прия́л єси́, благода́ті сосу́д бив ізбра́нний. Ті́мже, я́ко в житії́ твоє́м, та́ко найпа́че по блаже́ннім успе́нії, предстоя́ престо́лу Пресвяти́я Тро́йці, со дерзнове́нієм возді́єши преподо́бния твоя́ ру́ці, о па́стві твоє́й і о Благочести́війшем Імпера́торі на́шем і о всей землі́ Українській те́плі моля́ся. Сего́ ра́ди, с ві́рою і любо́вію к тебі́ притека́юще, всі скорб'я́щії неоску́дно утіше́ніє приє́млють і боля́щії ісціле́ній сподобля́ються. С ни́миже і ми тебі́, я́ко чадолюби́вому отцю́, взива́єм: моли́, свя́те, о призива́ющих і́м'я твоє́, от наві́тов вра́жиїх спасти́ся душа́м на́шим."]},{"h":"Пісня 7","ps":["Ірмос: О́троци євре́йстії в пещі́ попра́ша пла́мень дерзнове́нно і на ро́су огнь преложи́ша, вопію́ще: благослове́н єси́, Го́споди Бо́же, во ві́ки.","Приспів: Святи́телю о́тче Феодо́сіє, моли́ Бо́га о нас.","При́сно поуча́яся па́м'яті сме́ртній, непреста́нно жела́л єси́ крест Госпо́день пред очеси́ твої́ми держа́ти, єго́же воображе́ніє і в путі́ неразлу́чно пред тобо́ю пребива́ше, во є́же всегда́ от се́рдця взива́ти ко Го́споду: благослове́н єси́, Го́споди Бо́же, во ві́ки.","Приспів: Святи́телю о́тче Феодо́сіє, моли́ Бо́га о нас.","І по сме́рті, я́ко жив сий, благода́тію Бо́жиєю с ча́ди твої́ми пребива́єши і по преставле́нії твоє́м па́стир до́брий тім явля́єшися, о́тче Феодо́сіє, в со́нних виді́ніїх неве́дущия во ві́рі наставля́я і всіх вопи́ти науча́я: благослове́н єси́, Го́споди Бо́же, во ві́ки.","В це́рков Бо́жию ходи́ти і моли́тися боля́щему і́ноку повелі́л єси́, о́тче Феодо́сіє, во сні тому́ предста́в, і, оте́чеськи того́ вразумля́я, гріхи́ єго́ воспом'яну́л єси́, к покая́нію призива́я, і ісціле́ніє тому́ по́дал єси́, да ви́ну сла́вить Го́спода: благослове́н єси́, Го́споди Бо́же, во ві́ки.","Богородичен: Разсі́яся ум мой, одебелі́ се́рдце, немоществу́єть моє́ проізволе́ніє. Влади́чице Богоро́дице, умилосе́рдися о мні, грі́шнім, ісціли́ ду́шу мою́ і, я́ко Блага́го Спа́са моєго́ Блага́я Ма́ти, спаси́ м'я, да ви́ну вопію́ Єму́: благослове́н єси́, Го́споди Бо́же, во ві́ки."]},{"h":"Пісня 8","ps":["Ірмос: А́нгели і небеса́, на престо́лі сла́ви сідя́щаго, і я́ко Бо́га непреста́нно сла́вимаго, благослові́те, по́йте, і превозносі́те Єго́ во ві́ки.","Приспів: Святи́телю о́тче Феодо́сіє, моли́ Бо́га о нас.","Кто по достоя́нію мо́жеть пові́дати вся чудеса́ твоя́, святи́телю Феодо́сіє? І неі́щущим тебі́ боля́щим явля́єшися врач преізря́дний, всіх призива́я іспові́дати сла́ву Бо́га, прославля́ющаго святи́я Своя́ і превозноси́маго во ві́ки.","Приспів: Святи́телю о́тче Феодо́сіє, моли́ Бо́га о нас.","Стужа́ємим от духо́в нечи́стих засту́пник і прибі́жище яви́лся єси́, святи́телю Феодо́сіє, прогоня́я си́лою Бо́жиєю вся́коє ді́йство бісо́вськоє от і́же с ві́рою к моще́м твої́м притека́ющих, да сла́виться і́м'я Бо́жиє во ві́ки.","І́м'я твоє́, святи́телю Феодо́сіє, я́ко ми́ро ізлія́нноє, я́коже благоуха́ніє рая́ Бо́жия, по лицю́ всея́ землі́ Українськия обно́ситься, услажда́я сердца́ ві́рующих і призива́я в ра́дості духо́вній воспіва́ти Го́спода, превозноси́маго во вся ві́ки.","Богородичен: Не пре́зри моле́ній раб Твої́х, Ма́ти Бо́жия, прийми́ моли́тви на́ша ра́ди уго́дника Твоєго́, святи́теля Феодо́сія, і принеси́ ко престо́лу Си́на і Бо́га Твоєго́, да сла́виться і́м'я Єго́ от всея́ тва́рі во ві́ки."]},{"h":"Пісня 9","ps":["Ірмос: Тя, неіскусобра́чную Ма́тер Бо́га Ви́шняго, Тя, па́че ума́ ро́ждшую сло́вом воі́стину Бо́га, ви́шшую пречи́стих Сил, немо́лчними славословле́нії велича́єм.","Приспів: Святи́телю о́тче Феодо́сіє, моли́ Бо́га о нас.","Я́ко ціли́тель преми́лостивий, свя́те Феодо́сіє, не то́чію призива́ющим тя боля́щим ми́лостивне вне́млеши, но і при́сних їх послу́шаєши і по ві́рі тіх ско́рий врач боля́щим явля́єшися, всіх ми́луя і утіша́я, на всіх щедро́ти твоя́ преізоби́льні ізлива́я.","Приспів: Святи́телю о́тче Феодо́сіє, моли́ Бо́га о нас.","Воі́стину ди́вна і па́че сло́ва чудеса́ твоя́, Феодо́сіє, о́тче наш, яви́л бо ся єси́ сла́ва Це́ркве Українськия, Правосла́вния ві́ри небе́сний пропові́дник, і́стини же свиді́тель непрело́жний.","Свя́тче Бо́жий, уго́дниче Христо́в, ми́лости неістощи́моє сокро́вище, при́зри на не́мощі моя́, ісціли́ ду́шу мою́, страстьми́ злі обурева́ємую, ісціли́ і ті́ло моє́, не́мощми обложе́нноє, да просла́влю в тебі́ благода́ть і милосе́рдіє Христа́ Бо́га, ди́внаго во святи́х Свої́х.","Богородичен: К Тебі́, Премилосе́рдая Ма́ти, возношу́ моє́ грі́шноє се́рдце, пред Тобо́ю, Благода́тная, поверга́ю не́мощі душі́ і ті́ла моєго́: моли́твами Твої́ми заступи́ і поми́луй м'я."]},{"h":"Світилен","ps":["Не́бо звізда́ми Украси́вий но́вую звізду́ пресві́тлую яви́ тя, святи́телю Феодо́сіє, не́бо церко́вноє украша́ющую і мрак нечести́вих мудрова́ній разгоня́ющую. Ті́мже і на́ша сердця́, гріхо́м омраче́нная, просвіти́ і к покая́нію моли́твами твої́ми, преподо́бне, наста́ви.","Богородичен: Зарю́ пресві́тлую, явля́ющую нам Со́лнце незаходи́моє, ві́ми Тя, Пресвята́я Ді́во Богоро́дице. Сего́ ра́ди мо́лим Тя: я́ко Ма́ти Сві́та су́щи, просвіти́ нас сві́том Си́на Твоєго́, Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Канон святителю Арсенію, єпископу Тверському","e":"Canon to St Arsenius, Bishop of Tver","secs":[{"h":"Глас 2. Пісня 1","ps":["Ірмос: Гряді́те, лю́діє, пої́м піснь Христу́ Бо́гу, разді́льшему мо́ре і наста́вльшему лю́ди, я́же ізведе́ із рабо́ти єги́петськия, я́ко просла́вися.","Приспів: Святи́телю о́тче наш Арсе́ніє, моли́ Бо́га о нас.","Сві́те от Сві́та, Христе́ Бо́же, от Отця́ пре́жде вік рожде́йся і іскони́ Сий со Отце́м і Ду́хом, мрак душі́ моєя́ отгна́в, озари́ ум мой, молю́ся, я́ко да возмогу́ пі́ти Твоєго́ уго́дника, Арсе́нія свяще́ннаго.","Приспів: Святи́телю о́тче наш Арсе́ніє, моли́ Бо́га о нас.","А́ще і челові́к єси́ єстество́м, о́тче, но а́нгельськи на землі́ пожи́л єси́, десна́го путі́ от ю́ности є́мся, цілому́дрія рачи́тель бив, Ду́ха Свята́го честно́є оби́телище, Арсе́ніє свяще́нне, яви́лся єси́.","Му́дрости глави́зну, страх Бо́жий возлюби́в і за́повідем Єго́ при́сно поуча́яся, дре́во насади́ся при ісхо́дищах вод духо́вних, от ни́хже, о́тче, напоя́єм, плод Христу́, Арсе́ніє, прине́слся єси́.","Богородичен: Усли́ша Є́ва прама́ти, Чи́стая: в печа́ліх роди́ши ча́да. Ти же, Ді́во, усли́шала єси́: Госпо́дь с Тобо́ю, ра́дуйся! І ра́дованним гла́сом, Богоневі́сто, печа́ль прама́тере потре́бльши."]},{"h":"Пісня 3","ps":["Ірмос: На ка́мені м'я ві́ри утверди́в, разшири́л єси́ уста́ моя́ на враги́ моя́, возвесели́бося дух мой, внегда́ пі́ти: ність свят, я́коже Бог наш, і ність пра́веден, па́че Тебі́, Го́споди.","Приспів: Святи́телю о́тче наш Арсе́ніє, моли́ Бо́га о нас.","Презрі́в ни́жняя, я́ко попира́єма, і любо́в роди́телей преоби́дів, Христа́ взиска́л єси́, Єго́же любо́вію ду́шу твою́ уязви́л єси́, Того́ люб'я́ і Того́ іща́ красоти́.","Приспів: Святи́телю о́тче наш Арсе́ніє, моли́ Бо́га о нас.","Світи́льник сий, твою́ ду́шу украша́я слеза́ми, ра́но ко Христу́ у́тренюя, руку́ же просте́ртієм в моли́твах, Амали́ка — ті́ло умертви́л єси́ і на го́ру безстра́стія возше́л єси́.","Благоро́дієм висо́к і благоду́шієм ізя́щен, ра́зума му́дростію удивле́н бил єси́, цвіт я́ко прекра́сний, чистото́ю сія́я, і сві́тлим смире́нієм, Арсе́ніє о́тче, украси́лся єси́.","Богородичен: Ма́ти Бо́жия, Пречи́стая, Благослове́нная і Пренепоро́чная, душі́ моєя́ стру́пи ісціли́ і стра́сті плотські́я умертви́, умири́ ум мой, от вся́каго вре́да і вра́жия напа́сти ізми́ м'я, Влади́чице."]},{"h":"Сідален, глас 4","ps":["Вели́кий Христо́в святи́тель да воспоє́ться, столп сві́тлий, просвіща́яй нас чуде́с світлостьми́, богоно́сний о́тче наш Арсе́ніє, па́стирю і учи́телю землі́ на́шея, Христа́ моли́ о ста́ді твоє́м і о всіх, ві́рою і любо́вію чту́щих святу́ю па́м'ять твою́.","Поє́м Тя, Богоневі́сто, Ма́ти Христа́ Бо́га, сла́в'яще рождество́ Твоє́ непостижи́моє, і́мже ізба́вихомся от ле́сти дия́воли і вся́кия біди́, Богоро́дице Влади́чице, і ві́рно вопіє́м: поми́луй ста́до Твоє́, єди́на Всепі́тая."]},{"h":"Пісня 4","ps":["Ірмос: Пою́ Тя, слу́хом бо, Го́споди, усли́шах і ужасо́хся: до мене́ бо і́деши, мене́ іща́, заблу́ждшаго. Тім мно́гоє Твоє́ снизхожде́ніє, є́же на м'я, прославля́ю, Многоми́лостиве.","Приспів: Святи́телю о́тче наш Арсе́ніє, моли́ Бо́га о нас.","Вельми́ украси́л єси́ престо́л твой, святи́телю Арсе́ніє, вели́кими бо чудеси́ преспі́л єси́ і житіє́м сві́тлим, сего́ ра́ди превели́кий Бог наш вельми́ тя просла́ви.","Приспів: Святи́телю о́тче наш Арсе́ніє, моли́ Бо́га о нас.","Ми́лости Пода́теля Го́спода ві́дий, блаже́нне, те́плі Єго́ умоли́л єси́ на ісціле́ніє і спасе́ніє мно́гим, с ві́рою к тебі́ притека́ющим і в по́мощ тя призива́ющим.","Врача́ ізря́дна разли́чно неду́гующим і наставле́ніє всім, прельще́ним злим сові́том, Христо́с тя дарова́, чудотво́рця землі́ на́шей, святи́теля Арсе́нія, ті́мже тя ублажа́єм.","Богородичен: Ісціли́ла єси́ сокруше́ніє, Всенепоро́чная, дре́вняго окая́нства землени́х, поро́ждшая Го́спода і Царя́ Христа́, поне́сшаго неду́ги на́ша за благосе́рдіє неізглаго́ланноє, Ді́во Ма́ти."]},{"h":"Пісня 5","ps":["Ірмос: Просвіще́ніє во тьмі лежа́щих, спасе́ніє отча́янних, Христе́ Спа́се мой, к Тебі́ у́тренюю, Царю́ ми́ра, просвіти́ м'я сія́нієм Твої́м, іно́го бо ра́зві Тебе́ Бо́га не зна́ю.","Приспів: Святи́телю о́тче наш Арсе́ніє, моли́ Бо́га о нас.","Сла́вний па́стир, неістощи́мий істо́чник ісціле́нія, церко́вний столп, ві́рних утвержде́ніє, вели́кий світи́льник многосві́тлий, святи́телю Арсе́ніє.","Приспів: Святи́телю о́тче наш Арсе́ніє, моли́ Бо́га о нас.","Я́ко світоза́рно житіє́, я́ко зіло́ чу́дно, я́ко красни́ тру́дове твої́, я́ко вели́ка благода́ть сви́ше дана́ ті, му́дре, сего́ ра́ди ві́рою почита́єм тя, святи́телю Арсе́ніє.","Пресві́тлая твоя́ па́м'ять простира́ється в ми́рі і просвіща́єть челові́чеськія ду́ші сві́том благода́ті; ю́же соверша́ющих любо́вію, от бід нас ізба́ви, мо́лимся, святи́телю Арсе́ніє.","Богородичен: Се одр Соломо́нов, єго́же обстоя́ть си́льнії, Богодухнове́нних писа́ній ни́ні прориця́нія, на не́мже Христо́с Бог воплоще́нієм почи́л єсть, Благослове́нная і Обра́дованная."]},{"h":"Пісня 6","ps":["Ірмос: В бе́здні гріхо́вній валя́яся, неізслі́дную милосе́рдія Твоєго́ призива́ю бе́здну: от тлі, Бо́же, м'я возведи́.","Приспів: Святи́телю о́тче наш Арсе́ніє, моли́ Бо́га о нас.","Світи́льника тя су́щії во тьмі пре́лести, неле́стно наставля́юща, обрі́тше, к путе́м живота́, богоблаже́нне Арсе́ніє. І ни́ні по сме́рті врачь яви́лся єси́ боля́щим Ду́ха Боже́ственною благода́тію.","Приспів: Святи́телю о́тче наш Арсе́ніє, моли́ Бо́га о нас.","Зако́ном повину́яся Влади́чнім, заблу́ждшия взиска́л єси́ і во огра́ду покая́нія приве́л єси́, я́ко па́стир і́стинен показа́вся ста́ду твоєму́, о́тче святи́телю Арсе́ніє.","Свяще́нія храм, о́тче, Боже́ственнаго Ду́ха ві́рою бив, созда́л єси́ храм Пречи́стия Ма́тере Бо́жия і Єя́ уго́дников, Анто́нія і Феодо́сія, і оби́тель пречу́дну сотвори́л і украси́л єси́, в не́йже ті́ло твоє́ положено́ бисть.","Богородичен: Зако́ни о Тебі́ пресла́вно, Ді́во, обновля́ються: ражда́єши бо без сі́мене Бо́га Спа́са і пребива́єши, ді́вствующи па́ки, — стра́нно чу́до! — тім Тя, Ма́тер Емману́їлеву, благоче́стно іспові́дуєм."]},{"h":"Кондак, глас 8","ps":["Восприє́мши ра́достно честни́я твоя́ мо́щі пречи́стая це́рков, в ню́же че́стно вноси́ми мно́жеством священномона́хов і кня́зі благові́рними, і я́же приє́мши, я́ко сокро́вище многоці́нноє. Ті́мже і ми ни́ні, твоєя́ огра́ди слове́сния о́вці, о́крест ра́ки твоєя́ предстоя́ще, любе́зно вопіє́м ті: не забу́ди чад твої́х, о́тче, ї́хже му́дре собра́л і возлюби́л єси́, я́ко да зове́м ті: ра́дуйся, святи́телю Арсе́ніє, па́стирю і учи́телю наш."]},{"h":"Ікос","ps":["От скве́рних усте́н, от нечи́ста се́рдця, ка́ко ті принесу́ хвале́нія, окая́нний? Ужаса́юся і трепе́щу, но, наді́яся на твой благосе́рдний нрав, о́тче, хвалу́ ті прино́сим, глаго́люще: ра́дуйся, па́стирю наш до́брий, святи́телю Арсе́ніє, упаси́й ста́до Христо́во; ра́дуйся, ди́вний чудотво́рче, притека́ющим к тебі́ с ві́рою неоску́дно ісціле́ніє подава́я; ра́дуйся, це́рквам воздви́женіє і і́ноков люби́телю, си́рим і ни́щим пода́телю; ра́дуйся і ти, богохрани́мий гра́де Тфер, я́ко такова́ імі́ в себі́ пожи́вша святи́теля; ра́дуйся і весели́ся, Бо́жия Ма́тере це́рков, я́ко люби́мий Тобо́ю в тебі́ почи́л єсть богому́дрий Арсе́ній. Но, о богоблаже́нне о́тче! А́ще і ті́лом преше́л єси́ от нас, но ду́хом пребива́я с на́ми, і моли́ся за ни Христу́ і Пречи́стій Єго́ Ма́тері с Єя́ уго́дники, Анто́нієм і Феодо́сієм, і спаса́й пою́щих тя, да зове́м ті: ра́дуйся, святи́телю Арсе́ніє, па́стирю і учи́телю наш."]},{"h":"Пісня 7","ps":["Ірмос: Богопроти́вноє велі́ніє беззако́ннующаго мучи́теля висо́к пла́мень вознесло́ єсть: Христо́с же простре́ Богочести́вим отроко́м ро́су духо́вную, Сий Благослове́н і Препросла́влен.","Приспів: Святи́телю о́тче наш Арсе́ніє, моли́ Бо́га о нас.","Ви́шній Царю́ і Вседержи́телю, моли́твами Твоєго́ уго́дника жизнь умири́ всім, Сло́ве, христия́ном, посо́бствуя на ва́рвари благові́рним, да Тебі́, Христе́, зове́м: благослове́н Бог оте́ць на́ших.","Приспів: Святи́телю о́тче наш Арсе́ніє, моли́ Бо́га о нас.","Престо́лу предстоя́ Бо́жию, святи́телю Христо́в Арсе́ніє, моли́ти прилі́жно не преста́й о нас, твої́х рабі́х, да огня́ ві́чнаго ізба́вимся і вся́каго озлобле́нія, от враг находя́щаго, твої́ми моли́твами.","Ісціле́нія подава́єши всю́ду ві́рою к тебі́ притека́ющим, святи́телю Арсе́ніє. Ті́мже мо́лим тя, твої́ раби́: печа́ль на́шу в ра́дость преложи́ і от вся́кия ізба́ви ско́рби твої́ми моли́твами.","Богородичен: Стра́сті моєго́ се́рдця ісціли́ ми́лостію Твоє́ю, Всепі́тая, ум мой умири́, і ду́шу мою́ просвіти́, і ходи́ти м'я напра́ви на стезю́ спаси́тельную, я́ко да пою́ Тя, Препі́тая."]},{"h":"Пісня 8","ps":["Ірмос: В пещ о́гненную ко отроко́м євре́йським снизше́дшаго і пла́мень в ро́су прело́жшаго Бо́га, по́йте діла́, я́ко Го́спода, і превозносі́те во вся ві́ки.","Приспів: Святи́телю о́тче наш Арсе́ніє, моли́ Бо́га о нас.","Устро́їв твою́ жизнь боголі́пно, святи́телю Арсе́ніє, строї́тель ізря́ден показа́лся єси́ твоє́й оби́телі і сві́тло прия́телище Бо́жиє.","Приспів: Святи́телю о́тче наш Арсе́ніє, моли́ Бо́га о нас.","Чуде́с глубина́ і ісціле́ній ріка́, істо́чник непреста́нен, струя́, ніка́коже оскудіва́єма, твоя́ ра́ка показа́ся, о́тче.","І́же к Бо́гу моли́твами твої́ми те́плими очи́сти нас от вся́кия скве́рни, і скорбе́й, і болі́зней і вся́кия ну́жди, святи́телю Арсе́ніє, ізба́ви.","Богородичен: Пресвята́я Ді́во, Ти м'я спаси́ і не́мощі моє́й бу́ди по́мощ, скорбе́й мно́гих і лю́тих м'я ізба́ви, да Тя сла́влю, єди́ну Богоро́дицю."]},{"h":"Пісня 9","ps":["Ірмос: Безнача́льна Роди́теля Син, Бог і Госпо́дь, вопло́щся от Ді́ви, нам яви́ся, омраче́нная просвіти́ти, собра́ти расточе́нная, тім Всепі́тую Богоро́дицю, велича́єм.","Приспів: Святи́телю о́тче наш Арсе́ніє, моли́ Бо́га о нас.","Чудеса́ бо твоя́ мно́га і ісціле́нія безчи́сленна незави́стно подава́єши с те́плою ві́рою приходя́щим, Арсе́ніє святи́телю, похвала́ землі́ на́шей.","Приспів: Святи́телю о́тче наш Арсе́ніє, моли́ Бо́га о нас.","Поста́ви тебі́ Христо́с Ма́тере Своєя́ це́ркве столпа́ крі́пка і неподви́жима, соблюда́юща і назира́юща град твой неподви́жим і святу́ю оби́тель Свою́.","Святи́телі у́бо і кня́зі благочести́вії, свяще́нници і і́ноці і всі лю́діє, му́жи і жени́, і ста́рці со младе́нці, і всяк во́зраст, і вся́ко состоя́ніє, святи́телю на́шему Арсе́нію сві́тло пра́зднуєм.","Богородичен: Моли́ Твоєго́ Си́на, Госпоже́ Пречи́стая Богоро́дице, ізба́вити м'я в день стра́шнаго осужде́нія, да, ра́дуяся, пі́сньми велича́ю Тя."]},{"h":"Світилен","ps":["Восхва́лим днесь пі́сньми вели́каго па́стиря і учи́теля, Арсе́нія богому́драго: сей бо ізмла́да возлюби́ Христа́ і Пречи́стую Єго́ Ма́тер, с Не́юже ни́ні мо́лить Христа́ Бо́га поми́ловати ду́ші на́ша.","Богородичен: І́же от Бо́га ми́ру по́даним благи́м Ти вина́ била́ єси́, Богоро́дице, но і ни́ні ми́лостива сотвори́ о о́бщем спасе́нії благопремі́ннаго Бо́га."]}],"notes":[]},{"u":"Канон преподобним отцям Києво-Печерським","e":"Canon to the Venerable Fathers of the Kyiv Caves","secs":[{"h":"Глас 8. Пісня 1","ps":["Ірмос: Во́ду проше́д, я́ко су́шу, і єги́петськаго зла ізбіжа́в, ізра́їльтянин вопія́ше: Ізба́вителю і Бо́гу на́шему пої́м.","Приспів: Преподо́бнії отці́ Пече́рстії, молі́те Бо́га о нас.","Мно́гими окруже́нний опечале́ньми, от гріхо́в мої́х напа́дающими мні неща́дно, к вам притека́ю, о Богоно́снії! Движа́ ва́ша моли́тви в по́мощ.","Приспів: Преподо́бнії отці́ Пече́рстії, молі́те Бо́га о нас.","Анто́ніє Богоно́се і Феодо́сіє Богому́дре, в Україні і́ноком первонача́льници і наста́вници, пе́рвую м'я погу́бльша ума́ добро́ту ва́шими к Бо́гу хода́тайстви па́ки удо́бріте, наставля́юще м'я ко покая́нію.","Приспів: Преподо́бнії отці́ Пече́рстії, молі́те Бо́га о нас.","Стефа́не всехва́льне і Ни́коне всече́стне, Христо́ва ста́да би́вший предводи́теле і о́ноє упа́сший Богоуго́дно в неуси́пних стра́жах нощни́х, Бо́га мні ва́шими благоприя́тними моли́твами уми́лостивіте.","Сла́ву ми́ра сего́ і вся кра́сная нівочто́же вміни́вий, всеїзря́дне Варлаа́ме, сла́ви небе́сния прича́стника покажи́ м'я твої́ми моли́твами.","Боже́ственне Влади́мире царю́, Рома́не же с Дави́дом, му́чеников красота́, ча́да су́ще о́наго, со Єле́ною, ва́шею праба́бою, Бо́гу м'я предста́віте.","Богородичен: Твої́ми моли́твами к Своєму́ Си́ну, Богоро́дице, ско́ро спаси́ м'я от лю́тих: Тебі́ бо помо́щницю су́щий в біда́х всі стяжа́хом всегда́."]},{"h":"Пісня 3","ps":["Ірмос: Небе́снаго кру́га Верхотво́рче, Го́споди, і Це́ркве Зижди́телю, Ти мене́ утверди́ в любві́ Твоє́й, жела́ній кра́ю, ві́рних утвержде́ніє, Єди́не Человіколю́бче.","Приспів: Преподо́бнії отці́ Пече́рстії, молі́те Бо́га о нас.","Безме́зднії вра́чеве яви́стеся, ісціле́нія пресла́вно соверша́ющий, Дамія́не і Ага́пите блаже́ннії, ті́мже і аз к вам прихожду́, о святі́ї: ісцілі́те мі я́зви душе́вния і тіле́сния, не́мощну су́щу.","Приспів: Преподо́бнії отці́ Пече́рстії, молі́те Бо́га о нас.","Ониси́форе блаже́нне, предви́дівий вся і предвіща́я я́сні, со Ієремі́єм же Матфе́є, я́ко проро́ци, предви́дяще, біди́, належа́щия ско́ро, м'я ізба́віте моли́твами ва́шими.","Приспів: Преподо́бнії отці́ Пече́рстії, молі́те Бо́га о нас.","Ісаа́кий, премно́гими страда́нії низложи́вий дия́вольськую пре́лесть, Тя, Христе́, мо́лить: ізба́ви нас от того́ іскуше́ній і спаси́, Многоми́лостиве.","Лавре́нтіє, затвори́вий себі́ Го́сподеві і дерзнове́ніє мно́гоє стяжа́вий отту́ду к Нему́, не преста́й моля́ся всегда́, є́же із'я́тися нам от разли́чних страсте́й.","Предварі́те, раби́ Бо́жії, пре́жде да́же не поглоти́ть м'я до конця́ всегуби́тель, ізба́віте вско́рі ду́шу мою́ от лю́тих і мир вожделі́нний да́руйте.","Богородичен: Зол мно́жество смуща́єть м'я отвсю́ду, і беззако́ній пото́ци обурева́ють м'я, потщи́ся, предвари́ і настоя́щия ну́жди ізми́ м'я, Влади́чице, хода́тайством Твої́м."]},{"h":"Сідален, глас 8","ps":["Повелі́нная от Бо́га те́плі ісполня́юще і сові́том Того́ пра́во ше́ствующії, в пусти́нях, і гора́х, і разсі́линах земни́х обита́ша великоду́шнії по́стници, вся́каго лише́ни челові́чеськаго утіше́нія, ті́мже труди́ плодо́в свої́х пожина́юще, ни́ні с Го́сподем ра́дуються.","Богородичен: Безпло́тних Твої́х, Христе́, і Предте́чі Твоєго́, і учени́к, проро́к і му́ченик, преподо́бних і всіх святи́х і Богоро́диці Неіскусому́жния і благи́я Ма́тере Твоєя́ моли́твами умоле́н бив, даждь нам во сві́ті Твоє́м ходи́ти і сподо́би нас улучи́ти Ца́рствіє Твоє́ за милосе́рдіє ми́лости Твоєя́."]},{"h":"Пісня 4","ps":["Ірмос: Усли́шах, Го́споди, смотре́нія Твоєго́ та́їнство, разумі́х діла́ Твоя́ і просла́вих Твоє́ Божество́.","Приспів: Преподо́бнії отці́ Пече́рстії, молі́те Бо́га о нас.","Алі́піє, до́брі соблюди́й о́браз Бо́жий в душі́ твоє́й і зра́ки ізобразу́я святи́х, немощни́я ісціли́вий тро́стію своє́ю, ізобрази́ і во мні доброді́тельния ви́ди, всесла́вне.","Приспів: Преподо́бнії отці́ Пече́рстії, молі́те Бо́га о нас.","Григо́ріє всеблаже́нне, чуде́с благода́ть от Бо́га приє́мий і тезоіме́ніє от діл подо́бних ни́ні предвари́в, удиви́ і на нас твої́ми моли́твами Єго́ благода́ть.","Приспів: Преподо́бнії отці́ Пече́рстії, молі́те Бо́га о нас.","Мойсе́я, чистоти́ храни́теля крі́пкаго, я́ко о́наго прекра́снаго Іо́сифа, дви́жем, Христе́, к Тебі́ в моли́тву: поми́луй нас.","Іоа́нне многострада́льне, і́же смире́нноє ті́ло своє́ стесне́нії неосла́бними порабоще́й і жи́во погреби́йся, жела́я разріши́тися і со Христо́м соєдини́тися, от тлі м'я ізба́ви.","Про́хоре всеблаже́нне, хлі́би су́щими от би́лій і со́лію от пе́пела гла́дом та́ющия препита́вий, умоли́ Христа́ препита́ти і нас, душе́вним гла́дом ісчеза́ющих.","Богородичен: Не оста́ви мене́, к Тебі́ прибіга́ющая в ра́дованіє бісо́м би́ти, Влади́чице, но необори́мая Твоя́ моли́тва да низложи́ть сих сові́тованія."]},{"h":"Пісня 5","ps":["Ірмос: Просвіти́ нас повелі́нії Твої́ми, Го́споди, і ми́шцею Твоє́ю висо́кою Твой мир пода́ждь нам, Человіколю́бче.","Приспів: Преподо́бнії отці́ Пече́рстії, молі́те Бо́га о нас.","Ма́рко, єго́же повелі́нія ме́ртвії послу́шаху, умерщвле́нна м'я паде́нії возста́вив, моли́твами твої́ми спаси́.","Приспів: Преподо́бнії отці́ Пече́рстії, молі́те Бо́га о нас.","Фео́филе треблаже́нне, слез ра́ди очи́стивий славолю́бія оскверне́ніє, і мні моли́ дарова́тися ізбавле́нію.","Приспів: Преподо́бнії отці́ Пече́рстії, молі́те Бо́га о нас.","Всеблаже́нне Іоа́нне, і́же бра́та твоєго́ по преставле́нії подвиже́нієм ті́ла твоєго́ поче́т, і спасл єси́ того́, Творця́ нам ми́лостива сотвори́.","Одушевле́нная би́вше сокро́вища, от сребролюби́ваго мучи́теля, тлі́нна сокро́вища у вас істязу́ющаго, пострада́вшії непови́нне, Небе́сних","Сокро́вищ прича́стника м'я покажі́те, Васи́ліє і Фео́доре всеблаже́ннії.","І́овлю терпі́нію подо́б'яся, многовре́менную болі́знь претерпі́л єси́ усе́рдно і, ни́ні в неболе́зненном сий поко́ї, болі́зней м'я вся́ких ізба́ви, равноа́нгельне Пи́мене.","Богородичен: Виждь на́ша нало́ги, Многоми́лостиве, і сія́ я́ко Бог обле́гчи, приє́м о нас моля́щуюся Ма́тер Твою́, Ю́же Ті во умилостивле́ніє приво́дим."]},{"h":"Пісня 6","ps":["Ірмос: Моли́тву пролію́ ко Го́споду і Тому́ возвіщу́ печа́лі моя́, я́ко зол душа́ моя́ іспо́лнися і живо́т мой а́ду прибли́жися, і молю́ся, я́ко Іо́на: от тлі, Бо́же, возведи́ м'я.","Приспів: Преподо́бнії отці́ Пече́рстії, молі́те Бо́га о нас.","Спиридо́не незло́биве, і́же о́гненную пещ ма́нтією своє́ю угаси́л єси́, я́ко огнь, любо́во вжег в се́рдці твоє́м, о́тче, ко Го́споду, я́же на ни Велія́рова угаси́ стріля́нія, молю́ тя.","Приспів: Преподо́бнії отці́ Пече́рстії, молі́те Бо́га о нас.","Никоди́ме, по́стников сія́ніє, і́же нікогда́же устні́ возбрани́л єси́ воспіва́ти во псалмі́х Влади́ку, не преста́й моля́ся Єму́ прилі́жно ізба́вити вся от тлі, і бід, і скорбе́й, преподо́бне.","Приспів: Преподо́бнії отці́ Пече́рстії, молі́те Бо́га о нас.","Распни́йся умерщвле́нієм пло́ті пе́рвіє, от іуде́й же распни́йся второ́є, крі́пкий Євстра́тіє, і мно́гоє дерзнове́ніє у Христа́ обрі́т, от бід ізба́ви м'я.","Ізба́ви м'я твої́ми моли́твами, Ни́коне сла́вне, і́же ми́шцею Христо́вою висо́кою от пліне́нія ізба́влен, спасл єси́ своєго́ мучи́теля.","Безсме́ртіє обрі́т о Христі́, Безсме́ртнім Царі́ і Бо́зі, Афана́сіє блаже́нне, по сконча́нії своє́м пожи́л єси́ во мно́гих лі́тіх, пла́ча всегда́, ті́мже ни́ні оживи́ м'я.","Богородичен: Пречи́стая, Очище́ніє ро́ждши, Отцю́ Примири́вшаго мир, вім, Чи́стая, я́ко раздражи́х Єго́ безмі́рними мої́ми согріше́нії, но молю́: уми́лостиви мі Того́ па́ки Ма́терніми Твої́ми мольба́ми."]},{"h":"Кондак, глас 8","ps":["Отці́ всечестні́ї, ли́че Богокра́сний, чуде́с мно́гих істо́чници, ми́ро істоча́ющий, сокро́вища краснобога́тная Госпо́дня, в землі́ сокрове́нная не преста́йте, мо́лим ви, о нас моли́тися ко Го́споду, да зове́м вам: ра́дуйтеся, всему́ ми́ру світи́льници."]},{"h":"Ікос","ps":["А́нгельськи пожи́вшия землі́ і А́нгелом равностоя́телі я́вльшіяся на Небесі́, с ті́мижде і неізрече́нния о́ния наслажда́ющийся добро́ти, достоблаже́нния отці́ на́ші, помо́щники і засту́пники те́плия, прийді́те, ві́рнії, восхва́лим, к ним вопію́ще: ра́дуйся, Анто́ніє, со́лнцю подо́бний світи́льниче; ра́дуйся, зерца́ло і о́бразе всім преподо́бним Українським; ра́дуйся, втори́й Мойсе́є, ми́сленний скрижа́ли, доброді́телі твоя́ нам от гори́ святи́я принеси́й. Ра́дуйся, Феодо́сіє, ангелови́дний челові́че; ра́дуйся, звіздо́ у́тренняя, тьму неві́дінія прогоня́ющая; ра́дуйся, забра́ло необори́моє от враг ви́димих і неви́димих. Ра́дуйтеся, всі преподо́бнії отці́ на́ші Пече́рстії; ра́дуйтеся, земні́ї а́нгели і Небе́снії челові́ци; ра́дуйтеся, благоуха́ннії цві́ти ра́йстії; ра́дуйтеся, пребога́тая сокро́вища сокрове́нная в землі́; ра́дуйтеся, би́серіє многоці́ннії, от пеще́ри, а́ки от мо́ря, просія́вший; ра́дуйтеся, на́ша похвало́ і всім прибега́ющим к вам ізба́вители от бід; ра́дуйтеся, всему́ ми́ру світи́льници."]},{"h":"Пісня 7","ps":["Ірмос: От Іуде́ї доше́дше, о́троци во Вавило́ні іногда́ ві́рою Тро́йчеською пла́мень пе́щний попра́ша, пою́ще; отце́в Бо́же, благослове́н єси́.","Приспів: Преподо́бнії отці́ Пече́рстії, молі́те Бо́га о нас.","Нико́лає чу́дне, помо́щниче в ско́рбіх, і́же о самі́м єди́нім сло́ве ісціля́єши стра́сті немощни́х, із'яви́ся ско́ро, і от обдержа́щих м'я скорбе́й ізба́ви, і болі́зні се́рдця моєго́ облегчи́.","Приспів: Преподо́бнії отці́ Пече́рстії, молі́те Бо́га о нас.","Єра́зме му́дре, і́же бога́тство своє́ істощи́л єси́ во благолі́піє хра́ма Бо́жия, твої́ми моли́твами храм м'я покажи́ духо́вний.","Приспів: Преподо́бнії отці́ Пече́рстії, молі́те Бо́га о нас.","Сребролю́бія потопи́вий змі́я слез ту́чами, Аре́фо сла́вне, я́ко імі́я дерзнове́ніє, моли́ся о нас ко Го́споду.","Ти́те блаже́нне, гні́внаго бі́са смире́нієм попра́вий, і Пи́мене, по́стником єдиноревни́телю, ізба́віте м'я от іскуше́ній бісо́вських ва́шими моли́твами.","Анто́ніє му́чениче і тве́рдий Євста́фіє, вку́пі со Іоа́нном горди́ню Олге́рдову до землі́ низложи́вший, умерщвля́ющий м'я стра́сті успі́те.","Богородичен: На моле́ніє моє́ ни́ні умилосе́рдися і ра́дость в печа́лі мі́сто да́руй мі, да пою́ Тя, Влади́чице, і вопію́ Си́ну Твоєму́: благослове́н Бог оте́ць на́ших."]},{"h":"Пісня 8","ps":["Ірмос: Царя́ Небе́снаго, Єго́же пою́ть во́ї А́нгельстії, хвалі́те і превозносі́те во вся ві́ки.","Приспів: Преподо́бнії отці́ Пече́рстії, молі́те Бо́га о нас.","О Ку́кші му́чениче, свяще́нником пра́вило, по́стником і преподо́бним украше́ніє, і́же в про́повіді Єва́нгелія со ученико́м твої́м честни́м коне́ць приє́м, я́ко апо́стол, моли́твами твої́ми і мене́ на путь спасе́нія наста́ви.","Приспів: Преподо́бнії отці́ Пече́рстії, молі́те Бо́га о нас.","Не́сторе Богому́дре, житі́й святи́х спаса́телю пе́рвійший і ревни́телю о́нім до́брий, сла́ви о́ніх моли́твами твої́ми яви́ м'я о́бщника.","Приспів: Преподо́бнії отці́ Пече́рстії, молі́те Бо́га о нас.","Поліка́рпе сла́вне, ті́хже житія́ святи́х коне́чніє ісписа́вий і во єди́но собра́вий, в кни́зі живо́тній твої́ми моли́твами і мні написа́тися сподо́би.","Я́ко жи́ви су́ще, Богоно́снії, і по сме́рті блаже́нному Діони́сію от среди́ гробо́в отвіща́сте: воі́стину воскре́се Госпо́дь! Умерщвле́нна м'я страстьми́ оживі́те.","Євфроси́нію, ра́дованіє По́лотськоє і ді́вам сія́ніє, Христе́ мой, Тебі́ привожду́ моли́твенницю, єя́же ра́ди спаси́ м'я.","Богородичен: Царя́ Небе́снаго ро́ждшая, дерзнове́ніє Ма́тернєє я́ко іму́щи к Нему́, Ді́во, ізба́ви нас от бід."]},{"h":"Пісня 9","ps":["Ірмос: Воі́стину Богоро́дицю, Тя іспові́дуєм, спасе́ннії Тобо́ю, Ді́во Чи́стая, с Безпло́тними ли́ки Тя велича́юще.","Приспів: Преподо́бнії отці́ Пече́рстії, молі́те Бо́га о нас.","Михаї́ле, Іларіо́не, Пе́тре, Алексі́є, Іо́но, Фо́тіє і Киприя́не, Боже́ственнії ієра́рсі, Єфре́ме, Нико́лає, Ники́то, Іса́їє, Ми́но же, Луко́ і Феокти́сте, Бо́га нам уми́лостивіте.","Приспів: Преподо́бнії отці́ Пече́рстії, молі́те Бо́га о нас.","Лео́нтіє, Стефа́не і Ге́рмане, Ни́фонте, Мари́не, Євфи́міє, Лавре́нтіє же, Діоні́сіє і Си́моне, я́ко приє́мшії власть от Бо́га, просі́те і мні оставле́ніє.","Приспів: Преподо́бнії отці́ Пече́рстії, молі́те Бо́га о нас.","Си́моне ієра́рше, і́же А́гнця Бо́жия пе́рвіє принося́й в же́ртву Вседержи́телю, посліди́ же і себі́ сама́го, я́ко а́гня, приведи́й в же́ртву, спаси́ м'я твої́ми моли́твами.","Священному́чеников украше́ніє, Мака́ріє блаже́нне, і́же пре́жде да́же прия́ти престо́л землі́ чу́вственний, на престо́ли ми́сленния препосла́лся єси́, Бо́гу м'я примири́.","Привожду́ Ті, о Всеще́дре, Іуліяні́ю, присносветя́щую свіщу́, єле́єм благода́ті обдержи́мую, єя́же моли́твами от вся́каго зла соблюди́ м'я.","Богородичен: Со святи́ми А́нгели, с Боже́ственними Апо́столи, со сла́вними му́ченики і всі́ми преподо́бними Твоєго́ моли́ Си́на і Бо́га, Богороди́тельнице Пречи́стая, от бід ізба́вити ду́ші на́ша."]}],"notes":[]},{"u":"Канон преподобному Симеону, Новому Богослову","e":"Canon to St Symeon the New Theologian","secs":[{"h":"Глас 4. Пісня 1","ps":["Ірмос: Отве́рзу уста́ моя́, і напо́лняться Ду́ха, і сло́во отри́гну Цари́це Ма́тері, і явлю́ся, сві́тло торжеству́я, і воспою́, ра́дуйся, Тоя́ чудеса́.","Приспів: Преподо́бне о́тче Симео́не, моли́ Бо́га о нас.","Ду́ха орга́н показа́вся, свяще́ннійше Симео́не, і благода́ті гу́сли доброгла́сния, і мене́ соді́лай благода́ті гу́сли, я́ко да твоя́ благода́ті воспою́ в благода́ті.","Приспів: Преподо́бне о́тче Симео́не, моли́ Бо́га о нас.","Ум всесві́тлий Богосло́вія яви́ся, гром Небе́сний днесь огласи́ громогла́сная поуче́нія прему́дрости. Просвіті́теся, всі, і внемлі́те.","Разумі́ти кто мо́жеть твоєго́ Боже́ственнаго ві́дінія, прему́дре, висоту́ неудобовосходи́мую, глубину́ неізсле́диму, неудобозри́мую широту́ і долготу́ вку́пі, єго́же сподо́бился єси́, Богови́днійше?","Богородичен: Оде́ждо нарече́нная ца́рськая вопло́щшагося Бо́га Сло́ва, Пречи́стая, Богоукраше́нную, ю́же погуби́х, оде́жду благода́ті Боже́ственния па́ки мі оді́й хода́тайством Твої́м."]},{"h":"Пісня 3","ps":["Ірмос: Твоя́ пісносло́вці, Богоро́дице, живи́й і незави́стний істо́чниче, лик себі́ совоку́пльшія, духо́вно утверди́, в Боже́ственній Твоє́й сла́ві вінце́в сла́ви сподо́би.","Приспів: Преподо́бне о́тче Симео́не, моли́ Бо́га о нас.","Бил єси́ храм освяще́н Бо́жий, я́коже же́ртву чи́сту, ум Твой імі́я, свя́те, моли́тву — я́ко жертвоприноше́ніє же і я́ко же́ртвенник — пра́війшеє се́рдце твоє́.","Приспів: Преподо́бне о́тче Симео́не, моли́ Бо́га о нас.","Мойсе́я, спребива́юща Бо́гу, я́коже дре́вле просла́вися лице́, та́ко, о́тче, і твоє́ лице́, в непристу́пних пребива́ющу ті, Боже́ственним Сві́том просла́вися, всесві́тлоє, я́коже со́лнце.","Яви́ся во времена́ послі́дняя кни́га твоя́, о́тче Симео́не, лі́ствиця, нас возводя́щая от землі́ к Небе́сним, і звон свяще́ннійший, спя́щих возставля́ющий.","Богородичен: Я́коже мир, в ми́рі яви́лася єси́ в ма́лом, Превелича́йшая Ді́во, от не су́щих бо вся́чеськая в ми́рі Созда́вий, ми́ру Невмести́м, Тебі́ весь вмести́м бисть."]},{"h":"Сідален, глас 4","ps":["Мона́шествующих пра́вило і украси́тель, по́стников наста́вник і общежи́тельних детоводи́тель і всіх наслажде́ніє показа́лся єси́, свяще́ннійше Симео́не Богосло́ве, ті́мже і ни́ні моли́ся со дерзнове́нієм Зижди́телю о нас, ві́рою і любо́вію чту́щих па́м'ять твою́, преподо́бне.","Сла́ва: От Богоно́сних єди́н і і́стинен явля́йся, от богосло́вов же тре́тій сий і от преподо́бних єди́н і ве́лій ти бисть ме́рностію, любо́вію соверше́нною, Симео́не Богому́дре, і чистото́ю вся́чеською, і си́ми вся́чеськими доброді́тельми, і́миже возви́сился єси́ ко Го́споду, преподо́бне.","Богородичен: Не умолчи́м нікогда́, Богоро́дице, си́ли Твоя́ глаго́лати, недосто́йнії, а́ще бо Ти не би предстоя́ла моля́щи, кто би нас ізба́вил от толи́ких бід, кто же би сохрани́л дони́ні свобо́дні? Не отсту́пим, Влади́чице, от Тебе́, Твоя́ бо раби́ спаса́єши при́сно от вся́ких лю́тих."]},{"h":"Пісня 4","ps":["Ірмос: Неізслі́дний Бо́жий сові́т, є́же от Ді́ви воплоще́нія Тебі́, Ви́шняго, проро́к Авваку́м усмотря́я, зов'я́ше: сла́ва си́лі Твоє́й, Го́споди.","Приспів: Преподо́бне о́тче Симео́не, моли́ Бо́га о нас.","Зако́ном Влади́ки повину́яся, му́дре, за́повіді вся іспо́лнил єси́, в ни́хже обрі́л єси́ сокри́та Христа́, сія́ запове́давша, і Єго́ благода́тію обогати́лся єси́.","Приспів: Преподо́бне о́тче Симео́не, моли́ Бо́га о нас.","Язи́к, вити́йствующий ри́торськими хи́тростьми і смишле́ньми, не мо́жеть просла́вити дарова́нія твоя́, я́же па́че єстества́ прия́л єси́, о́тче Симео́не Богопросла́вленне.","Обрі́л єси́ неудо́б обріта́ємоє дре́вле і ни́ні бога́тство, Симео́не Богопросла́вленне, є́же обожи́тися і восхи́титися уму́ твоєму́ от землі́ к Небе́сним. О, стра́ннаго сли́шанія!","Богородичен: Словесе́м Твої́м послі́дующе, Пречи́стая, всі ро́ди, ублажа́єм Тя, я́ко ро́ждшую Блаже́ннаго Бо́га, блаже́нни показа́вшаго уми́ і челові́ки Боже́ственною благода́тію."]},{"h":"Пісня 5","ps":["Ірмос: Ужасо́шася вся́чеськая о Боже́ственній сла́ві Твоє́й, Ти бо, Неіскусобра́чная Ді́во, імі́ла єси́ во утро́бі над всі́ми Бо́га і родила́ єси́ безлі́тнаго Си́на, всім воспіва́ющим Тя мир подава́ющая.","Приспів: Преподо́бне о́тче Симео́не, моли́ Бо́га о нас.","Любве́ горя́ огне́м в се́рдці твоє́м, весь во ізступле́нії бил єси́ і Бо́гу єди́ному всему́, возлю́бленному от тебе́, сраствори́лся єси́, я́коже єди́н дух би́ти с Ним, свяще́ннійше.","Приспів: Преподо́бне о́тче Симео́не, моли́ Бо́га о нас.","Се ни́ні возсія́ Світ Боже́ственния благода́ті! Се безсме́ртіє ма́нни живо́тния всім предлага́ється Симео́н, Боже́ственний оте́ць! Прийді́те і насладі́теся, живота́ жа́ждущії.","Ри́торов красні́йшій показа́вся ду́хом, я́же о Бо́зі і Боже́ственнім словеса́ боголе́пнейше богосло́вствовал єси́ нам, ті́мже но́вий нарече́ся Богосло́в, тезоімені́те.","Богородичен: О Ма́ти всесві́тлая Сві́та Пе́рваго, просвіти́ ду́шу несві́тлую сві́том Твої́м, я́ко да Світ ви́жду па́ки Пе́рвійший, І́же із Тебе́ озари́ нас і Тя просвети́вший, Сей бо от Сві́та то́йжде."]},{"h":"Пісня 6","ps":["Ірмос: Боже́ственноє сіє́ і всечестно́є соверша́юще пра́зднество, Богому́дрії, Богома́тере, прийді́те, рука́ми воспле́щим, от Нея́ ро́ждшагося Бо́га сла́вим.","Приспів: Преподо́бне о́тче Симео́не, моли́ Бо́га о нас.","Реку́ приснотеку́щую Боже́ственния благода́ті, от ми́сленнаго Еде́ма істека́ющую, прийді́те, в пі́сніх почти́м і живота́ струя́ми єя́ наслади́мся.","Приспів: Преподо́бне о́тче Симео́не, моли́ Бо́га о нас.","Покая́нія учи́тель, пропові́дник просвіще́нія благода́ті, свяще́ннійший ни́ні Симео́н ублажа́ється, пожи́вший в ми́рі сем житіє́м равноа́нгельським.","Побіди́в крі́постію Ду́ха, і труди́ воздержа́нія, і слеза́ми, Симео́не преподо́бне, стра́сті душе́вния же і тіле́сния, к безстра́стію кра́йнему дости́гл єси́.","Богородичен: Бо́га безсі́менно зачала́ єси́, Ді́во, і нетру́дно носи́ла єси́ во утро́бі Твоє́й, нетлі́нно же Сего́ родила́ єси́. О, трегу́баго чудеса́! Кто не ужасне́ться!"]},{"h":"Кондак, глас 3","ps":["Сві́том просвіще́н Трисо́лнечним, Богому́дре, Богосло́в яви́лся єси́ Пребоже́ственния Тро́йці. Сви́ше прему́дростію слове́с обогати́вся, істочи́л єси́ Богому́дрія Боже́ственния струї́, от ни́хже пію́ще, вопіє́м: ра́дуйся, треблаже́нне Симео́не Богонауче́нне."]},{"h":"Ікос","ps":["Пресвяти́й Дух, І́же пре́жде ри́бари некни́жния умудри́ і ри́тори і Богосло́ви їх показа́, Той і в послі́дняя времена́, в чи́стій твоє́й душе́ всели́вся, Симео́не святі́йший, ри́тора ри́торов і Богосло́ва тя прему́дра із некни́жнаго і нему́драго соді́ла, добропи́шуща і ди́вно ізлага́юща догма́ти пресуще́ственнаго Богосло́вія і та́їнства Боже́ственнаго Сві́та і я́же в душі́ та́йно бива́ющая разли́чная ді́йства Боже́ственния благода́ті Свята́го Ду́ха, ї́хже і ми чте́нія наслажда́ющеся, тя ублажа́єм, достоблаже́ннейше о́тче, я́ко преєсте́ственна і Небе́сна челові́ка, і, святи́й пра́здник твой любо́вію соверша́юще, согла́сно вопіє́м: ра́дуйся, треблаже́нне Симео́не преподо́бне."]},{"h":"Пісня 7","ps":["Ірмос: Не послужи́ша тва́рі Богому́дрії па́че Созда́вшаго, но, о́гненноє преще́ніє му́жеськи попра́вше, ра́довахуся, пою́ще: препі́тий отце́в Госпо́дь і Бог, благослове́н єси́.","Приспів: Преподо́бне о́тче Симео́не, моли́ Бо́га о нас.","Ізлія́ся благода́ть во устні́ твої́ бога́тая сви́ше, о свяще́нні Симео́не, і полнота́ се́рдця даде́ся ті, я́ко песо́к морськи́й, от тя Умудри́вшаго, я́коже іногда́ Соломо́ну.","Приспів: Преподо́бне о́тче Симео́не, моли́ Бо́га о нас.","Многосві́тлоє і всезлато́є благода́ті і сія́нноє со́лнце Це́ркве Христо́ви, честну́ю проходя́щеє всю твердь і тре́звости сія́ющеє блиста́ньми, Симео́н да похва́литься!","Слове́снійший слове́сних, Богонауче́нний і духоно́сний, ти Богосло́в Христо́в показа́лся єси́ конце́м землі́, Симео́не преподо́бне, напе́рсний втори́й і Григо́рій, огнедухнове́нний Богосло́в.","Богородичен: Огнеобра́зний престо́ле і пла́меннейшеє Христа́ Всецаря́ висо́коє не́бо, от вся́кия стра́сти ни́зменния м'я свобода́ і бре́ннаго обстоя́нія, Присноді́во Марі́є!"]},{"h":"Пісня 8","ps":["Ірмос: О́троки благочести́вий в пещі́ Рождество́ Богоро́дичо спасло́ єсть, тогда́ у́бо образу́ємоє, ни́ні же ді́йствуємоє, вселе́нную всю воздвиза́єть пі́ти Тебі́: Го́спода по́йте, діла́, і превозносі́те Єго́ во вся ві́ки.","Приспів: Преподо́бне о́тче Симео́не, моли́ Бо́га о нас.","Яви́лся єси́ ми́сленний, всеблаже́нне, рай, во Єде́мі Богонасажде́нний, імі́я посреді́ тебі́, я́ко дре́во жи́зні, цвіту́щеє сладкопло́дноє, Христа́ прозя́бшаго, преподо́бне, о́крест же, я́ко древеса́, крася́щаяся плода́ми же і листа́ми, — доброді́телі вся́чеськия.","Приспів: Преподо́бне о́тче Симео́не, моли́ Бо́га о нас.","Уподо́бился єси́ купцю́, о не́мже рече́ Христо́с, Симео́не преподо́бне, ти бо, я́же стяжа́л єси́, вся прода́л єси́ і би́сер прия́л єси́ многоці́нний, єго́же сокри́л єси́ внутр се́рдця, і возвесели́лся єси́ о сем неізрече́нно.","Но́воє не́бо узрі́ся, о́тче, Го́спода, я́коже со́лнце превели́коє, сві́тлоє і златоза́рнейшеє імі́я в пе́рсіх твої́х, і, я́коже луну́ всесві́тлую, среброблиста́ющую, благода́ть Ду́ха стяжа́в, і, я́коже сві́тлия зві́зди, честна́я списа́нія твоя́.","Богородичен: Свята́го Святи́х я́ко ро́ждши, во святи́х при́сно Почива́юща, і я́ко єди́на воздви́гшая побі́ду на враги́ неви́димия, Пречи́стая, ум соблю́дшая па́че сми́сла неразу́мнаго, нариця́єшися от всіх пра́ведно Пресвята́я."]},{"h":"Пісня 9","ps":["Ірмос: Всяк земноро́дний да взигра́ється, Ду́хом просвіща́єм, да торжеству́єть же Безпло́тних умо́в єстество́, почита́ющеє свяще́нноє торжество́ Богома́тере, і да вопіє́ть: ра́дуйся, Всеблаже́нная Богоро́дице, Чи́стая Присноді́во.","Приспів: Преподо́бне о́тче Симео́не, моли́ Бо́га о нас.","Ра́дуйся ни́ні ра́достію воі́стину безконе́чною і неізрече́нною, Симео́не треблаже́нне, іді́же селе́ніє ра́дости благода́тноє, пла́кася бо зді вре́менні, на Небесі́х уте́шился єси́ і весели́шися ві́чно ра́достним і блаже́нним весе́лієм.","Приспів: Преподо́бне о́тче Симео́не, моли́ Бо́га о нас.","Зри́ши сла́дкаго Ісу́са лице́м к лицю́, Єго́же пре́жде зрі́ти сподо́бился єси́, но зерца́лом в гада́нії. Наслажда́йся у́бо, свя́те, взигра́й і лику́й, приобща́яся ни́ні Возлю́бленнаго тобо́ю, і нас, почита́ющих тя, помина́й.","Прийми́ піснь сію́, ю́же прино́сим, Симео́не преподо́бне, я́ко ме́ньшій дар мно́гаго до́лга, єго́же к тебі́ і́мами, і награ́ду про́сим дарова́ти, Ду́ха благода́ть, і нам, моли́твами твої́ми, ю́же зло́бою мно́гою отврати́хом от себе́.","Богородичен: Творе́нія і Созда́теля Посре́дниця несре́дственне пребила́ єси́, Чи́стая, ті́мже і полноту́ всіх благода́тей приє́млеши, Всенепоро́чная, і подає́ши всім челові́ком же і А́нгелом, отону́дуже пода́ждь сію́ і нам, Влади́чице, непотре́бним рабо́м Твої́м."]},{"h":"Світилен, глас 2","ps":["Богосло́ва всі Симео́на благопохва́лим, мона́шествующих удобре́ніє і свяще́нников сла́ву, Богосло́вов похвалу́ і ві́рних украше́ніє, благода́ті трубу́ і Це́ркве Христо́ви живоно́сноє світи́ло.","Слава: Чу́вственноє у́бо со́лнце, зау́тро восходя́ще, просвіща́єть мир весь, дости́гше же за́пада, оба́че своя́ скрива́єть лучи́. Ти же, преподо́бне о́тче, со́лнце яви́лся єси́ незаходи́моє, в нощі́ і во дні свяще́нними словеси́ твої́ми просвіща́я весь мир, ті́мже со́лнця бил єси́ чу́вственнаго вельми́ лу́чшій.","Богородичен: По Бо́зі, Пренепоро́чная, Ти Бог показа́лася єси́, Втори́чная іму́щи Святи́я Тро́йці, ві́ри нача́ло пе́рвоє і наде́жди основа́ніє, утвержде́ніє дія́нія і олта́р Богозрі́нія, краєстро́чіє проро́ков всіх і Писа́ній скрижа́ль, небесе́ і землі́ зна́меніє і стихи́я ми́ра."]}],"notes":[]},{"u":"Канон преподобному Макарію, ігумену Калязинському","e":"Canon to St Macarius, Abbot of Kalyazin","secs":[{"h":"Глас 8. Пісня 1","ps":["Ірмос: Во́ду проше́д, я́ко су́шу, і єги́петськаго зла ізбіжа́в, ізра́їльтянин вопія́ше: Ізба́вителю і Бо́гу на́шему пої́м.","Приспів: Преподо́бне о́тче Мака́ріє, моли́ Бо́га о нас.","Отве́рзи мі, Христе́, устні́ воспі́ти по́двиги уго́дника Твоєго́, преподо́бнаго Мака́рія, да моли́твами свої́ми о́блак разори́ть неві́дінія моєго́.","Приспів: Преподо́бне о́тче Мака́ріє, моли́ Бо́га о нас.","Блаже́нноє житіє́ на землі́ пожи́в, преподо́бне, Небе́сноє наслажде́ніє дости́гл єси́ і ни́ні со А́нгели лику́єши.","Слава: Па́м'ять твоя́, Мака́ріє преподо́бне, я́ко пресві́тлоє со́лнце, возсія́, в ню́же нам іспроси́ от Бо́га благода́ть і ми́лость і согріше́ній ізбавле́ніє.","І нині: Благослове́н Плод, Пречи́стая, чре́ва Твоєго́, І́мже земні́ї всі кля́тви ізба́вихомся, Благослове́нная Всечи́стая, несказа́нноє чу́до, неві́домоє сли́шаніє, всіх же ві́рних спасе́ніє."]},{"h":"Пісня 3","ps":["Ірмос: Ти єси́ утвержде́ніє притека́ющих к Тебі́, Го́споди, Ти єси́ Світ омраче́нних, і поє́ть Тя дух мой.","Приспів: Преподо́бне о́тче Мака́ріє, моли́ Бо́га о нас.","Крі́пкою твоє́ю моли́твою, о́тче, возше́л єси́ к преми́рному наслажде́нію і от честни́я ра́ки чуде́с сія́нія іспуща́єши, Мака́ріє.","Приспів: Преподо́бне о́тче Мака́ріє, моли́ Бо́га о нас.","В Боже́ственній па́м'яті твоє́й днесь соше́дшеся, воспіва́єм твоя́ по́двиги, і болі́зні, і ісправле́нія, о́тче преподо́бне.","Слава: Чу́дно житіє́ твоє́ яви́ся, преподо́бне, благода́тію Боже́ственнаго Ду́ха обложе́н, блаже́нную кончи́ну прия́л єси́, о́тче, ра́дуяся.","І нині: От ложе́сн Твої́х, Пречи́стая, пра́вди Со́лнце возсія́ і мир просвіти́, Єго́же Боже́ственними заря́ми і мене́ просвіти́."]},{"h":"Сідален, глас 8","ps":["Храни́тель сий Боже́ственних повелі́ній Влади́ки, сла́вне, чи́стоє житіє́ твоє́ показа́ тя священноді́теля Боже́ственна, ка́плями по́тов твої́х пре́лести лю́тоє у́гліє погаси́л єси́ і в ти́хоє приста́нище дости́гл єси́, зри́ши, блаже́нне, Єго́же возжелі́л єси́. Ті́мже вопіє́м ті: моли́ Христа́ Бо́га гріхо́в оставле́ніє пода́ти чту́щим любо́вію святу́ю па́м'ять твою́.","Я́ко Ді́ву і єди́ну в жена́х, Тя, без сі́мене ро́ждшую Бо́га пло́тію, всі ублажа́єм, ро́ди челові́честії, Огнь бо всели́ся в Тя Божества́, і я́ко Младе́нця доі́ши Зижди́теля і Го́спода. Тім, А́нгельський і челові́чеський род, досто́йно сла́вим пресвято́є Рождество́ Твоє́ і согла́сно вопіє́м Ті: моли́ Христа́ Бо́га согріше́ній оставле́ніє дарова́ти покланя́ющимся ві́рою пресвято́му Рождеству́ Твоєму́."]},{"h":"Пісня 4","ps":["Ірмос: Усли́шах, Го́споди, смотре́нія Твоєго́ та́їнство, разумі́х діла́ Твоя́ і просла́вих Твоє́ Божество́.","Приспів: Преподо́бне о́тче Мака́ріє, моли́ Бо́га о нас.","В простоті́ душі́, я́ко А́нгел, пожи́в, блаже́нне, страсте́й разгна́л єси́ душетлі́нную пре́лесть Боже́ственною благода́тію.","Приспів: Преподо́бне о́тче Мака́ріє, моли́ Бо́га о нас.","Че́стен сосу́д яви́лся єси́ Боже́ственнаго Ду́ха, нося́ в се́рдці твоє́м, блаже́нне, Боже́ственния арома́ти, услажда́я сердца́ ві́рно па́м'ять твою́ почита́ющих.","Слава: Пресві́тлим вінце́м обложе́н, предстої́ши Престо́лу всіх Царя́: моли́ся, преблаже́нне, о ві́рою пра́зднующих Боже́ственную па́м'ять твою́.","І нині: Зако́ни в Тебі́ іспраздни́шася єстества́, па́че єстества́ бо Сло́во родила́ єси́. Ті́мже Тя ві́рою молю́: па́че єстества́ челові́ча, Всенепоро́чная, мно́го согрі́шша і Бо́га уда́льшася, обра́щшася, спаси́ м'я моли́твами Твої́ми."]},{"h":"Пісня 5","ps":["Ірмос: У́тренююще, вопіє́м Ті: Го́споди, спаси́ ни, Ти бо єси́ Бог наш, ра́зві Тебе́, іно́го не ві́ми.","Приспів: Преподо́бне о́тче Мака́ріє, моли́ Бо́га о нас.","Єгда́ благода́тію Ду́ха смире́нную стяжа́л єси́ му́дрость, ражда́ющему смерть врагу́ глубоку́ я́зву дал єси́ і високоу́мний того́ нрав до конця́ низложи́л єси́.","Приспів: Преподо́бне о́тче Мака́ріє, моли́ Бо́га о нас.","Возше́д ко оби́телем ві́чним, ли́ку преподо́бних причта́лся єси́, Мака́ріє, с ни́миже нас помина́й, на землі́ тебі́ помина́ющих.","Слава: Да ублажи́ться досто́йно Мака́рій: поще́нієм бо, і моли́твами, і слеза́ми Бо́гу соєдини́ся і вся просвіща́єть духо́вною благода́тію.","І нині: О Ма́ти Ді́во Отрокови́це, я́же необиме́ннаго Бо́га пло́тію ро́ждшая, А́нгелов сла́ва і де́монов я́зва, Богоневі́сто, моє́ се́рдце, уязви́вшеєся гріхо́м, цільби́ Боже́ственния сподо́би."]},{"h":"Пісня 6","ps":["Ірмос: Моли́тву пролію́ ко Го́споду і Тому́ возвіщу́ печа́лі моя́, я́ко зол душа́ моя́ іспо́лнися і живо́т мой а́ду прибли́жися, і молю́ся, я́ко Іо́на: от тлі, Бо́же, возведи́ м'я.","Приспів: Преподо́бне о́тче Мака́ріє, моли́ Бо́га о нас.","На землі́ до́брі пожи́л єси́, преподо́бне, і святи́х сві́тлости, і ві́чних наслажде́ній блаже́нства ви́діти сподо́бился єси́.","Приспів: Преподо́бне о́тче Мака́ріє, моли́ Бо́га о нас.","Честна́ смерть яви́ся блаже́ннаго Мака́рія пред Тобо́ю, Бо́же вся́чеських, єго́же па́м'ять почита́ющим врачевство́ безме́здно яви́л єси́.","Слава: Ду́ха благода́ть прия́л єси́, о́тче, неду́ги от челові́к прогоня́ти і вред де́монський істребля́ти, вели́кий уго́дник показа́вся Христа́ Бо́га на́шего.","І нині: На́йде на Тя Вседі́тельний Дух, Всенепоро́чная, і Сло́во Бо́жиє в Тя всели́ся, і плоть бисть несказа́нно, преби́в неізмі́нен."]},{"h":"Кондак, глас 2","ps":["Ви́шніх жела́я, воздержа́нієм, і труди́, і по́ти наслади́вся, жела́ніє пло́ті твоєя́ обузда́в, чуде́с дар приє́м от Христа́ Бо́га, світи́льник яви́лся єси́ пресві́тлий. Ті́мже Христо́ва Це́рков пі́сньми сла́вить тя, преподо́бне Мака́ріє, о́тче наш."]},{"h":"Ікос","ps":["А́нгел земни́й і челові́к Небе́сний, просія́л єси́ во воздержа́нії вся́цім моли́твою, і посто́м, і чистото́ю і, Боже́ственноє тече́ніє сконча́в, Ви́шняго нетлі́нія прича́стник бил єси́, Богоно́се, дерзнове́ніє стяжа́в к Человіколю́бцю Бо́гу, І́же ісціле́ній благода́ть на неду́ги разли́чния тебі́ дарова́. Ті́мже ті ві́рою вопіє́м: ра́дуйся, всеблаже́нне о́тче, по́стников похвало́; ра́дуйся цілому́дрія сто́лпе, і́мже де́монськия шата́нія іскорени́шася; ра́дуйся, світи́льниче многосві́тлий, і́же чуде́с сія́нії вселе́нную просвіща́єши; ра́дуйся, я́ко ста́ду твоєму́ подава́єши по́мощ і заступле́ніє; ра́дуйся, крестоно́сному наро́ду на́шему похвала́ і утвержде́ніє, єго́же соблюди́ моли́твами твої́ми от враг ненаві́тна, да всі вопіє́м ті: ра́дуйся, преподо́бне Мака́ріє, о́тче наш."]},{"h":"Пісня 7","ps":["Ірмос: Бо́жия снизхожде́нія огнь устиді́ся во Вавило́ні іногда́. Сего́ ра́ди о́троци в пещі́, ра́дованною ного́ю, я́ко во цві́тниці, лику́юще, поя́ху: благослове́н єси́, Бо́же оте́ць на́ших.","Приспів: Преподо́бне о́тче Мака́ріє, моли́ Бо́га о нас.","К Сві́ту Незаходи́мому возше́д і, я́ко со́лнце, просвіща́єши вселе́нную, Сві́та бо діла́ соверши́л єси́, Мака́ріє преподо́бне, і ни́ні вопіє́ши: оте́ць на́ших Бо́же, благослове́н єси́.","Приспів: Преподо́бне о́тче Мака́ріє, моли́ Бо́га о нас.","Плотська́я движе́нія, преподо́бне, воздержа́нієм і на землі́ лега́нієм умертви́л єси́ і доброді́телей просвіще́нієм просія́л єси́, вопія́ Христу́: оте́ць на́ших Бо́же, благослове́н єси́.","Слава: Чу́дно житіє́ твоє́, преподо́бне, яви́ся, благода́тію Боже́ственнаго Ду́ха обложе́н, блаже́нную кончи́ну прия́л єси́, о Христі́ ра́дуяся, к Нему́же і взива́л єси́: оте́ць на́ших Бо́же, благослове́н єси́.","І нині: Ни́ні вся іспо́лнишася Сві́та Боже́ственнаго Тобо́ю, Пречи́стая, Ти бо двер яви́лася єси́, є́юже ми́ру Бог приї́де, просвіща́я ві́рою зову́щия: оте́ць на́ших Бо́же, благослове́н єси́."]},{"h":"Пісня 8","ps":["Ірмос: Седьмери́цею пещ халде́йський мучи́тель Богочесті́вим неі́стовно разжже́, си́лою же лу́чшею спасе́ни, сія́ ви́дів, Творцю́ і Ізба́вителю вопія́ше: о́троци, благослові́те, свяще́нници, воспо́йте, лю́діє, превозносі́те во вся ві́ки.","Приспів: Преподо́бне о́тче Мака́ріє, моли́ Бо́га о нас.","Боже́ственними добро́тами наслажда́яся, чуде́с сія́нії вся просвіща́єши і де́монськую тьму разоря́єши Бо́жиєю благода́тію, поя́: о́троци, благослові́те, свяще́нници, воспо́йте, лю́діє, превозносі́те во вся ві́ки.","Приспів: Преподо́бне о́тче Мака́ріє, моли́ Бо́га о нас.","Блиста́яся благода́тію Боже́ственнаго Ду́ха, преподо́бне Мака́ріє, честно́є твоє́ творя́щим успе́ніє сві́тлими твої́ми моли́твами іспроси́ гріхо́в отпуще́ніє, пою́щим: о́троци, благослові́те, свяще́нници, воспо́йте, лю́діє, превозносі́те во вся ві́ки.","Слава: Заря́ми тве́рдих по́двиг твої́х, я́ко со́лнце, возсія́л єси́: врачева́нія істоча́єши і вся́ку болі́знь облегча́єши Христу́ вопію́щим: о́троци, благослові́те, свяще́нници, воспо́йте, лю́діє, превозносі́те во вся ві́ки.","І нині: Я́ко разбо́йник, взива́ю ті: пом'яни́ м'я, Человіколю́бче. Пла́чу, я́ко блудни́ця, і вопію́: согріши́х, я́ко дре́вле блу́дний, ка́ющася прийми́ м'я, отча́яннаго, Богоро́диці ра́ди, да усе́рдно вопію́: свяще́ннії, воспо́йте, лю́діє, і превозносі́те Христа́ во ві́ки."]},{"h":"Пісня 9","ps":["Ірмос: Ужасе́ся о сем Не́бо, і землі́ удиви́шася конці́, я́ко Бог яви́ся челові́ком пло́тськи і чре́во Твоє́ бисть простра́ннійшеє Небе́с. Тім Тя, Богоро́дицю, А́нгелов і челові́к чинонача́лія велича́ють.","Приспів: Преподо́бне о́тче Мака́ріє, моли́ Бо́га о нас.","Ра́ка, іді́же лежи́ть честно́є ті́ло твоє́, істо́чник содіва́єть чуде́с, к не́йже притека́юще, от вся́кия скве́рни і страсте́й ізбавля́ємся.","Приспів: Преподо́бне о́тче Мака́ріє, моли́ Бо́га о нас.","Огне́м Боже́ственнаго стра́ха ду́шу распали́л єси́, і к сія́нію невече́рнему восте́кл єси́, і ни́ні, блаже́нне, Трисо́лнечним Сві́том озаря́єм.","Слава: Мирськи́я сла́дости возненави́дів, му́жеським нра́вом к подвиго́м устреми́лся єси́ і преподо́бним красота́ лі́потна бил єси́, тім па́м'ять твою́ почита́єм, досточу́дне.","І нині: Низложи́ вознесе́нния і побіди́ полки́ іноплеме́нних, Ді́во Чи́стая, хотя́щия бра́нем, і Твоя́ раби́ невре́дни от них сохрани́, Отрокови́це."]}],"notes":[]},{"u":"Канон праведній Софії, княжні Слуцькій","e":"Canon to the Righteous Sophia, Princess of Sluck","secs":[{"h":"Глас 8. Пісня 1","ps":["Ірмос: Колесницегони́теля фарао́ня погрузи́ чудотворя́й іногда́ Моїсе́йський жезл, крестообра́зно порази́в і разділи́в мо́ре: Ізра́їля же біглеця́, пішехо́дця спасе́, піснь Бо́гові воспіва́юща.","Приспів: Свята́я пра́ведная Софі́є, моли́ Бо́га о нас.","Стра́стними бу́рями всю́ду погружа́єму, і помишле́нії гріхо́вними коле́блему, ко приста́нищу ти́хому Христо́вих за́повідей, моли́твами твої́ми, пра́ведная Софі́є, м'я напра́ви, да досто́йно тя воспою́.","Приспів: Свята́я пра́ведная Софі́є, моли́ Бо́га о нас.","Боже́ственними добро́тами просвіще́на, богоблаже́нная Софі́є, Сло́ву Преві́чному уневі́стилася єси́, пожи́вши богоуго́дні, і Того́ живоно́сним стопа́м послі́довала єси́, ві́ру правосла́вную житіє́м твої́м утвержда́ющи.","Боже́ственних оте́ць наказа́нію послі́довала єси́, сла́вная Софі́є, і сих нра́ву чи́сті поревнова́ла єси́, по зако́ну Бо́жию пра́ведно пожи́вши, до́брими ді́ли Бо́гу угоди́вши, богому́драя, і і́стинним смире́нієм.","Богородичен: Боже́ственную ста́мну і трапе́зу, Хліб живо́тний поне́сшую, неді́ланную ни́ву, го́ру святу́ю, Богоро́дицю Ді́ву пі́сньми просла́вим."]},{"h":"Пісня 3","ps":["Ірмос: Небе́снаго кру́га Верхотво́рче Го́споди, і Це́ркве Зижди́телю, Ти мене́ утверди́ в любві́ Твоє́й, жела́ній кра́ю, ві́рних утвержде́ніє, Єди́не Человіколю́бче.","Приспів: Свята́я пра́ведная Софі́є, моли́ Бо́га о нас.","В Небе́сния черто́ги світоза́рния всели́вшися, ісціле́нія нам рі́ки істоча́єши, прему́драя Софі́є, стра́стная тече́нія ізсуша́ющи.","Приспів: Свята́я пра́ведная Софі́є, моли́ Бо́га о нас.","Украси́лася єси́ жела́нієм кра́йнім, жела́ющи Христа́, премно́жеством благосе́рдія пло́тію обнища́вшаго, і послі́довала єси́ живо́тним Єго́ словесе́м, жите́йськая вся кра́сная возненави́дівши.","Позлаще́нні крилі́ доброді́телі стяжа́вши, на висоту́ Небе́сную возлеті́ла єси́, блаже́нная Софі́є, я́ко голуби́ця непоро́чная.","Богородичен: Род челові́чеський спасе́ся, Всенепоро́чная, всесла́вним Рождество́м Твої́м: ті́мже чтим Тя, і благоче́стно ублажа́єм, Пречи́стая Ді́во Богора́дованная."]},{"h":"Сідален, глас 4","ps":["Добро́тами боже́ственними преукра́шена і нетлі́нієм святи́х моще́й твої́х от Бо́га просла́влена, пра́ведная Софі́є, к Нему́ в нетлі́нний черто́г вошла́ єси́, іді́же мо́лишися непреста́нно спасти́ся от вся́кия біди́ любо́вію тя почита́ющим.","Богородичен: Чи́стая, Всенепоро́чная і Неіскусобра́чная Ді́во, єди́на Безлі́тноє Сло́во Бо́жиє в лі́то ро́ждшая: Того́ со святи́ми і честни́ми апо́столи, му́ченики і проро́ки, і преподо́бними моли́ дарова́ти нам очище́ніє і ве́лію ми́лость."]},{"h":"Пісня 4","ps":["Ірмос: Усли́шах Го́споди, смотре́нія Твоєго́ та́їнство: разумі́х діла́ Твоя́, і просла́вих Твоє́ Божество́.","Приспів: Свята́я пра́ведная Софі́є, моли́ Бо́га о нас.","Сві́тлоє твоє́ торжество́, сві́том Ду́ха Бо́жия сія́ющеє, озаря́єть ду́ші на́ша, ві́рою пою́щих тя, Софі́є пра́ведная.","Приспів: Свята́я пра́ведная Софі́є, моли́ Бо́га о нас.","Чудеси́ боже́ственними уві́рила єси́ неві́дущих Влади́ку Христа́, і к позна́нію Того́ обрати́ла єси́ пре́лести тьму оста́вльших.","Да́ри Христу́ принесла́ єси́, моли́тви і труди́ воздержа́нія: сего́ ра́ди прия́ла єси́ Небе́сноє Ца́рство, Софі́є, і ві́чнующеє наслажде́ніє.","Богородичен: Смири́вши спаси́ м'я, високому́дрієм живу́щаго, ро́ждшая Возне́сшаго смири́вшеєся єстество́ на́ше, Пречи́стая."]},{"h":"Пісня 5","ps":["Ірмос: У́тренююще вопіє́м Ті, Го́споди, спаси́ ни: Ти бо єси́ Бог наш, ра́зві Тебе́ іно́го не ві́ми.","Приспів: Свята́я пра́ведная Софі́є, моли́ Бо́га о нас.","Рука́ма твої́ма преподо́бно воздвиза́ємима к Зижди́телю, ма́ти Софі́є, вра́жия шата́нія низложи́ла єси́.","Приспів: Свята́я пра́ведная Софі́є, моли́ Бо́га о нас.","Удержа́в ру́ку твою́ десну́ю Ви́шній, наста́вил тя єсть, ма́ти, к Небе́сному наслажде́нію.","Стезю́ ті́сную проше́дши в житії́ твоє́м, к широті́ приспі́ла єси́ ра́йстій, Софі́є всечестна́я.","Богородичен: І́же Богоро́дицю Тя неві́дущії, Богома́ти, Сві́та не і́муть ви́діти Ро́ждшагося із Тебе́, Пречи́стая."]},{"h":"Пісня 6","ps":["Ірмос: Ри́зу мні пода́ждь сві́тлу, одія́йся сві́том я́ко ри́зою, многоми́лостиве Христе́ Бо́же наш.","Приспів: Свята́я пра́ведная Софі́є, моли́ Бо́га о нас.","Умертви́вши двиза́нія плотська́я, над страстьми́ вельми́ воцари́лася єси́, і ни́ні, всечи́стая Софі́є, в безстра́стних живе́ши сві́тлостіх.","Приспів: Свята́я пра́ведная Софі́є, моли́ Бо́га о нас.","О́бразу Спа́сову нави́кла єси́ покланя́тися, сла́вная, ді́ли і словеси́ твої́ми спаси́тельная Єго́ соблюда́ющи уче́нія.","О́блак тя Христо́с показа́, ма́ти Софі́є, дождь істоча́ющий живо́тний ві́рою притека́ющим к тебі́, пресла́вная.","Богородичен: Красе́н па́че всіх челові́к Син Твой, Пречи́стая, добро́тою Божества́, а́ще і плоть бисть нас ра́ди."]},{"h":"Кондак, глас 4","ps":["Прийді́те, вся українськия жени́, святу́ю Софі́ю восхва́лим, уподо́бившуюся му́дрим ді́вам, єле́й благода́ті Ду́ха Свята́го стяжа́вшим; ті́мже умудри́ ю Госпо́дь подвиза́тися во утвержде́ніє святи́я правосла́вния ві́ри і соблюда́ти Це́рков Єго́ нези́блему от єресе́й і раско́лов, сего́ ра́ди благода́рні воспої́м єй: ра́дуйся, гра́да Слу́цька і всея́ землі́ на́шея ра́досте і утвержде́ніє."]},{"h":"Ікос","ps":["Струї́ мні сло́ва даждь, Бо́же мой, і істо́чник благочи́нія сотвори́ мой ум, і благослови́ язи́к мой, да воспою́ уго́дницю Твою́ Софі́ю богому́друю, ю́же вінча́л єси́ бла́гостію Твоє́ю: а́ще бо Сам не да́си мі сло́ва досто́йнаго, ка́ко принесу́ дар, ни́щий сий, ті́мже пода́ждь мі си́лу, іспові́дати єя́ по́двиги, крі́пко бо зві́ри ми́сленния побіди́ла єсть. Моли́твами єя́, Спа́се, утверди́ і моя́ помишле́нія."]},{"h":"Пісня 7","ps":["Ірмос: О́троци євре́йстії в пещі́ попра́ша пла́мень дерзнове́нно, і на ро́су огнь преложи́ша, вопію́ще: благослове́н єси́, Го́споди Бо́же, во ві́ки.","Приспів: Свята́я пра́ведная Софі́є, моли́ Бо́га о нас.","О добро́ті тлі́ющей, Софі́є блаже́нная, зді небрегла́ єси́, сматря́ющи та́мо су́щая воздая́нія і світ, і сла́ву Бо́жию нестарі́ющуюся і красоту́, і Боже́ственноє селе́ніє.","Ра́зум боголюби́в стяжа́ла єси́, Софі́є, і, во пло́ті су́щи, А́нгелом уподо́билася єси́, бдя́щи бо́дренне і любо́вію пою́щи: благослове́н єси́, Го́споди Бо́же, во ві́ки.","Богородичен: Виждь скорб мою́, Ді́во, ю́же мі наведе́ мно́жество зол мої́х, і родства́ о́гненнаго ісхити́ м'я, вопію́щаго: благослове́н єси́, Го́споди Бо́же, во ві́ки."]},{"h":"Пісня 8","ps":["Ірмос: Богоглаго́ливії о́троци в пещі́ со огне́м пла́мень попира́юще, поя́ху: благослові́те, діла́ Госпо́дня, Го́спода.","Приспів: Свята́я пра́ведная Софі́є, моли́ Бо́га о нас.","Укра́шена сія́нієм чистоти́, і чи́стим житіє́м просвіще́на, Софі́є Богому́драя, предстої́ши Христу́ Бо́гу на́шему.","Приспів: Свята́я пра́ведная Софі́є, моли́ Бо́га о нас.","Болі́зні разли́чния врачу́єть челові́ков, і отгоня́єть бісо́вськия напа́сти ті́ло твоє́ свято́є, в ра́ці пресла́вно храни́моє.","Свяще́нная же́ртва принесла́ся єси́, і приноше́ніє сві́тлоє, пра́ведная княги́не Софі́є, я́ко кади́ло благоуха́нноє, всіх Влади́ці Христу́ Бо́гу на́шему.","Богородичен: Без істлі́нія Сло́во па́че словесе́ родила́ єси́, тлі́нія вся́каго нас ізбавля́ющеє: сего́ ра́ди Тя, Ді́во, ві́рою велича́єм."]},{"h":"Пісня 9","ps":["Ірмос: Устраши́ся всяк слух неізрече́нна Бо́жия снизхожде́нія, я́ко Ви́шній во́лею сни́де да́же і до пло́ті, от діви́чеськаго чре́ва бив челові́к. Ті́мже Пречи́стую Богоро́дицю ві́рнії велича́єм.","Приспів: Свята́я пра́ведная Софі́є, моли́ Бо́га о нас.","Возжелі́ла єси́ добро́ту ми́сленную Христо́ву, і чи́сто возлюби́ла єси́ Єго́. Гді почива́єши? Гді ли пасе́ши? – те́плі вопія́ла єси́, – да почі́ю у Тебе́, і в Твої́х сві́тлостіх наслажду́ся, велича́ющи Твою́ бла́гость.","Приспів: Свята́я пра́ведная Софі́є, моли́ Бо́га о нас.","Ра́зум імі́ла єси́ в твоє́й душі́, і смире́ніє, і боже́ственную кро́тость, ві́ру несумне́нну, і наде́жду і любо́в, ю́же к Бо́гу, всено́щними моли́твами предстоя́вши Єму́, і Небе́сними сві́тлостьми, блаже́нная Софі́є, озаря́єма і просвіща́єма.","Днесь собра́шася лю́ди хвала́ми возвели́чити Го́спода, возвели́чившаго твоє́ свято́є торжество́: в не́мже помина́й нас, помина́ющих тя, предстоя́щи Христу́, пра́ведная Софі́є і всечестна́я.","Богородичен: Пощади́ м'я, Бо́же, рожде́йся от Ді́ви, єгда́ ся́деши суди́ти діла́ моя́, і Тоя́ моли́твами пре́зри беззако́нія і гріхи́ моя́, я́ко Благ і Многоми́лостив."]},{"h":"Світилен","ps":["Кня́зя утаї́вшися студа́, і сего́ в прему́дростнім о́бразе показа́ безу́мна, жена́ су́щи душе́ю і ті́лом, возсія́ла єси́ я́ко муж ра́зумом і ві́рою, ма́ти Софі́є, жен пра́ведних украше́ніє.","Слава, і нині: День мні возсія́й разу́мнаго весе́лія, Ти бо єси́, Чи́стая, світ і живо́т, су́щих во тьмі: вся бо, а́ще хо́щеши, твори́ти мо́жеши, я́ко су́щи всіх Влади́чиця."]}],"notes":[]}];
export default D;
